// Content for Speak Up (node g19, ages 9-12, Chapter 3): NEW v2 build to GDD 19 (mechanic-embodying), the
// bystander-to-upstander node (Thread E · Gender & Respect). "From bystander to upstander." 85 researched,
// India-grounded scenarios across the name → why → moves → words → help → act arc, each encoded as one of the
// shared v2 play actions (branch / role-play / sort / spot / reflect / strike-rewrite / match): no binary
// "tap the right card", led by the **five-moves chooser** (branch ×25: choose an upstander move, see it play
// out safely; the reference branch engine Stand Up g27 & Defenders of the Body g20 reuse). Teaches: naming
// the forms of gender-based harm (gendered name-calling, exclusion, unwanted touch, body-mocking, online
// hate), why speaking up matters, the **five safe upstander moves** (the 5 Ds: Say something/Direct,
// Distract, Get help/Delegate, Check in/Delay, Report/Document), finding the actual words, where to get help,
// and being the upstander. SAFETY OVER HEROICS (never confront danger alone: "get help" is always honoured);
// NEVER BLAME THE TARGET; TELLING IS NOT TATTLING (help-seeking reframed); FREEZING IS OKAY (a second chance);
// real routes to help (trusted adults, school counsellors, **Childline 1098 / 112**). Builds on g11 (Not Fair,
// Not Funny); prereq g18; pairs g08. Rendered by the shared engine (components/games/v2-engine.tsx).
// gameId "speak-up". DO NOT RENAME.

import type { Scenario, V2GameConfig } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  // Name the harm
  {"id":"su-001","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / naming","hook":"In the corridor. Spot what's harmful.","why":"A gendered insult is harm, even when it's dressed up as 'a joke'.","relearn":"Gendered name-calling is harm, even when called 'a joke'.","scene":[{"id":"a","text":"A boy calls a girl a gendered slur to get laughs","trick":true},{"id":"b","text":"Kids are walking to class","trick":false},{"id":"c","text":"He says \"it's just a joke\"","trick":true},{"id":"d","text":"A monitor hands out notebooks","trick":false},{"id":"e","text":"The bell rings for the next period","trick":false}]},
  {"id":"su-002","cat":"name-the-harm","type":"spot","persona":"Diya","source":"gender-based harm / exclusion","hook":"At the playground. Spot what's harmful.","why":"Shutting someone out because of their gender is harm, not just 'a game'.","relearn":"Excluding someone because of their gender is a form of harm.","scene":[{"id":"a","text":"A group won't let a girl join 'because girls are useless at this'","trick":true},{"id":"b","text":"They're playing cricket","trick":false},{"id":"c","text":"\"Go away, this isn't for you,\" they tell her","trick":true},{"id":"d","text":"A ball rolls off the pitch","trick":false},{"id":"e","text":"Other kids are picking teams","trick":false}]},
  {"id":"su-003","cat":"name-the-harm","type":"spot","persona":"Diya","source":"gender-based harm / bodies","hook":"In class. Spot what's harmful.","why":"Mocking someone's body or puberty is harm that can really hurt.","relearn":"Mocking someone's body or puberty is gender-based harm.","scene":[{"id":"a","text":"Boys snigger and mime about a girl's changing body","trick":true},{"id":"b","text":"The teacher writes on the board","trick":false},{"id":"c","text":"One whispers a cruel name for how she looks now","trick":true},{"id":"d","text":"A fan hums above the desks","trick":false},{"id":"e","text":"Someone sharpens a pencil","trick":false}]},
  {"id":"su-004","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / touch (links g15)","hook":"On the bus. Spot what's harmful.","why":"Touching someone after they've said stop is harm; their 'no' counts.","relearn":"Unwanted touching after a 'no' is harm; the 'no' must be respected.","scene":[{"id":"a","text":"An older kid keeps touching a younger one who's said stop","trick":true},{"id":"b","text":"The bus is crowded","trick":false},{"id":"c","text":"\"Don't be dramatic,\" the older one says, not stopping","trick":true},{"id":"d","text":"The conductor calls out a stop","trick":false},{"id":"e","text":"Bags are stacked in the aisle","trick":false}]},
  {"id":"su-005","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / online (links g12)","hook":"Online. Spot what's harmful.","why":"Spreading a cruel, gendered post is online harm, and forwarding makes it worse.","relearn":"Sharing cruel gendered posts is online harm; forwarding spreads it.","scene":[{"id":"a","text":"Someone shares a mean, gendered meme about a classmate","trick":true},{"id":"b","text":"It's a group chat","trick":false},{"id":"c","text":"Others start forwarding it to more chats","trick":true},{"id":"d","text":"A few people post homework photos","trick":false},{"id":"e","text":"The chat has a class trip plan pinned","trick":false}]},
  {"id":"su-006","cat":"name-the-harm","type":"spot","persona":"Aarav","source":"gender-based harm / norms (links g17)","hook":"In the lane. Spot what's harmful.","why":"Bullying a boy for not fitting a gender mould is gender-based harm too.","relearn":"Bullying someone for not fitting gender norms is harm.","scene":[{"id":"a","text":"A boy is teased and shoved for being 'too girly'","trick":true},{"id":"b","text":"There's a tea stall nearby","trick":false},{"id":"c","text":"\"Real boys aren't like you,\" they jeer","trick":true},{"id":"d","text":"A cycle is parked by the wall","trick":false},{"id":"e","text":"Kids are heading home from school","trick":false}]},
  {"id":"su-007","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / body-shaming","hook":"At a family event. Spot what's harmful.","why":"Repeated 'jokes' about someone's body are harm, even from family.","relearn":"Repeated 'jokes' about a person's body are harmful, even from family.","scene":[{"id":"a","text":"A relative keeps making 'jokes' about a cousin's weight and looks","trick":true},{"id":"b","text":"There's lots of food","trick":false},{"id":"c","text":"He keeps it up even after she goes quiet","trick":true},{"id":"d","text":"Music is playing in the next room","trick":false},{"id":"e","text":"Elders are chatting over tea","trick":false}]},
  {"id":"su-008","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm","hook":"Sort: harm, or okay?","relearn":"Teasing about bodies and gendered slurs are harm; kindness is okay.","items":[{"id":"a","text":"Teasing a girl about her period"},{"id":"b","text":"Inviting everyone to play"},{"id":"c","text":"A gendered slur 'as a joke'"},{"id":"d","text":"Cheering a friend on"},{"id":"e","text":"Mocking a boy for crying"},{"id":"f","text":"Sharing your snack with a classmate"}],"bins":[{"id":"harm","label":"Harm","valence":"neg"},{"id":"okay","label":"Okay","valence":"pos"}],"key":{"a":"harm","b":"okay","c":"harm","d":"okay","e":"harm","f":"okay"}},
  {"id":"su-009","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm","hook":"Sort: harm, or okay?","relearn":"Exclusion and ignoring a 'stop' are harm; asking and disagreeing kindly are okay.","items":[{"id":"a","text":"Leaving someone out for being a girl"},{"id":"b","text":"Disagreeing politely"},{"id":"c","text":"Grabbing someone who said stop"},{"id":"d","text":"Asking before a hug"},{"id":"e","text":"Spreading a gendered rumour"},{"id":"f","text":"Saving a seat for a friend"}],"bins":[{"id":"harm","label":"Harm","valence":"neg"},{"id":"okay","label":"Okay","valence":"pos"}],"key":{"a":"harm","b":"okay","c":"harm","d":"okay","e":"harm","f":"okay"}},
  {"id":"su-010","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm (links g11)","hook":"Sort: a joke everyone enjoys, or harm dressed as a joke?","relearn":"If a 'joke' humiliates one person, it's harm, not fun.","items":[{"id":"a","text":"A silly pun about homework"},{"id":"b","text":"A 'joke' that humiliates one kid's gender"},{"id":"c","text":"A funny story you both laugh at"},{"id":"d","text":"Mocking how a girl's body is changing"},{"id":"e","text":"A wordplay riddle the class enjoys"},{"id":"f","text":"A 'joke' nickname for a boy who cried"}],"bins":[{"id":"fun","label":"Fun for all","valence":"pos"},{"id":"harm","label":"Harm as 'joke'","valence":"neg"}],"key":{"a":"fun","b":"harm","c":"fun","d":"harm","e":"fun","f":"harm"}},
  {"id":"su-011","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm","hook":"Sort: which of these is gender-based harm?","relearn":"Put-downs aimed at someone's gender are gender-based harm.","items":[{"id":"a","text":"\"You can't play, you're a girl\""},{"id":"b","text":"\"Let's take turns\""},{"id":"c","text":"\"Boys like you are pathetic\""},{"id":"d","text":"\"Nice shot!\""},{"id":"e","text":"\"Girls shouldn't speak up like that\""},{"id":"f","text":"\"Want to join our team?\""}],"bins":[{"id":"harm","label":"Gender-based harm","valence":"neg"},{"id":"fine","label":"Just fine","valence":"pos"}],"key":{"a":"harm","b":"fine","c":"harm","d":"fine","e":"harm","f":"fine"}},
  {"id":"su-012","cat":"name-the-harm","type":"strike-rewrite","hook":"\"If it's a joke, it can't be harmful.\"","myth":{"un":"Anything said as a joke can't really be harmful.","re":"A 'joke' that hurts or humiliates someone is still harm.","why":"The harm is in the impact, not the label."},"relearn":"Calling harm 'a joke' doesn't stop it being harm.","persona":"Aarav","source":"naming harm"},
  {"id":"su-013","cat":"name-the-harm","type":"strike-rewrite","hook":"\"If they don't cry, it didn't hurt them.\"","myth":{"un":"If someone doesn't cry, the harm didn't affect them.","re":"People often hide hurt behind a laugh or a blank face.","why":"You can't measure harm by tears alone."},"relearn":"Hidden hurt is still real; don't judge harm by tears.","persona":"any","source":"naming harm / empathy"},
  {"id":"su-014","cat":"name-the-harm","type":"reflect","hook":"Lensy: harm can be words, leaving-out, touching, or online. Recognise the shapes now?","prompt":"What do you think?","options":["Yes","Many shapes","I can spot them"],"affirm":"Harm comes in many shapes; naming it is the first step to stopping it.","relearn":"Gender-based harm takes many shapes: words, exclusion, touch, online.","persona":"any","source":"naming harm"},
  // Why speaking up matters
  {"id":"su-015","cat":"why-speak-up","type":"strike-rewrite","hook":"\"It's none of my business if it's not happening to me.\"","myth":{"un":"If it's not happening to me, it's none of my business.","re":"When you see harm, speaking up is everyone's business.","why":"Silence lets harm continue."},"relearn":"Witnessing harm makes it your business too.","persona":"any","source":"why speak up / allyship"},
  {"id":"su-016","cat":"why-speak-up","type":"strike-rewrite","hook":"\"Telling an adult is just tattling.\"","myth":{"un":"Telling an adult about harm is tattling.","re":"Tattling is to get someone in trouble; telling is to keep someone safe.","why":"Help-seeking for safety is brave, not sneaky."},"relearn":"Telling to keep someone safe is help-seeking, not tattling.","persona":"Asha","source":"why speak up / help-seeking"},
  {"id":"su-017","cat":"why-speak-up","type":"strike-rewrite","hook":"\"If I stay quiet, at least I'm not making it worse.\"","myth":{"un":"Staying silent is the safe, neutral choice.","re":"Silence can let the person being harmed feel alone.","why":"Doing nothing quietly sides with the harm."},"relearn":"Silence isn't neutral; it can leave the target alone.","persona":"any","source":"why speak up / bystander effect"},
  {"id":"su-018","cat":"why-speak-up","type":"strike-rewrite","hook":"\"Someone else will surely step in.\"","myth":{"un":"Someone else is bound to step in, so I don't need to.","re":"When everyone thinks that, no one acts; you can be the one.","why":"This is the bystander trap."},"relearn":"Don't wait for someone else; you can be the one who acts.","persona":"any","source":"why speak up / bystander effect"},
  {"id":"su-019","cat":"why-speak-up","type":"strike-rewrite","hook":"\"The person being harmed must have done something to deserve it.\"","myth":{"un":"If someone's being harmed, they must have asked for it.","re":"Harm is never the fault of the person being hurt.","why":"Blaming the target excuses the person doing harm."},"relearn":"Harm is never the target's fault.","persona":"any","source":"why speak up / no victim-blaming"},
  {"id":"su-020","cat":"why-speak-up","type":"reflect","hook":"Lensy: imagine being harmed and one person stands with you. How much would that matter?","prompt":"What do you think?","options":["A lot","Everything","I'd feel less alone"],"affirm":"One upstander can change everything for the person being harmed.","relearn":"One person standing with you can make all the difference.","persona":"Diya","source":"why speak up / empathy"},
  {"id":"su-021","cat":"why-speak-up","type":"reflect","hook":"Lensy: what kind of bystander do you want to be, the silent one or the upstander?","prompt":"Be honest.","options":["The upstander","The one who helps","Not the silent one"],"affirm":"Choosing to be an upstander is a choice you can make every time.","relearn":"You can choose to be an upstander, not a silent bystander.","persona":"any","source":"why speak up / identity"},
  {"id":"su-022","cat":"why-speak-up","type":"reflect","hook":"Lensy: speaking up can feel scary, and still be worth it. Agree?","prompt":"What do you think?","options":["Yes","Scary but worth it","Brave is okay to be"],"affirm":"Courage isn't feeling unafraid; it's acting even while afraid.","relearn":"Speaking up can feel scary and still be the right, brave thing.","persona":"Aarav","source":"why speak up / courage"},
  {"id":"su-023","cat":"why-speak-up","type":"sort","hook":"Sort: an upstander, or a silent bystander?","items":[{"id":"a","text":"Telling the kids to stop"},{"id":"b","text":"Watching and saying nothing"},{"id":"c","text":"Getting a teacher"},{"id":"d","text":"Laughing along"},{"id":"e","text":"Sitting beside the one left out"},{"id":"f","text":"Filming it for a laugh"}],"bins":[{"id":"up","label":"Upstander","valence":"tell"},{"id":"by","label":"Silent bystander","valence":"neg"}],"key":{"a":"up","b":"by","c":"up","d":"by","e":"up","f":"by"},"relearn":"Upstanders act; silent bystanders watch, laugh, or film.","persona":"any","source":"why speak up"},
  {"id":"su-024","cat":"why-speak-up","type":"sort","hook":"Sort: helps the person harmed, or helps the harm continue?","items":[{"id":"a","text":"Checking if they're okay"},{"id":"b","text":"Forwarding the mean post"},{"id":"c","text":"Sitting with them at lunch"},{"id":"d","text":"Egging it on"},{"id":"e","text":"Walking them to a teacher"},{"id":"f","text":"Sharing the photo to your group"}],"bins":[{"id":"helps","label":"Helps the person","valence":"pos"},{"id":"continues","label":"Helps the harm","valence":"neg"}],"key":{"a":"helps","b":"continues","c":"helps","d":"continues","e":"helps","f":"continues"},"relearn":"Small acts either help the person or help the harm; choose the person.","persona":"any","source":"why speak up"},
  {"id":"su-025","cat":"why-speak-up","type":"branch","hook":"You see harm but think \"maybe I'm overreacting\".","options":[{"text":"Trust that if it looks like harm, it's worth acting on","consequence":"You step in or get help, just in case.","outcome":"upstander","best":true},{"text":"Talk yourself out of it","consequence":"If it looks like harm, it's worth checking, not ignoring."}],"debrief":"It's better to act on a maybe than to ignore real harm.","relearn":"If it looks like harm, act, don't talk yourself out of it.","persona":"any","source":"why speak up"},
  {"id":"su-026","cat":"why-speak-up","type":"branch","hook":"Stepping in might make the bullies turn on you.","options":[{"text":"Pick a safe move: get an adult or distract, not a fight","consequence":"You help without putting yourself in danger.","outcome":"smart","best":true},{"text":"Do nothing out of fear","consequence":"There are safe ways to help that don't mean fighting."}],"debrief":"You can help safely; upstanding isn't the same as fighting.","relearn":"You can help in safe ways, without confronting bullies directly.","persona":"any","source":"why speak up / safety"},
  // The five upstander moves
  {"id":"su-026b","cat":"five-moves","type":"reflect","hook":"Lensy: there are five safe ways to help, the five upstander moves. Want them?","prompt":"What do you think?","options":["Yes please","Teach me","Five tools"],"affirm":"Say something, distract, get help, check in, and report, your toolkit.","relearn":"The upstander toolkit: speak up, distract, get help, check in, report.","persona":"Asha","source":"5 Ds (Right To Be)"},
  {"id":"su-027","cat":"five-moves","type":"branch","hook":"Move 1, SAY SOMETHING. Kids are taunting a classmate; it feels safe to speak.","options":[{"text":"Say calmly \"hey, that's not okay, stop\"","consequence":"Naming it often makes harm pause.","outcome":"direct","best":true},{"text":"Stay quiet","consequence":"A calm 'that's not okay' is the Direct move; it works."}],"debrief":"The Direct move: say plainly that it's not okay, when it's safe.","relearn":"Move 1 (Direct): say calmly that the behaviour isn't okay.","persona":"Aarav","source":"5 Ds / Direct"},
  {"id":"su-028","cat":"five-moves","type":"branch","hook":"Move 2, DISTRACT. Confronting the bullies head-on doesn't feel safe.","options":[{"text":"Break it up: ask the target a random question, drop your books","consequence":"The distraction interrupts the harm safely.","outcome":"distract","best":true},{"text":"Confront the biggest bully alone","consequence":"Direct feels unsafe; Distract interrupts, no clash."}],"debrief":"Distract: derail the moment, no confrontation.","relearn":"Move 2 (Distract): interrupt sideways when direct feels unsafe.","persona":"any","source":"5 Ds / Distract"},
  {"id":"su-029","cat":"five-moves","type":"branch","hook":"Move 3, GET HELP. The harm is serious or scary.","options":[{"text":"Find a teacher or trusted adult fast","consequence":"An adult can step in with authority.","outcome":"delegate","best":true},{"text":"Try to handle a scary situation alone","consequence":"For serious harm, getting an adult (Delegate) is the right move."}],"debrief":"The Delegate move: bring in an adult for anything serious or scary.","relearn":"Move 3 (Delegate): get a trusted adult for serious harm.","persona":"Asha","source":"5 Ds / Delegate"},
  {"id":"su-030","cat":"five-moves","type":"branch","hook":"Move 4, CHECK IN. The moment has passed, but the person looked hurt.","options":[{"text":"Go over later: \"are you okay? that wasn't fair\"","consequence":"They feel seen and less alone.","outcome":"delay","best":true},{"text":"Forget about it","consequence":"Checking in afterward (Delay) really helps the person heal."}],"debrief":"The Delay move: check in afterwards so they don't feel alone.","relearn":"Move 4 (Delay): check in with the person after the harm.","persona":"Diya","source":"5 Ds / Delay"},
  {"id":"su-031","cat":"five-moves","type":"branch","hook":"Move 5, REPORT. There's a cruel post being spread online.","options":[{"text":"Don't forward it; report it and tell an adult","consequence":"You stop the spread and create a record.","outcome":"report","best":true},{"text":"Share it 'to show people'","consequence":"Don't spread it; reporting it safely is the move."}],"debrief":"The Report move: don't spread harm online, report it and tell an adult.","relearn":"Move 5 (Report): report online harm and don't forward it.","persona":"any","source":"5 Ds / Document-report"},
  {"id":"su-032","cat":"five-moves","type":"branch","hook":"You want to help, but which move fits a loud taunt in a safe corridor?","options":[{"text":"A calm Direct \"that's not okay\"","consequence":"Direct fits when it's safe and clear.","outcome":"direct","best":true},{"text":"Secretly film it","consequence":"Here a calm Direct works; filming isn't needed."}],"debrief":"Match the move to the moment; Direct suits a safe, clear situation.","relearn":"Choose the upstander move that fits the situation.","persona":"any","source":"5 Ds / choosing"},
  {"id":"su-033","cat":"five-moves","type":"branch","hook":"A big, aggressive group is harming someone. Which move?","options":[{"text":"Get an adult fast (Delegate), don't go in alone","consequence":"You bring real help without risking yourself.","outcome":"delegate","best":true},{"text":"Jump into the middle of the group","consequence":"For a scary group, Delegate (get an adult) is safest."}],"debrief":"For anything dangerous, Delegate beats going in alone.","relearn":"For dangerous situations, get an adult rather than going in alone.","persona":"any","source":"5 Ds / safety"},
  {"id":"su-034","cat":"five-moves","type":"sort","hook":"Sort the move to its name.","items":[{"id":"a","text":"\"That's not okay, stop\""},{"id":"b","text":"Dropping books to break it up"},{"id":"c","text":"Fetching a teacher"},{"id":"d","text":"\"Are you okay?\" afterwards"},{"id":"e","text":"Asking a sudden question to derail it"},{"id":"f","text":"Sitting with them at lunch later"}],"bins":[{"id":"direct","label":"Direct / Distract","valence":"tell"},{"id":"help","label":"Delegate / Delay","valence":"neutral"}],"key":{"a":"direct","b":"direct","c":"help","d":"help","e":"direct","f":"help"},"relearn":"Speaking up and distracting are one set; getting help and checking in another.","persona":"any","source":"5 Ds"},
  {"id":"su-035","cat":"five-moves","type":"sort","hook":"Sort: a safe upstander move, or risky?","items":[{"id":"a","text":"Getting an adult"},{"id":"b","text":"Fighting the bully"},{"id":"c","text":"Distracting to break it up"},{"id":"d","text":"Threatening them back"},{"id":"e","text":"Checking in afterwards"},{"id":"f","text":"Chasing them down the corridor"}],"bins":[{"id":"safe","label":"Safe move","valence":"pos"},{"id":"risky","label":"Risky move","valence":"neg"}],"key":{"a":"safe","b":"risky","c":"safe","d":"risky","e":"safe","f":"risky"},"relearn":"Upstander moves are designed to help safely, not to fight.","persona":"any","source":"5 Ds / safety"},
  {"id":"su-036","cat":"five-moves","type":"sort","hook":"Sort: which move fits, get help, or check in?","items":[{"id":"a","text":"Serious harm happening now"},{"id":"b","text":"The person looked sad afterwards"},{"id":"c","text":"Something scary you can't stop"},{"id":"d","text":"They're sitting alone, hurt, later"},{"id":"e","text":"A big group cornering someone"},{"id":"f","text":"A friend who went quiet after teasing"}],"bins":[{"id":"gethelp","label":"Get help now","valence":"tell"},{"id":"checkin","label":"Check in after","valence":"neutral"}],"key":{"a":"gethelp","b":"checkin","c":"gethelp","d":"checkin","e":"gethelp","f":"checkin"},"relearn":"Get help during serious harm; check in with the person afterwards.","persona":"any","source":"5 Ds"},
  {"id":"su-037","cat":"five-moves","type":"sort","hook":"Sort: helps safely online, or makes it worse?","items":[{"id":"a","text":"Reporting the post"},{"id":"b","text":"Forwarding it"},{"id":"c","text":"Telling an adult"},{"id":"d","text":"Adding a mean comment"},{"id":"e","text":"Saving a screenshot as proof"},{"id":"f","text":"Tagging more people to see it"}],"bins":[{"id":"helps","label":"Helps safely","valence":"pos"},{"id":"worse","label":"Makes it worse","valence":"neg"}],"key":{"a":"helps","b":"worse","c":"helps","d":"worse","e":"helps","f":"worse"},"relearn":"Report, save proof, and tell an adult; never forward or pile on.","persona":"any","source":"5 Ds / online"},
  {"id":"su-038","cat":"five-moves","type":"role-play","hook":"You choose the Direct move on a taunt.","setup":"Say it calm and clear:","yourLine":[{"text":"\"That's not okay. Leave them alone.\"","best":true},{"text":"\"...\" (say nothing)"}],"relearn":"A calm, clear 'that's not okay' is a strong Direct move.","persona":"Aarav","source":"5 Ds / Direct voice"},
  {"id":"su-039","cat":"five-moves","type":"role-play","hook":"You use the Distract move.","setup":"Break the moment naturally. Say:","yourLine":[{"text":"\"Hey, the teacher's looking for you, come on.\"","best":true},{"text":"\"Carry on then.\""}],"relearn":"A casual interruption is an effective, safe Distract.","persona":"any","source":"5 Ds / Distract voice"},
  {"id":"su-040","cat":"five-moves","type":"role-play","hook":"You use the Check-in move afterwards.","setup":"Be warm. Say:","yourLine":[{"text":"\"That wasn't fair on you. Are you okay?\"","best":true},{"text":"Avoid them so it's not awkward"}],"relearn":"A warm 'are you okay?' afterwards helps the person feel less alone.","persona":"Diya","source":"5 Ds / Delay voice"},
  {"id":"su-041","cat":"five-moves","type":"reflect","hook":"Lensy: five moves means you've always got at least one safe option. Reassuring?","prompt":"What do you think?","options":["Yes","Always an option","I can always help"],"affirm":"With five moves, there's always a safe way to help.","relearn":"With five moves, you can always find a safe way to help.","persona":"any","source":"5 Ds"},
  {"id":"su-042","cat":"five-moves","type":"reflect","hook":"Lensy: which move feels most like 'you'?","prompt":"Pick one.","options":["Say something","Distract","Get help","Check in"],"affirm":"Start with the move that fits you; you can grow the others.","relearn":"Start with the upstander move that feels most natural to you.","persona":"any","source":"5 Ds"},
  // Find the words
  {"id":"su-043","cat":"find-the-words","type":"role-play","hook":"A friend is being called a gendered name.","setup":"Step in for them. Say:","yourLine":[{"text":"\"Don't call them that. Not cool.\"","best":true},{"text":"Laugh nervously"}],"relearn":"A short, firm line can stop name-calling in its tracks.","persona":"any","source":"upstander voice"},
  {"id":"su-044","cat":"find-the-words","type":"role-play","hook":"A girl is being shut out of the game.","setup":"Open the door. Say:","yourLine":[{"text":"\"She's on my team. Let's play.\"","best":true},{"text":"\"Guess she can't play.\""}],"relearn":"Inviting someone in is a powerful upstander move.","persona":"Diya","source":"upstander voice / inclusion"},
  {"id":"su-045","cat":"find-the-words","type":"role-play","hook":"People are mocking a boy for being gentle.","setup":"Back him up. Say:","yourLine":[{"text":"\"Being kind isn't something to mock.\"","best":true},{"text":"Join in so you fit in"}],"relearn":"You can defend someone mocked for not fitting a gender mould.","persona":"Aarav","source":"upstander voice / norms"},
  {"id":"su-046","cat":"find-the-words","type":"role-play","hook":"A classmate is being teased about her changing body.","setup":"Shut it down kindly. Say:","yourLine":[{"text":"\"Everyone's body changes. Leave her alone.\"","best":true},{"text":"Snigger along"}],"relearn":"Normalising bodies while defending someone stops body-teasing.","persona":"Diya","source":"upstander voice / bodies"},
  {"id":"su-047","cat":"find-the-words","type":"role-play","hook":"Friends want you to forward a cruel post.","setup":"Refuse clearly. Say:","yourLine":[{"text":"\"I'm not sending that. It's mean.\"","best":true},{"text":"\"Okay, sending.\""}],"relearn":"You can refuse to forward harm, out loud.","persona":"any","source":"upstander voice / online"},
  {"id":"su-048","cat":"find-the-words","type":"role-play","hook":"You need to tell a teacher about ongoing harm.","setup":"Report it clearly. Say:","yourLine":[{"text":"\"Miss, something's happening that someone needs help with.\"","best":true},{"text":"Keep it to yourself"}],"relearn":"You can clearly ask a trusted adult to step in.","persona":"Asha","source":"upstander voice / help"},
  {"id":"su-049","cat":"find-the-words","type":"role-play","hook":"The person doing harm says \"why do you even care?\"","setup":"Hold steady. Say:","yourLine":[{"text":"\"Because it's not okay, that's why.\"","best":true},{"text":"\"...sorry, never mind.\""}],"relearn":"You can stand by your reason for speaking up.","persona":"any","source":"upstander voice / steady"},
  {"id":"su-050","cat":"find-the-words","type":"role-play","hook":"You froze the first time; now you get another chance.","setup":"Try again. Say:","yourLine":[{"text":"\"Hey, stop, that's enough.\"","best":true},{"text":"Freeze again"}],"relearn":"Freezing once is okay; you can find your voice next time.","persona":"Aarav","source":"upstander voice / second chance"},
  {"id":"su-051","cat":"find-the-words","type":"role-play","hook":"You want to support the target without making a scene.","setup":"Quietly ally. Say:","yourLine":[{"text":"\"Come sit with us.\"","best":true},{"text":"Pretend not to notice"}],"relearn":"A quiet 'come sit with us' is a gentle, real upstander move.","persona":"Diya","source":"upstander voice / quiet ally"},
  {"id":"su-052","cat":"find-the-words","type":"branch","hook":"You've got the words ready but your heart is pounding.","options":[{"text":"Take a breath and say your line anyway","consequence":"You act through the nerves; it gets easier.","outcome":"brave","best":true},{"text":"Swallow the words","consequence":"Breathe and say it; courage grows with each try."}],"debrief":"Nerves are normal; say your line anyway.","relearn":"You can speak up even with your heart pounding.","persona":"any","source":"upstander voice / courage"},
  {"id":"su-053","cat":"find-the-words","type":"branch","hook":"Your first line didn't work; the harm continues.","options":[{"text":"Switch moves: now go get an adult","consequence":"You escalate to help instead of giving up.","outcome":"persistent","best":true},{"text":"Give up because one try failed","consequence":"If one move fails, switch to another, like getting help."}],"debrief":"If one move doesn't work, switch to another.","relearn":"If your first move fails, switch to another, like getting help.","persona":"any","source":"upstander voice / persistence"},
  {"id":"su-054","cat":"find-the-words","type":"reflect","hook":"Lensy: having a line ready makes it easier to use in the moment. Worth practising?","prompt":"What do you think?","options":["Yes","I'll practise","Ready lines help"],"affirm":"A rehearsed line comes out far more easily under pressure.","relearn":"Practising a ready line helps you use it in the moment.","persona":"any","source":"upstander voice / rehearsal"},
  // Where to get help
  {"id":"su-055","cat":"get-help","type":"match","hook":"Match the situation to who can help.","pairs":[{"left":"Harm at school","right":"A trusted teacher"},{"left":"Harm at home","right":"A trusted adult or relative"},{"left":"A serious emergency","right":"Childline 1098 / 112"},{"left":"You feel low and need to talk","right":"A school counsellor"},{"left":"Harm on the bus or street","right":"Any safe grown-up nearby"}],"relearn":"Different situations have the right helper; know who to turn to.","persona":"Asha","source":"get help / UNESCO 5.5"},
  {"id":"su-056","cat":"get-help","type":"match","hook":"Match the helper to what they can do.","pairs":[{"left":"School counsellor","right":"Listen and support privately"},{"left":"Parent or guardian","right":"Step in and protect"},{"left":"Childline 1098","right":"24-hour help for children"},{"left":"Class teacher","right":"Sort out trouble in school"},{"left":"Asha, the NGO didi","right":"A near-peer you can confide in"}],"relearn":"Counsellors, parents and Childline 1098 each offer real help.","persona":"any","source":"get help / UNESCO 5.5"},
  {"id":"su-057","cat":"get-help","type":"match","hook":"Match the worry to a first step.","pairs":[{"left":"Scared to tell alone","right":"Bring a friend with you"},{"left":"Don't know who to trust","right":"Pick any safe adult to start"},{"left":"It's urgent and scary","right":"Call 1098 or 112"},{"left":"Words won't come out","right":"Write it down and hand it over"},{"left":"Worried no one will listen","right":"Keep telling till one adult acts"}],"relearn":"There's always a first step to getting help, even when it's hard.","persona":"Diya","source":"get help"},
  {"id":"su-058","cat":"get-help","type":"match","hook":"Match the reason to what it really is.","pairs":[{"left":"To get someone in trouble","right":"That's tattling"},{"left":"To keep someone safe","right":"That's telling"},{"left":"Reporting serious harm","right":"Telling that protects"},{"left":"Just to land a friend in a scolding","right":"Tattling, not telling"},{"left":"Because a child could get hurt","right":"Telling that matters"}],"relearn":"Telling keeps people safe; that's different from tattling.","persona":"any","source":"get help / help-seeking"},
  {"id":"su-059","cat":"get-help","type":"branch","hook":"You told one adult and nothing changed.","options":[{"text":"Tell another trusted adult, keep going until someone helps","consequence":"Persistence gets the harm taken seriously.","outcome":"persistent","best":true},{"text":"Give up, assuming no one will help","consequence":"If one adult doesn't act, tell another, don't give up."}],"debrief":"If the first adult doesn't help, tell another, and another.","relearn":"Keep telling trusted adults until someone helps.","persona":"Asha","source":"get help / persistence"},
  {"id":"su-060","cat":"get-help","type":"branch","hook":"A friend is being harmed but begs you not to tell anyone.","options":[{"text":"For serious harm, tell a trusted adult anyway, kindly","consequence":"You keep them safe even if they're upset for now.","outcome":"caring","best":true},{"text":"Promise to keep the secret","consequence":"Safety comes before a secret; tell a trusted adult."}],"debrief":"Some secrets aren't safe to keep; safety comes first.","relearn":"For serious harm, tell a trusted adult even if asked to keep it secret.","persona":"any","source":"get help / safe vs unsafe secrets (links g08)"},
  {"id":"su-061","cat":"get-help","type":"branch","hook":"You're not totally sure if it counts as 'serious enough' to report.","options":[{"text":"Ask a trusted adult; let them help you decide","consequence":"You get guidance instead of guessing alone.","outcome":"resourceful","best":true},{"text":"Decide alone it's probably nothing","consequence":"When unsure, a trusted adult can help you judge."}],"debrief":"When unsure, asking an adult is itself a smart move.","relearn":"When unsure if harm is 'serious enough', ask a trusted adult.","persona":"any","source":"get help"},
  {"id":"su-062","cat":"get-help","type":"branch","hook":"The harm is happening online to you or a friend.","options":[{"text":"Save proof, don't reply, and tell a trusted adult","consequence":"You handle it safely and get backup.","outcome":"savvy","best":true},{"text":"Fight back in the comments","consequence":"Save proof and tell an adult; don't get pulled into a fight."}],"debrief":"For online harm: keep proof, don't engage, tell an adult.","relearn":"For online harm, save proof, don't reply, and tell a trusted adult.","persona":"any","source":"get help / online (links g12)"},
  {"id":"su-063","cat":"get-help","type":"strike-rewrite","hook":"\"Asking for help means I'm weak.\"","myth":{"un":"Asking for help means I'm weak.","re":"Asking for help is a smart, strong thing to do.","why":"Even the bravest people get backup."},"relearn":"Asking for help is strong and smart, not weak.","persona":"Aarav","source":"get help / help-seeking"},
  {"id":"su-064","cat":"get-help","type":"strike-rewrite","hook":"\"Adults never do anything anyway.\"","myth":{"un":"There's no point telling adults; they never help.","re":"Many adults will help; if one doesn't, another will.","why":"You may need to find the right adult."},"relearn":"Many adults will help; keep looking for the right one.","persona":"any","source":"get help"},
  {"id":"su-065","cat":"get-help","type":"sort","hook":"Sort: a trusted helper, or not a safe choice?","items":[{"id":"a","text":"A teacher you trust"},{"id":"b","text":"A stranger online offering to 'sort it'"},{"id":"c","text":"A parent or guardian"},{"id":"d","text":"The person doing the harm"},{"id":"e","text":"A school counsellor"},{"id":"f","text":"An older bully who says he'll 'handle it'"}],"bins":[{"id":"trusted","label":"Trusted helper","valence":"pos"},{"id":"not","label":"Not safe","valence":"neg"}],"key":{"a":"trusted","b":"not","c":"trusted","d":"not","e":"trusted","f":"not"},"relearn":"Turn to trusted adults, not strangers or the person causing harm.","persona":"any","source":"get help / who to trust"},
  {"id":"su-066","cat":"get-help","type":"sort","hook":"Sort: a good time to call 1098 / 112, or handle another way?","items":[{"id":"a","text":"A child is in danger right now"},{"id":"b","text":"A small disagreement over a game"},{"id":"c","text":"Someone is being seriously hurt"},{"id":"d","text":"You don't like the homework"},{"id":"e","text":"A child is being threatened and is scared"},{"id":"f","text":"Two friends are sulking after an argument"}],"bins":[{"id":"call","label":"Call for help","valence":"tell"},{"id":"other","label":"Handle another way","valence":"neutral"}],"key":{"a":"call","b":"other","c":"call","d":"other","e":"call","f":"other"},"relearn":"Helplines like 1098/112 are for real danger and serious harm.","persona":"any","source":"get help / helpline"},
  {"id":"su-067","cat":"get-help","type":"role-play","hook":"You're helping a friend make the call for help.","setup":"Encourage them. Say:","yourLine":[{"text":"\"I'll be right here with you while you tell them.\"","best":true},{"text":"\"You're on your own with this.\""}],"relearn":"Being beside someone makes asking for help far easier.","persona":"Diya","source":"get help / support"},
  {"id":"su-068","cat":"get-help","type":"role-play","hook":"You decide to tell a trusted adult about ongoing harm.","setup":"Open clearly. Say:","yourLine":[{"text":"\"I need to tell you something to keep someone safe.\"","best":true},{"text":"Hint vaguely and hope they guess"}],"relearn":"Opening clearly helps a trusted adult understand and act.","persona":"any","source":"get help / voice"},
  // Be the upstander
  {"id":"su-069","cat":"be-the-upstander","type":"branch","hook":"Capstone: a girl is cornered and teased by a group; it's loud but not physical.","options":[{"text":"Distract to break it up, then check she's okay","consequence":"You interrupt safely and support her.","outcome":"upstander","best":true},{"text":"Watch from a distance","consequence":"A distract-then-check-in combo helps without a clash."}],"debrief":"Pair moves: distract in the moment, check in afterwards.","relearn":"You can combine upstander moves: distract, then check in.","persona":"Diya","source":"upstander / combo"},
  {"id":"su-070","cat":"be-the-upstander","type":"branch","hook":"A boy is being shoved and called slurs; it's turning physical.","options":[{"text":"Get an adult immediately","consequence":"You bring help for a dangerous situation.","outcome":"delegate","best":true},{"text":"Jump in to fight them off","consequence":"When it's physical and dangerous, get an adult fast."}],"debrief":"Physical danger calls for an adult, not a solo rescue.","relearn":"When harm turns physical, get an adult immediately.","persona":"Aarav","source":"upstander / safety"},
  {"id":"su-071","cat":"be-the-upstander","type":"branch","hook":"Your own friend is the one doing the harm.","options":[{"text":"Tell your friend honestly it's not okay","consequence":"A real friend can hear the truth from you.","outcome":"honest","best":true},{"text":"Let it slide because they're your friend","consequence":"Being a true friend includes telling them when they're wrong."}],"debrief":"Upstanding sometimes means correcting your own friend.","relearn":"You can tell even a friend that their harm isn't okay.","persona":"any","source":"upstander / friends"},
  {"id":"su-072","cat":"be-the-upstander","type":"branch","hook":"You're scared that helping will make you the next target.","options":[{"text":"Choose a safe move (get help, distract) so you help and stay safe","consequence":"You protect the target and yourself.","outcome":"smart","best":true},{"text":"Do nothing out of fear","consequence":"Safe moves let you help without becoming a target."}],"debrief":"Your safety matters too; pick the move that protects everyone.","relearn":"Choose safe moves so you can help without endangering yourself.","persona":"any","source":"upstander / safety"},
  {"id":"su-073","cat":"be-the-upstander","type":"branch","hook":"Everyone else is just watching the harm happen.","options":[{"text":"Be the first to act; others often join once someone starts","consequence":"Your move gives others courage to help too.","outcome":"leader","best":true},{"text":"Wait with the crowd","consequence":"Someone has to be first; it can be you, and others follow."}],"debrief":"The first upstander often unfreezes the whole crowd.","relearn":"Being the first to act can free others to help too.","persona":"any","source":"upstander / leadership"},
  {"id":"su-074","cat":"be-the-upstander","type":"branch","hook":"You helped once and it worked. Now it's happening again, to someone else.","options":[{"text":"Step up again, you know you can","consequence":"You become a reliable upstander.","outcome":"consistent","best":true},{"text":"Feel you've 'done your bit' already","consequence":"Upstanding is a habit, not a one-time act."}],"debrief":"Being an upstander is something you keep choosing.","relearn":"Upstanding is an ongoing habit, not a one-off.","persona":"any","source":"upstander / habit"},
  {"id":"su-075","cat":"be-the-upstander","type":"branch","hook":"You witness subtle harm: a sly gendered 'joke' that lands hard.","options":[{"text":"Name it lightly: \"that's not really funny, though\"","consequence":"You flag it without a big confrontation.","outcome":"direct","best":true},{"text":"Let it pass as 'just a joke'","consequence":"Even subtle harm can be named, lightly."}],"debrief":"Quiet harm deserves a quiet upstander too.","relearn":"You can gently name subtle harm, not just obvious harm.","persona":"any","source":"upstander / subtle"},
  {"id":"su-076","cat":"be-the-upstander","type":"branch","hook":"A younger child is being harmed and looks to you.","options":[{"text":"Step in and get them to a trusted adult","consequence":"You protect a younger kid who needs you.","outcome":"protector","best":true},{"text":"Decide it's not your problem","consequence":"A younger child needs an older one to step up."}],"debrief":"Older kids can be powerful upstanders for younger ones.","relearn":"You can step up to protect a younger child.","persona":"Asha","source":"upstander / mentoring"},
  {"id":"su-077","cat":"be-the-upstander","type":"branch","hook":"You realise you once laughed along at harm. You see it again now.","options":[{"text":"Do it differently this time, speak up","consequence":"You grow from bystander to upstander.","outcome":"growth","best":true},{"text":"Laugh along again","consequence":"You can change; this time, be the upstander."}],"debrief":"You can change from bystander to upstander any time.","relearn":"You can choose differently and become an upstander.","persona":"Aarav","source":"upstander / growth"},
  {"id":"su-078","cat":"be-the-upstander","type":"branch","hook":"Capstone: online, a friend is being targeted with gendered hate.","options":[{"text":"Don't share it, report it, save proof, and tell an adult","consequence":"You use the safe online toolkit fully.","outcome":"upstander","best":true},{"text":"Reply with insults to defend them","consequence":"Report, save proof, and tell an adult; don't fuel the fight."}],"debrief":"Online upstanding: report, preserve proof, tell an adult, never pile on.","relearn":"Online: report, save proof, tell an adult, and don't pile on.","persona":"any","source":"upstander / online"},
  {"id":"su-079","type":"spot","scene":[{"id":"a","text":"One kid quietly fetches a teacher","trick":false},{"id":"b","text":"Most are filming for laughs","trick":true},{"id":"c","text":"Another goes to sit with the target","trick":false},{"id":"d","text":"Some chant to egg the teasers on","trick":true},{"id":"e","text":"A few just stand and watch","trick":false}],"why":"Filming and chanting egg the teasing on; getting help and sitting with the target are what upstanders do.","cat":"be-the-upstander","persona":"any","source":"upstander / spotting","relearn":"Filming and chanting egg harm on; upstanders get help and support the target.","hook":"A scene with many people. Spot the two egging it on."},
  {"id":"su-080","type":"spot","scene":[{"id":"a","text":"Someone sits with the hurt kid","trick":false},{"id":"b","text":"A kid copies the teasing to get a laugh","trick":true},{"id":"c","text":"Someone says \"want to tell a teacher together?\"","trick":false},{"id":"d","text":"A kid retells the teasing, laughing","trick":true},{"id":"e","text":"Others walk past without looking","trick":false}],"why":"Copying and retelling the teasing for a laugh keep it going.","cat":"be-the-upstander","persona":"Diya","source":"upstander / care","relearn":"Copying or retelling harm keeps it going; sitting with someone or offering help matters.","hook":"After the harm. Spot the two that keep it going."},
  {"id":"su-081","type":"spot","scene":[{"id":"a","text":"You could quietly get the nearby teacher","trick":false},{"id":"b","text":"You could wave the teacher over from here","trick":false},{"id":"c","text":"You could jump into the middle","trick":true},{"id":"d","text":"You could distract them: \"sir wants everyone\"","trick":false},{"id":"e","text":"You could challenge the biggest one","trick":true}],"why":"With bigger bullies, jumping in or challenging isn't safe; get a teacher or distract.","cat":"be-the-upstander","persona":"any","source":"upstander / safety","relearn":"When outmatched, get an adult or distract; don't fight.","hook":"Bigger bullies. Spot the two unsafe moves."},
  {"id":"su-082","cat":"be-the-upstander","type":"strike-rewrite","hook":"\"I'm just a kid, I can't make a difference.\"","myth":{"un":"I'm just a kid; I can't make a difference to harm.","re":"Kids are upstanders every day; your action counts.","why":"Even one small safe move can change someone's day."},"relearn":"Even as a kid, your upstander action makes a real difference.","persona":"any","source":"upstander / agency"},
  {"id":"su-083","cat":"be-the-upstander","type":"reflect","hook":"Lensy: biggest take-away from Speak Up?","prompt":"Pick your motto.","options":["Name the harm","Pick a safe move","Telling isn't tattling","Be the upstander"],"affirm":"You can spot harm, choose a safe move, and help, every time.","relearn":"Spot the harm, choose a safe move, get help, be the upstander.","persona":"any","source":"consolidation"},
  {"id":"su-084","cat":"be-the-upstander","type":"reflect","hook":"Lensy: knowing the five moves and 1098, do you feel ready to help?","prompt":"What do you think?","options":["Ready","Yes","I know what to do"],"affirm":"You've got the moves and the helplines, you're ready to be an upstander.","relearn":"With the five moves and helplines, you're ready to help safely.","persona":"any","source":"consolidation"},
  {"id":"su-900","type":"branch","options":[{"text":"Sit beside her and say loudly, \"leave her alone\"","consequence":"You break their game and she isn't alone.","best":true,"outcome":"upstander"},{"text":"Look out the window and pretend not to see","consequence":"Sitting with her and a firm line breaks it without a fight."}],"debrief":"Moving next to the target and naming it can stop teasing fast.","cat":"be-the-upstander","persona":"Diya","source":"upstander / bus","relearn":"Sitting with someone and naming harm is a safe upstander move.","hook":"On the school bus, boys keep flicking a girl's dupatta and laughing."},
  {"id":"su-901","type":"branch","options":[{"text":"Distract: \"Sir's calling everyone\" so she can slip away","consequence":"The chant breaks and she gets away safely.","best":true,"outcome":"distract"},{"text":"Tell her to just use a different tap","consequence":"A quick distraction breaks the moment without a clash."}],"debrief":"When a direct line feels risky, a distraction breaks the crowd.","cat":"be-the-upstander","persona":"Diya","source":"upstander / period-teasing","relearn":"Distract breaks a harmful moment when direct feels unsafe.","hook":"At the tap, three boys block a girl, chanting she's 'unclean' for having her period."},
  {"id":"su-902","type":"branch","options":[{"text":"Stand by him: \"crying isn't only for girls, back off\"","consequence":"You break the chant and he isn't alone in it.","best":true,"outcome":"direct"},{"text":"Laugh quietly so they don't turn on you","consequence":"Standing beside him and naming it is the upstander move."}],"debrief":"Gentle boys are not weak; naming the chant stops it.","cat":"be-the-upstander","persona":"Aarav","source":"upstander / gentle-boy","relearn":"You can defend a boy mocked as 'girly' without joining in.","hook":"A boy in your class cried after a film. Now others mob him chanting 'ladki, ladki'."},
  {"id":"su-903","type":"branch","options":[{"text":"Get the ground teacher right away","consequence":"An adult stops the grabbing and keeps her safe.","best":true,"outcome":"delegate"},{"text":"Tell him she clearly doesn't like it and hope he stops","consequence":"Unwanted touching that won't stop needs an adult, fast."}],"debrief":"Unwanted touching is serious; the safe move is to get an adult.","cat":"be-the-upstander","persona":"any","source":"upstander / touching","relearn":"When touching won't stop, get an adult immediately.","hook":"On the playground, a boy keeps grabbing a girl's wrist 'for fun'. She keeps pulling away."},
  {"id":"su-904","type":"branch","options":[{"text":"Invite her into your game and learn one word of her language","consequence":"She's included and the mocking loses its audience.","best":true,"outcome":"include"},{"text":"Feel sorry for her but say nothing","consequence":"Including her is itself an upstander act."}],"debrief":"Including a left-out child is a real upstander move.","cat":"be-the-upstander","persona":"any","source":"upstander / exclusion","relearn":"Including someone who's excluded is being an upstander.","hook":"A new girl who speaks a different language is left out of every game. Others mimic her accent."},
  {"id":"su-905","type":"branch","options":[{"text":"Run and fetch a teacher now","consequence":"You bring an adult for a dangerous, physical scene.","best":true,"outcome":"delegate"},{"text":"Shout at the seniors to stop and stand in front","consequence":"When it's physical and seniors are bigger, get an adult fast."}],"debrief":"Physical, scary harm calls for an adult, never a solo stand.","cat":"be-the-upstander","persona":"Aarav","source":"upstander / safety","relearn":"When harm is physical and scary, get an adult, don't fight alone.","hook":"Seniors corner a junior boy, calling him a slur and shoving. It's getting rough."},
  {"id":"su-906","type":"branch","options":[{"text":"Don't forward it; screenshot it and show a teacher","consequence":"You keep proof and bring an adult, without spreading it.","best":true,"outcome":"report"},{"text":"Add a comment telling them off in the group","consequence":"Save proof and tell an adult; replying just fuels it."}],"debrief":"Online harm: save proof, tell an adult, don't forward.","cat":"be-the-upstander","persona":"any","source":"upstander / online","relearn":"Online: save proof and tell an adult; don't forward harm.","hook":"In the class group, someone posts a mean edited photo of a girl. Others pile on."},
  {"id":"su-907","type":"branch","options":[{"text":"Sit with her: \"that was unfair, are you okay?\"","consequence":"She feels less alone and knows it wasn't her fault.","best":true,"outcome":"delay"},{"text":"Give her space and walk on","consequence":"Checking in afterwards is a real upstander move too."}],"debrief":"Checking in afterwards tells someone the harm wasn't their fault.","cat":"be-the-upstander","persona":"Diya","source":"upstander / check-in","relearn":"Checking in after the moment is its own upstander move.","hook":"After a girl is teased about her body, the crowd drifts off. She's sitting alone, blinking back tears."},
  {"id":"su-908","type":"branch","options":[{"text":"Tell your friend quietly later, \"that's not okay, stop it\"","consequence":"A real friend can hear the truth from you.","best":true,"outcome":"honest"},{"text":"Laugh so your friend doesn't feel embarrassed","consequence":"Being a true friend includes telling them when they're wrong."}],"debrief":"You can tell even a close friend their harm isn't okay.","cat":"be-the-upstander","persona":"any","source":"upstander / friends","relearn":"A real upstander can correct even their own friend.","hook":"Your best friend is the one calling a quieter boy 'gay' to get laughs."},
  {"id":"su-909","type":"branch","options":[{"text":"Say it plainly: \"that's not a rule, anyone can lead\"","consequence":"You name the unfair idea and others rethink it.","best":true,"outcome":"direct"},{"text":"Stay quiet because everyone seems to agree","consequence":"Excluding someone for their gender is harm, not a rule."}],"debrief":"\"Girls can't lead\" is harm dressed as a rule; you can name it.","cat":"be-the-upstander","persona":"any","source":"upstander / exclusion","relearn":"You can name gender exclusion even when the crowd agrees.","hook":"A girl is told she can't be team captain 'because girls can't lead'."},
  {"id":"su-910","type":"branch","options":[{"text":"Try again now: even a small \"hey, stop\" counts","consequence":"You act through the fear; freezing once doesn't define you.","best":true,"outcome":"growth"},{"text":"Decide you're just not brave enough and look away","consequence":"Freezing once is okay; courage is trying again now."}],"debrief":"Freezing once is okay; you get a second chance to act.","cat":"be-the-upstander","persona":"Aarav","source":"upstander / second-chance","relearn":"You can try again after freezing; courage is acting through fear.","hook":"You froze last week when a boy was mocked. Today it's happening again."},
  {"id":"su-911","type":"branch","options":[{"text":"Be the first: walk over and ask her to come with you","consequence":"Your move gives others courage to step in too.","best":true,"outcome":"leader"},{"text":"Wait to see if a bigger kid handles it","consequence":"Someone has to be first; it can be you, and others follow."}],"debrief":"Being first to act can unfreeze a whole watching crowd.","cat":"be-the-upstander","persona":"any","source":"upstander / first","relearn":"You can be the first upstander; you don't have to wait.","hook":"Everyone in the corridor is just watching a girl get cornered and teased. Nobody moves."},
  {"id":"su-912","type":"branch","options":[{"text":"Tell him after class his answer was good, and check he's okay","consequence":"He feels backed and less alone with the mocking.","best":true,"outcome":"delay"},{"text":"Think the teacher should handle it, not you","consequence":"Quietly backing a mocked classmate is an upstander move."}],"debrief":"Backing a mocked classmate afterwards is upstanding.","cat":"be-the-upstander","persona":"any","source":"upstander / check-in","relearn":"You can check in and back a classmate who's being mocked.","hook":"A boy who stammers is mocked whenever he answers. Today he won't raise his hand."},
  {"id":"su-913","type":"branch","options":[{"text":"Pull him into the dance so it stops being about him","consequence":"The teasing fizzles and he's included, not the joke.","best":true,"outcome":"distract"},{"text":"Tell him to ignore them and sit down","consequence":"Distracting and including him breaks the teasing kindly."}],"debrief":"Including someone shifts a moment away from the teasing.","cat":"be-the-upstander","persona":"any","source":"upstander / family","relearn":"Pulling someone in can include them and end the teasing.","hook":"At a wedding, older cousins tease your shy cousin for 'dancing like a girl'."},
  {"id":"su-914","type":"branch","options":[{"text":"Grab it back, hand it to her, and say \"grow up\" to them","consequence":"She gets it back and the spectacle ends.","best":true,"outcome":"direct"},{"text":"Pretend you didn't notice to save her embarrassment","consequence":"Ending the spectacle and returning her pad is the kind move."}],"debrief":"Stepping in to end period-mocking is a real upstander move.","cat":"be-the-upstander","persona":"Diya","source":"upstander / period-teasing","relearn":"You can step in to stop period-mocking and help her quietly.","hook":"A girl drops her sanitary pad and boys snatch it, waving it around."},
  {"id":"su-915","type":"branch","options":[{"text":"Tell them the swing is shared and help her take her turn","consequence":"You protect a younger kid and the 'boys first' line fails.","best":true,"outcome":"protector"},{"text":"Decide little kids should sort it out themselves","consequence":"An older kid stepping in helps a younger one stand up."}],"debrief":"Older kids can be upstanders for younger ones.","cat":"be-the-upstander","persona":"Asha","source":"upstander / younger","relearn":"You can step up to protect a younger child from unfairness.","hook":"A younger child is made to give up the swing because 'boys go first'."},
  {"id":"su-916","type":"branch","options":[{"text":"Step up again, the same way; you know it works","consequence":"You become a reliable upstander, not a one-off helper.","best":true,"outcome":"consistent"},{"text":"Feel you've done your bit already and stay out of it","consequence":"Upstanding is a habit you keep choosing, not a one-time act."}],"debrief":"Upstanding is an ongoing habit, not a single act.","cat":"be-the-upstander","persona":"any","source":"upstander / habit","relearn":"Being an upstander is something you keep choosing.","hook":"Helping that girl yesterday worked. Now a different kid is being teased the same way."},
  {"id":"su-917","type":"branch","options":[{"text":"Name it lightly: \"that's not really fair, though\"","consequence":"You flag the dig without a big confrontation.","best":true,"outcome":"direct"},{"text":"Let it slide as harmless","consequence":"Even subtle, sly harm can be named lightly."}],"debrief":"You can gently name subtle harm, not just the obvious kind.","cat":"be-the-upstander","persona":"any","source":"upstander / subtle","relearn":"Quiet, sly harm deserves a quiet upstander too.","hook":"A sly comment lands: \"she only got picked because she's a girl.\" A few smirk."},
  {"id":"su-918","type":"branch","options":[{"text":"Refuse, report the post, and tell a trusted adult","consequence":"You stop the spread and bring help, without piling on.","best":true,"outcome":"report"},{"text":"Share it once 'just so she knows what's going on'","consequence":"Don't forward it; report and tell an adult instead."}],"debrief":"Don't forward harmful content; report and tell an adult.","cat":"be-the-upstander","persona":"any","source":"upstander / online","relearn":"Online: don't forward, report, tell a trusted adult.","hook":"A girl's photo is passed around with cruel gendered captions. Friends say share it."},
  {"id":"su-919","type":"branch","options":[{"text":"Pick a safe move, get a teacher, so you help and stay safe","consequence":"You protect the target and yourself at once.","best":true,"outcome":"smart"},{"text":"Do nothing because you're afraid","consequence":"Safe moves let you help without becoming the next target."}],"debrief":"Choose a safe move so you help without endangering yourself.","cat":"be-the-upstander","persona":"any","source":"upstander / safety","relearn":"Your safety matters too; choose the move that protects everyone.","hook":"You're scared that if you help, the group will start targeting you next."},
  {"id":"su-920","type":"branch","options":[{"text":"Tell her after class her marks prove that's not true","consequence":"She hears the put-down was wrong, not her.","best":true,"outcome":"delay"},{"text":"Agree because a teacher said it","consequence":"Even an adult can be wrong; back the kid who was put down."}],"debrief":"A grown-up's gender put-down can still be wrong; back the kid.","cat":"be-the-upstander","persona":"any","source":"upstander / adult","relearn":"You can quietly back someone an adult has unfairly put down.","hook":"A teacher jokes that 'boys are just naturally better at maths'. A girl who topped looks down."},
  {"id":"su-921","type":"branch","options":[{"text":"Pass to him and tell the others he's on your side","consequence":"He's in the game and the 'too soft' line is dropped.","best":true,"outcome":"include"},{"text":"Agree he'd probably slow the team down","consequence":"Including him in the game is the upstander choice."}],"debrief":"Including a left-out boy is a real upstander move.","cat":"be-the-upstander","persona":"any","source":"upstander / exclusion","relearn":"You can include a boy who's pushed out of a 'boys' game'.","hook":"A boy is left out of the kabaddi team because 'he's too soft for a boys' game'."},
  {"id":"su-922","type":"branch","options":[{"text":"Say, \"that's not okay, how would you like being ranked?\"","consequence":"You name it and the ranking game stops.","best":true,"outcome":"direct"},{"text":"Join in since it's the girls doing it, not boys","consequence":"Harm is harm whoever does it; you can still name it."}],"debrief":"Gender harm is harm whoever does it; you can name it.","cat":"be-the-upstander","persona":"any","source":"upstander / direct","relearn":"You can name harm even when it's a group of girls doing it.","hook":"Girls are giggling and ranking boys by who's 'manly enough'. One boy hears and shrinks."},
  {"id":"su-923","type":"branch","options":[{"text":"Find a part she can do and tell them she's dancing too","consequence":"She's included and the double put-down fails.","best":true,"outcome":"include"},{"text":"Feel it's kinder to let her just watch","consequence":"Including her, not sidelining her, is the upstander move."}],"debrief":"Including someone pushed aside is a real upstander move.","cat":"be-the-upstander","persona":"any","source":"upstander / inclusion","relearn":"You can include a child who's doubly left out.","hook":"A girl in a wheelchair is told she 'can't join the dance, girls like her just watch'."},
  {"id":"su-924","type":"branch","options":[{"text":"Tell him the teasing was wrong, not him, and stay a while","consequence":"He hears it wasn't his fault and isn't alone.","best":true,"outcome":"delay"},{"text":"Tell him to just toughen up","consequence":"Never blame the target; remind him the harm wasn't his fault."}],"debrief":"The target is never to blame; the harm wasn't his fault.","cat":"be-the-upstander","persona":"Aarav","source":"upstander / no-blame","relearn":"Remind a hurt friend the harm was never their fault.","hook":"After a fight, a boy who was mocked says, \"maybe I am weak.\" He believes the teasing."},
  {"id":"su-925","type":"branch","options":[{"text":"Step in and say firmly, \"stop, that's not okay\"","consequence":"Loud-not-physical harm, a firm line can break it safely.","best":true,"outcome":"direct"},{"text":"Wait to see if they get bored","consequence":"Loud but not physical means a safe direct move can work."}],"debrief":"Loud-not-physical harm can be met with a firm, safe line.","cat":"be-the-upstander","persona":"any","source":"upstander / judgement","relearn":"When it's loud but not physical, a firm line is a safe move.","hook":"Two kids loudly tease a girl about her dark skin and 'being a girl'. It's loud, not physical."},
  {"id":"su-926","type":"branch","options":[{"text":"Walk with her to a trusted adult and stay till she's heard","consequence":"A serious, scary harm reaches an adult who can act.","best":true,"outcome":"delegate"},{"text":"Promise to keep it a secret between you two","consequence":"Serious, scary harm needs a trusted adult, not a secret."}],"debrief":"Serious, scary harm needs a trusted adult, not a secret.","cat":"be-the-upstander","persona":"Asha","source":"upstander / serious","relearn":"For serious harm, get a trusted adult, not a secret.","hook":"A scared girl whispers an older boy keeps touching her and following her home."},
  {"id":"su-927","type":"branch","options":[{"text":"Report the players and tell her she belongs in the game","consequence":"You use the report tool and back her up.","best":true,"outcome":"report"},{"text":"Mute it and say nothing to her","consequence":"Report the harm and back the target; muting alone leaves her alone."}],"debrief":"Online: report the harassers and back up the target.","cat":"be-the-upstander","persona":"any","source":"upstander / online","relearn":"You can report in-game harassment and back the target.","hook":"Online gaming voice chat: players keep telling the one girl to 'get back to the kitchen'."},
  {"id":"su-928","type":"branch","options":[{"text":"Help him say no and tell them clothes don't change who you are","consequence":"The dare fizzles and he isn't the joke.","best":true,"outcome":"direct"},{"text":"Laugh along so you don't seem boring","consequence":"Backing his 'no' and naming the idea stops the dare."}],"debrief":"Backing someone's 'no' is a real upstander move.","cat":"be-the-upstander","persona":"any","source":"upstander / dare","relearn":"You can back a kid's 'no' and end a humiliating dare.","hook":"A whole class laughs as a boy is dared to wear a dupatta 'to see if he becomes a girl'."},
  {"id":"su-929","type":"branch","options":[{"text":"Be the someone: start with one safe move yourself","consequence":"When everyone waits, you can be the one who acts.","best":true,"outcome":"leader"},{"text":"Wait, since surely someone else will step in","consequence":"The 'someone else will' trap means no one acts; you can."}],"debrief":"When everyone waits for someone else, you can be that someone.","cat":"be-the-upstander","persona":"any","source":"upstander / bystander-trap","relearn":"Don't wait for someone else; you can be the upstander.","hook":"You want to help but everyone says, \"someone bigger will sort it out.\" Nobody does."},
  {"id":"su-930","type":"branch","options":[{"text":"Quickly tell her, \"meet me after, that wasn't fair\"","consequence":"Even a quick check-in plants that she isn't alone.","best":true,"outcome":"delay"},{"text":"Decide there's no time to do anything","consequence":"Even a few seconds is enough for a small upstander move."}],"debrief":"Even a tiny, quick move counts as upstanding.","cat":"be-the-upstander","persona":"Diya","source":"upstander / small-move","relearn":"Even with seconds, a small upstander move counts.","hook":"A girl is being teased and you only have a second before the bell. What's the upstander move?"},
  {"id":"su-931","type":"branch","options":[{"text":"Decide to be the kind of person who steps up, again and again","consequence":"You choose an upstander identity, not a one-off act.","best":true,"outcome":"identity"},{"text":"Wait for one big heroic moment to prove yourself","consequence":"Upstanding is who you choose to be, not a single rescue."}],"debrief":"Being an upstander is who you choose to be, daily.","cat":"be-the-upstander","persona":"Lensy","source":"upstander / identity","relearn":"Upstanding is an identity built through small choices.","hook":"Being an upstander isn't one big rescue, it's lots of small choices, every day."},
  {"id":"su-932","type":"spot","scene":[{"id":"a","text":"One kid quietly walks off to fetch a teacher","trick":false},{"id":"b","text":"A group films the teasing for laughs","trick":true},{"id":"c","text":"Another kid goes to sit beside the target","trick":false},{"id":"d","text":"Some kids chant along with the teasers","trick":true},{"id":"e","text":"A few just watch and say nothing","trick":false}],"why":"Filming and chanting feed the harm; upstanders get help and sit with the target.","cat":"be-the-upstander","persona":"any","source":"upstander / spotting","relearn":"Filming and chanting make harm worse; upstanders get help and support the target.","hook":"Recess scene. Spot the two that make it worse."},
  {"id":"su-933","type":"spot","scene":[{"id":"a","text":"Someone sits with the hurt girl","trick":false},{"id":"b","text":"A kid mimics how she cried, for a laugh","trick":true},{"id":"c","text":"Someone asks, \"want to tell sir together?\"","trick":false},{"id":"d","text":"A kid retells the teasing, laughing","trick":true},{"id":"e","text":"Others walk past, eyes down","trick":false}],"why":"Mimicking and retelling it for laughs keep the harm going.","cat":"be-the-upstander","persona":"Diya","source":"upstander / care","relearn":"Mocking or retelling harm keeps it going; sitting with someone or offering help is real upstanding.","hook":"After the harm. Spot the two that keep it going."},
  {"id":"su-934","type":"spot","scene":[{"id":"a","text":"Quietly go and get the nearby teacher","trick":false},{"id":"b","text":"Distract them: \"sir wants everyone now\"","trick":false},{"id":"c","text":"Stand back and wave the teacher over","trick":false},{"id":"d","text":"Jump into the middle to push them off","trick":true},{"id":"e","text":"Challenge the biggest one to back off","trick":true}],"why":"Jumping in or challenging bigger bullies isn't safe; get a teacher or distract instead.","cat":"be-the-upstander","persona":"any","source":"upstander / safety","relearn":"When outmatched, get an adult or distract; don't fight.","hook":"Bigger bullies. Spot the two unsafe moves."},
  {"id":"su-935","type":"spot","scene":[{"id":"a","text":"Screenshot the post as proof","trick":false},{"id":"b","text":"Forward it to warn other friends","trick":true},{"id":"c","text":"Show a trusted adult what's happening","trick":false},{"id":"d","text":"Report the post so it gets taken down","trick":false},{"id":"e","text":"Add a laughing emoji to fit in","trick":true}],"why":"Forwarding it or a laughing emoji only spread the harm.","cat":"be-the-upstander","persona":"any","source":"upstander / online","relearn":"Online: forwarding or piling on spreads harm; save proof, report, tell an adult.","hook":"Online harm. Spot the two that spread it."},
  {"id":"su-936","type":"spot","scene":[{"id":"a","text":"\"Come on, you're on my team\"","trick":false},{"id":"b","text":"\"Girls slow the game down\"","trick":true},{"id":"c","text":"Make space and pass the ball to her","trick":false},{"id":"d","text":"\"Just watch from the side\"","trick":true},{"id":"e","text":"Ask her which position she wants","trick":false}],"why":"\"Girls slow the game down\" and \"just watch\" keep her out; inviting her in includes her.","cat":"be-the-upstander","persona":"any","source":"upstander / inclusion","relearn":"Excluding lines keep someone out; inviting them in is a real upstander move.","hook":"A girl is left out. Spot the two that keep her out."},
  {"id":"su-937","type":"spot","scene":[{"id":"a","text":"\"That's not okay, stop.\"","trick":false},{"id":"b","text":"\"Leave them alone, that's not fair.\"","trick":false},{"id":"c","text":"\"Are you okay? That wasn't fair.\"","trick":false},{"id":"d","text":"\"You probably started it.\"","trick":true},{"id":"e","text":"\"It's just a joke, relax.\"","trick":true}],"why":"\"You probably started it\" blames the target and \"it's just a joke\" excuses the harm.","cat":"be-the-upstander","persona":"any","source":"upstander / words","relearn":"Lines that blame the target or excuse harm aren't upstander words; upstander words name it or check in.","hook":"Spot the two lines that blame or excuse the harm."},
  {"id":"su-938","type":"spot","scene":[{"id":"a","text":"A kid filming and laughing","trick":true},{"id":"b","text":"Someone fetching a teacher","trick":false},{"id":"c","text":"A kid chanting along to encourage it","trick":true},{"id":"d","text":"Someone sitting with the target","trick":false},{"id":"e","text":"A kid asking the target to walk away with them","trick":false}],"why":"Filming and chanting feed the harm; fetching help and supporting the target stop it.","cat":"be-the-upstander","persona":"any","source":"upstander / spotting","relearn":"Filming and egging-on make harm worse; helping and supporting stop it.","hook":"Crowded scene. Spot the two people making it worse."},
  {"id":"su-939","type":"spot","scene":[{"id":"a","text":"An older boy keeps following a girl home","trick":true},{"id":"b","text":"A small name-call you can answer yourself","trick":false},{"id":"c","text":"Someone is being shoved and hurt","trick":true},{"id":"d","text":"A mild tease you can shrug off","trick":false},{"id":"e","text":"A joke that stopped when you frowned","trick":false}],"why":"Following and physical hurt are serious, so get an adult; the small ones have other moves.","cat":"be-the-upstander","persona":"any","source":"upstander / get-help","relearn":"Serious or scary harm means get an adult; everyday teasing has moves.","hook":"When is it 'get an adult' time? Spot the two serious ones."},
  {"id":"su-940","type":"spot","scene":[{"id":"a","text":"Blame the girl for 'asking for it'","trick":true},{"id":"b","text":"Check she's okay afterwards","trick":false},{"id":"c","text":"Forward the cruel photo to others","trick":true},{"id":"d","text":"Quietly get a trusted adult","trick":false},{"id":"e","text":"Name the harm calmly","trick":false}],"why":"Blaming the target and forwarding harm are never upstander moves; checking in, getting help and naming it are.","cat":"be-the-upstander","persona":"any","source":"upstander / not-this","relearn":"An upstander never blames the target or spreads the harm.","hook":"Spot the two things an upstander never does."},
  {"id":"su-941","type":"spot","scene":[{"id":"a","text":"Tell your friend later, \"that wasn't okay\"","trick":false},{"id":"b","text":"Laugh so your friend feels backed","trick":true},{"id":"c","text":"Check the teased kid is alright","trick":false},{"id":"d","text":"Join in so you stay in the group","trick":true},{"id":"e","text":"Ask the teased kid to walk off with you","trick":false}],"why":"Laughing along and joining in side with the teasing.","cat":"be-the-upstander","persona":"any","source":"upstander / friends","relearn":"Laughing along or joining in backs the teasing; correct your friend and check on the kid.","hook":"Your friend is teasing. Spot the two that side with it."},
  {"id":"su-942","type":"strike-rewrite","myth":{"un":"Someone braver than me will step in, so I don't need to.","re":"When everyone waits for someone else, no one acts; you can be the first.","why":"One person speaking up often gives others the nerve to join in."},"cat":"be-the-upstander","persona":"any","source":"upstander / myth","relearn":"Don't wait for a braver kid: being first to speak makes it safe for others.","hook":"\"Someone braver will step in, so I don't have to.\""},
  {"id":"su-943","type":"strike-rewrite","myth":{"un":"Someone braver will step in, so I don't have to.","re":"When everyone waits, no one acts; you can be the first.","why":"The first upstander often gives everyone else the courage to help."},"cat":"be-the-upstander","persona":"any","source":"upstander / myth","relearn":"Don't wait for someone braver; you can be the first to act.","hook":"\"Someone braver will step in, so I don't have to.\""},
  {"id":"su-944","type":"strike-rewrite","myth":{"un":"Telling a teacher about the teasing is just tattling.","re":"Telling keeps someone safe; tattling just gets someone in trouble.","why":"Help-seeking that protects a person is brave, not tattling."},"cat":"be-the-upstander","persona":"any","source":"upstander / myth","relearn":"Telling to keep someone safe is brave, not tattling.","hook":"\"Telling a teacher is just tattling.\""},
  {"id":"su-945","type":"strike-rewrite","myth":{"un":"Staying quiet when I see harm is the safe, neutral choice.","re":"Silence isn't neutral; it can leave the hurt person feeling alone.","why":"When no one speaks, the person being harmed feels no one cares."},"cat":"be-the-upstander","persona":"any","source":"upstander / myth","relearn":"Silence isn't neutral; speaking up tells someone they're not alone.","hook":"\"Staying quiet is the safe, neutral choice.\""},
  {"id":"su-946","type":"strike-rewrite","myth":{"un":"I'm too young to do anything about harm.","re":"Kids are upstanders every day; one safe move counts.","why":"Even a small safe move from a kid can change someone's whole day."},"cat":"be-the-upstander","persona":"any","source":"upstander / myth","relearn":"You're not too young; your safe upstander move counts.","hook":"\"I'm too young to do anything about it.\""},
  {"id":"su-947","type":"strike-rewrite","myth":{"un":"Being an upstander means I have to fight the bullies.","re":"You never have to fight; safe moves like get-help always work.","why":"Distracting or getting an adult helps without any danger to you."},"cat":"be-the-upstander","persona":"any","source":"upstander / myth","relearn":"Upstanding never means fighting; safe moves help without danger.","hook":"\"Helping means I have to fight the bullies.\""},
  {"id":"su-948","type":"strike-rewrite","myth":{"un":"She must have done something to get teased like that.","re":"The person being harmed is never to blame for it.","why":"No one earns being humiliated; the harm is the teaser's choice."},"cat":"be-the-upstander","persona":"any","source":"upstander / myth","relearn":"The target is never to blame; the harm is the teaser's choice.","hook":"\"She must have done something to get teased.\""},
  {"id":"su-949","type":"reflect","prompt":"Pick the one that fits you.","options":["Say something","Distract","Get help","Check in afterwards"],"affirm":"Any of these is a real upstander move; you already have one that's yours.","cat":"be-the-upstander","persona":"any","source":"reflection","relearn":"There are many safe upstander moves; you can pick the one that fits.","hook":"Lensy: which upstander move feels most like you?"},
  {"id":"su-950","type":"reflect","prompt":"How did it feel?","options":["Lonely","Unfair","Scary","Like no one cared"],"affirm":"That feeling is exactly why upstanders matter; you can be that someone now.","cat":"be-the-upstander","persona":"any","source":"reflection","relearn":"Remembering needing help shows why being an upstander matters.","hook":"Lensy: think of a time you wished someone had stepped in for you."},
  {"id":"su-951","type":"reflect","prompt":"Pick one.","options":["The one who films","The one who laughs along","The one who looks away"],"affirm":"Noticing this is the first step; you can choose the upstander instead.","cat":"be-the-upstander","persona":"any","source":"reflection","relearn":"Naming the bystander you don't want to be helps you choose the upstander.","hook":"Lensy: what kind of bystander do you want to stop being?"},
  {"id":"su-952","type":"reflect","prompt":"Picture them.","options":["A parent","A teacher","An older cousin or didi","A school counsellor"],"affirm":"Having someone in mind means you'll know where to turn when it's serious.","cat":"be-the-upstander","persona":"any","source":"reflection","relearn":"Knowing your trusted adult means you're ready when harm is serious.","hook":"Lensy: who is your trusted adult, the one you'd go to?"},
  {"id":"su-953","type":"reflect","prompt":"Choose your words.","options":["Standing up for others","Not staying silent","Being someone's safe person"],"affirm":"Whatever you chose, it's about who you want to be, and that's enough.","cat":"be-the-upstander","persona":"any","source":"reflection","relearn":"Being an upstander is about who you choose to be.","hook":"Lensy: what does being an upstander mean to you?"},
  {"id":"su-954","type":"reflect","prompt":"Pick a kind thing to say.","options":["It's okay, I can try again","Freezing doesn't make me a bad person","Next time I'll act"],"affirm":"All true; freezing once is okay, and you get another chance to step up.","cat":"be-the-upstander","persona":"Aarav","source":"reflection","relearn":"Freezing once is okay; you can be kind to yourself and try again.","hook":"Lensy: you froze once. What do you want to tell yourself?"},
  {"id":"su-955","type":"sort","items":[{"id":"i1","text":"Sit beside the teased kid"},{"id":"i2","text":"Film it for a laugh"},{"id":"i3","text":"Quietly fetch a teacher"},{"id":"i4","text":"Chant along with the crowd"},{"id":"i5","text":"Ask the target to walk away with you"},{"id":"i6","text":"Watch and say nothing"}],"bins":[{"id":"up","label":"Upstander","valence":"tell"},{"id":"by","label":"Bystander","valence":"neg"}],"key":{"i1":"up","i2":"by","i3":"up","i4":"by","i5":"up","i6":"by"},"cat":"be-the-upstander","persona":"any","source":"upstander / sort","relearn":"Upstanders help or get help; bystanders film, chant, or just watch.","hook":"Sort each action: upstander or bystander?"},
  {"id":"su-956","type":"sort","items":[{"id":"i1","text":"A small one-off name-call"},{"id":"i2","text":"Someone is being shoved and hurt"},{"id":"i3","text":"A mild tease that you can shrug off"},{"id":"i4","text":"An older boy keeps following a girl home"},{"id":"i5","text":"A joke that stopped when you frowned"},{"id":"i6","text":"Someone is being touched and won't be left alone"}],"bins":[{"id":"self","label":"Use a safe move","valence":"tell"},{"id":"adult","label":"Get an adult","valence":"uhoh"}],"key":{"i1":"self","i2":"adult","i3":"self","i4":"adult","i5":"self","i6":"adult"},"cat":"be-the-upstander","persona":"any","source":"upstander / sort","relearn":"Everyday teasing has safe moves; serious or physical harm means get an adult.","hook":"Sort the moment: handle it yourself, or get an adult?"},
  {"id":"su-957","type":"sort","items":[{"id":"i1","text":"\"That's not okay, stop.\""},{"id":"i2","text":"\"Don't be such a girl.\""},{"id":"i3","text":"\"Are you okay? That wasn't fair.\""},{"id":"i4","text":"\"You probably asked for it.\""},{"id":"i5","text":"\"Want to tell sir together?\""},{"id":"i6","text":"\"It's just a joke, relax.\""}],"bins":[{"id":"good","label":"Upstander line","valence":"tell"},{"id":"bad","label":"Harmful line","valence":"neg"}],"key":{"i1":"good","i2":"bad","i3":"good","i4":"bad","i5":"good","i6":"bad"},"cat":"be-the-upstander","persona":"any","source":"upstander / sort","relearn":"Upstander lines name harm or check in; harmful lines blame, excuse, or put down.","hook":"Sort each line: an upstander line, or a harmful one?"},
  {"id":"su-958","type":"sort","items":[{"id":"i1","text":"Screenshot the post as proof"},{"id":"i2","text":"Forward it to other friends"},{"id":"i3","text":"Tell a trusted adult"},{"id":"i4","text":"Reply with insults"},{"id":"i5","text":"Report the post"},{"id":"i6","text":"Add a laughing emoji"}],"bins":[{"id":"safe","label":"Safe online move","valence":"pos"},{"id":"worse","label":"Makes it worse","valence":"neg"}],"key":{"i1":"safe","i2":"worse","i3":"safe","i4":"worse","i5":"safe","i6":"worse"},"cat":"be-the-upstander","persona":"any","source":"upstander / sort","relearn":"Online: save proof, report, and tell an adult; forwarding, insults, and emojis spread the harm.","hook":"Sort the online action: safe move, or makes it worse?"},
  {"id":"su-959","type":"sort","items":[{"id":"i1","text":"Loud teasing, not physical"},{"id":"i2","text":"A boy is being beaten up"},{"id":"i3","text":"A sly comment in class"},{"id":"i4","text":"An adult is needed for a scary follower"},{"id":"i5","text":"A one-off mean nickname"},{"id":"i6","text":"Someone is grabbed and won't be let go"}],"bins":[{"id":"direct","label":"Say something","valence":"tell"},{"id":"help","label":"Get help","valence":"uhoh"}],"key":{"i1":"direct","i2":"help","i3":"direct","i4":"help","i5":"direct","i6":"help"},"cat":"be-the-upstander","persona":"any","source":"upstander / sort","relearn":"Loud-not-physical harm can take a direct line; physical or scary harm means get help.","hook":"Sort which move fits: a direct line, or get help?"},
  {"id":"su-960","type":"sort","items":[{"id":"i1","text":"\"Come on, you're on my team\""},{"id":"i2","text":"\"Girls can't play this\""},{"id":"i3","text":"Make space and pass to her"},{"id":"i4","text":"\"Just watch from the side\""},{"id":"i5","text":"Learn one word of her language"},{"id":"i6","text":"Mimic the new kid's accent"}],"bins":[{"id":"in","label":"Includes them","valence":"pos"},{"id":"out","label":"Leaves them out","valence":"neg"}],"key":{"i1":"in","i2":"out","i3":"in","i4":"out","i5":"in","i6":"out"},"cat":"be-the-upstander","persona":"any","source":"upstander / sort","relearn":"Inviting, sharing, and learning include someone; rules and mimicking leave them out.","hook":"Sort each: includes someone, or leaves them out?"},
  {"id":"su-961","type":"sort","items":[{"id":"i1","text":"\"That's not okay, stop\""},{"id":"i2","text":"\"Sir's calling everyone\" to break it up"},{"id":"i3","text":"Run and fetch a teacher"},{"id":"i4","text":"\"Are you okay? That wasn't fair\""},{"id":"i5","text":"Screenshot and tell an adult"},{"id":"i6","text":"Stand silent and watch"}],"bins":[{"id":"act","label":"An upstander move","valence":"tell"},{"id":"none","label":"Not a move","valence":"neg"}],"key":{"i1":"act","i2":"act","i3":"act","i4":"act","i5":"act","i6":"none"},"cat":"be-the-upstander","persona":"any","source":"upstander / sort","relearn":"Say something, distract, get help, check in, and report are all moves; watching silently isn't.","hook":"Sort the move to its name (the five upstander moves)."},
  {"id":"su-962","type":"sort","items":[{"id":"i1","text":"Telling keeps someone safe"},{"id":"i2","text":"Staying quiet is the neutral choice"},{"id":"i3","text":"One kid's action can count"},{"id":"i4","text":"Telling a teacher is tattling"},{"id":"i5","text":"Asking for help is brave"},{"id":"i6","text":"The teased kid asked for it"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Silencing myth","valence":"neg"}],"key":{"i1":"true","i2":"myth","i3":"true","i4":"myth","i5":"true","i6":"myth"},"cat":"be-the-upstander","persona":"any","source":"upstander / sort","relearn":"Telling, kid agency, and help-seeking are true; the silencing myths blame the target or excuse silence.","hook":"Sort the belief: true, or a silencing myth?"},
  {"id":"su-963","type":"role-play","setup":"Boys are teasing a girl about her period at the water tap. You step closer.","yourLine":[{"text":"\"That's not okay, leave her alone.\"","best":true},{"text":"\"Maybe just ignore them?\""}],"cat":"be-the-upstander","persona":"any","source":"upstander / voice","relearn":"A short, firm line, \"that's not okay\", can stop teasing in its tracks.","hook":"Say the upstander line."},
  {"id":"su-964","type":"role-play","setup":"A boy is being chanted at, 'ladki, ladki', for crying. You want to back him.","yourLine":[{"text":"\"Crying isn't only for girls. Stop it.\"","best":true},{"text":"\"He's used to it, it's fine.\""}],"cat":"be-the-upstander","persona":"Aarav","source":"upstander / voice","relearn":"You can defend a boy mocked as 'girly' with one calm, firm line.","hook":"Say the upstander line."},
  {"id":"su-965","type":"role-play","setup":"The crowd has gone. The teased girl is sitting alone, looking down.","yourLine":[{"text":"\"Are you okay? That wasn't fair.\"","best":true},{"text":"\"You should just forget about it.\""}],"cat":"be-the-upstander","persona":"Diya","source":"upstander / voice","relearn":"Checking in has its own words: \"are you okay? that wasn't fair.\"","hook":"Say the check-in line."},
  {"id":"su-966","type":"role-play","setup":"It's serious, an older boy keeps following a younger girl. You go to a teacher.","yourLine":[{"text":"\"Sir, she needs help, a boy keeps following her.\"","best":true},{"text":"\"Sir, um, nothing, never mind.\""}],"cat":"be-the-upstander","persona":"any","source":"upstander / voice","relearn":"Asking an adult for help is a line too, not a failure.","hook":"Say the asking-for-help line."},
  {"id":"su-967","type":"role-play","setup":"Your friend is the one teasing a quieter boy. You catch them alone later.","yourLine":[{"text":"\"That wasn't okay. Don't do that to him.\"","best":true},{"text":"\"That was kind of funny, I guess.\""}],"cat":"be-the-upstander","persona":"any","source":"upstander / voice","relearn":"Calm, direct words, even to a friend, work better than going along with it.","hook":"Say the line to your own friend."},
  {"id":"su-968","type":"role-play","setup":"A new girl is being left out of the game because she's 'not from here'.","yourLine":[{"text":"\"Come play with us, you're on my team.\"","best":true},{"text":"\"Maybe sit this one out for now.\""}],"cat":"be-the-upstander","persona":"any","source":"upstander / voice","relearn":"One welcoming line can turn exclusion into belonging.","hook":"Say the including line."},
  {"id":"su-969","type":"role-play","setup":"You froze before. The same boy is being mocked again. Your heart is pounding.","yourLine":[{"text":"\"Hey, stop. That's enough.\"","best":true},{"text":"\"...\" (stay frozen again)"}],"cat":"be-the-upstander","persona":"Aarav","source":"upstander / voice","relearn":"Freezing once is okay; even a short \"stop\" the next time is courage.","hook":"Say the line, even after freezing last time."},
  {"id":"su-970","type":"role-play","setup":"Direct feels unsafe, the group is big. You distract to give her a way out.","yourLine":[{"text":"\"Hey, sir wants everyone in the hall now!\"","best":true},{"text":"\"You should all stop, every one of you.\""}],"cat":"be-the-upstander","persona":"any","source":"upstander / voice","relearn":"When direct feels unsafe, a distraction line can break the moment.","hook":"Say the line to break it up."},
  {"id":"su-971","type":"match","pairs":[{"left":"Say something","right":"\"That's not okay, stop.\""},{"left":"Distract","right":"\"Sir wants everyone now!\""},{"left":"Get help","right":"Fetch a trusted adult"},{"left":"Check in","right":"\"Are you okay? That wasn't fair.\""},{"left":"Report","right":"Save proof and tell an adult"}],"cat":"be-the-upstander","persona":"any","source":"upstander / match","relearn":"Each upstander move has its own action: say, distract, get help, check in, report.","hook":"Match each upstander move to what you do."},
  {"id":"su-972","type":"match","pairs":[{"left":"Loud teasing, not physical","right":"Say a firm line"},{"left":"A direct line feels unsafe","right":"Distract the moment"},{"left":"Physical or scary harm","right":"Get a trusted adult"},{"left":"After the harm has passed","right":"Check in with the target"},{"left":"Cruel post online","right":"Save proof, tell an adult"}],"cat":"be-the-upstander","persona":"any","source":"upstander / match","relearn":"Match the situation to the move: judgement about which one fits keeps everyone safe.","hook":"Match the situation to the safest move."},
  {"id":"su-973","type":"match","pairs":[{"left":"Serious harm right now","right":"Childline 1098 / 112"},{"left":"Worried and need to talk","right":"A school counsellor"},{"left":"Trouble at home","right":"A trusted parent"},{"left":"Teasing in class","right":"Your class teacher"},{"left":"Won't tell a parent or teacher","right":"Asha, the NGO didi"}],"cat":"be-the-upstander","persona":"any","source":"upstander / match","relearn":"Different situations call for different helpers; there's always someone to turn to.","hook":"Match each situation to the right helper."},
  {"id":"su-974","type":"match","pairs":[{"left":"\"None of my business\"","right":"Seeing harm makes it mine too"},{"left":"\"Telling is tattling\"","right":"Telling keeps someone safe"},{"left":"\"Silence is neutral\"","right":"Silence can leave them alone"},{"left":"\"I'm just a kid\"","right":"Kids are upstanders every day"},{"left":"\"She asked for it\"","right":"The target is never to blame"}],"cat":"be-the-upstander","persona":"any","source":"upstander / match","relearn":"Every silencing myth has a truth that frees you to act.","hook":"Match the myth to its truth."},
  {"id":"su-975","type":"match","pairs":[{"left":"Say something","right":"When it feels safe and clear"},{"left":"Distract","right":"When direct feels unsafe"},{"left":"Get help","right":"For anything serious or scary"},{"left":"Check in","right":"Once the moment has passed"},{"left":"Report","right":"For online harm"}],"cat":"be-the-upstander","persona":"any","source":"upstander / match","relearn":"Each move has its moment; knowing when to use which keeps you safe.","hook":"Match the move to when you use it."},
  {"id":"su-976","type":"match","pairs":[{"left":"Fetching a teacher","right":"Upstander"},{"left":"Filming for laughs","right":"Bystander"},{"left":"Sitting with the target","right":"Helping"},{"left":"Chanting along","right":"Making it worse"},{"left":"Asking them to walk away","right":"Stepping in"}],"cat":"be-the-upstander","persona":"any","source":"upstander / sort","relearn":"Helping and getting help is upstanding; filming and chanting is just standing by.","hook":"Match each action to upstander or bystander."},
  {"id":"su-977","type":"match","pairs":[{"left":"Screenshot the post","right":"Saves proof"},{"left":"Forward it on","right":"Spreads the harm"},{"left":"Tell a trusted adult","right":"Brings real help"},{"left":"Reply with insults","right":"Fuels the fight"},{"left":"Report the post","right":"Flags it to be removed"}],"cat":"be-the-upstander","persona":"any","source":"upstander / match","relearn":"Online, save proof, report, and tell an adult; forwarding and insults only spread harm.","hook":"Match the online action to what it does."},
  {"id":"su-978","type":"match","pairs":[{"left":"Stood beside the teased girl","right":"Said something"},{"left":"Shouted \"sir's calling us!\"","right":"Distracted"},{"left":"Ran for the teacher","right":"Got help"},{"left":"Sat with her after","right":"Checked in"},{"left":"Saved the screenshot","right":"Reported"}],"cat":"be-the-upstander","persona":"Diya","source":"upstander / match","relearn":"Each child's action names one of the five upstander moves.","hook":"Match each child to the upstander move they made."},
  {"id":"su-990","type":"role-play","persona":"any","hook":"A boy keeps calling a classmate a gendered name.","setup":"Name it. Say:","yourLine":[{"text":"\"That word's a put-down. Cut it out.\"","best":true},{"text":"Look away and stay quiet"}],"relearn":"A short, firm line can stop name-calling in its tracks.","source":"upstander voice / name-calling","cat":"find-the-words"},
  {"id":"su-991","type":"role-play","persona":"Diya","hook":"Boys won't pass the ball to the new girl.","setup":"Pass it to her. Say:","yourLine":[{"text":"\"Diya's open, give her the ball.\"","best":true},{"text":"\"She'll just miss it anyway.\""}],"relearn":"Bringing someone into the game is a real upstander move.","source":"upstander voice / inclusion","cat":"find-the-words"},
  {"id":"su-992","type":"role-play","persona":"Aarav","hook":"Kids laugh at a boy for crying after a fall.","setup":"Stand with him. Say:","yourLine":[{"text":"\"Anyone would cry, that looked painful.\"","best":true},{"text":"Laugh so you blend in"}],"relearn":"Boys are allowed feelings; defending that is upstander work.","source":"upstander voice / norms","cat":"find-the-words"},
  {"id":"su-993","type":"role-play","persona":"Diya","hook":"Someone mimics a girl's chest behind her back.","setup":"Shut it down. Say:","yourLine":[{"text":"\"Stop that. It's not funny.\"","best":true},{"text":"Pretend you didn't see"}],"relearn":"Calm, direct words beat sniggering along.","source":"upstander voice / bodies","cat":"find-the-words"},
  {"id":"su-994","type":"role-play","persona":"any","hook":"A group chat is roasting a girl with cruel edits.","setup":"Type your line. Say:","yourLine":[{"text":"\"Not okay. I'm not laughing at this.\"","best":true},{"text":"Add a laughing emoji"}],"relearn":"You can refuse to pile on, in writing, out loud.","source":"upstander voice / online","cat":"find-the-words"},
  {"id":"su-995","type":"role-play","persona":"Asha","hook":"You want to tell the counsellor what you saw.","setup":"Open clearly. Say:","yourLine":[{"text":"\"Didi, I need to report something unfair.\"","best":true},{"text":"Decide it's not your place"}],"relearn":"Asking a trusted adult to step in is a line, not a failure.","source":"upstander voice / help-seeking","cat":"find-the-words"},
  {"id":"su-996","type":"role-play","persona":"any","hook":"The one doing harm sneers, \"Mind your own business.\"","setup":"Hold your ground. Say:","yourLine":[{"text":"\"This is my business when it's this unfair.\"","best":true},{"text":"Mumble sorry and back off"}],"relearn":"You can stand by your reason for speaking up.","source":"upstander voice / steady","cat":"find-the-words"},
  {"id":"su-997","type":"role-play","persona":"Aarav","hook":"You froze last week; the same teasing is back.","setup":"Try again now. Say:","yourLine":[{"text":"\"Enough. Leave him alone.\"","best":true},{"text":"Freeze and hope it ends"}],"relearn":"Freezing once is okay; your voice can show up next time.","source":"upstander voice / second chance","cat":"find-the-words"},
  {"id":"su-998","type":"role-play","persona":"Diya","hook":"A girl is eating lunch alone after being left out.","setup":"Quietly invite her. Say:","yourLine":[{"text":"\"Come sit with us, there's space.\"","best":true},{"text":"Walk past her table"}],"relearn":"A quiet 'come sit with us' is a gentle, real upstander move.","source":"upstander voice / quiet ally","cat":"find-the-words"},
  {"id":"su-999","type":"role-play","persona":"any","hook":"After it's over, the teased kid looks shaken.","setup":"Check in. Say:","yourLine":[{"text":"\"You okay? That wasn't fair to you.\"","best":true},{"text":"Say nothing and move on"}],"relearn":"Checking in afterwards has its own words and they matter.","source":"upstander voice / check in","cat":"find-the-words"},
  {"id":"su-1000","type":"role-play","persona":"any","hook":"Friends want you to share a humiliating photo.","setup":"Refuse out loud. Say:","yourLine":[{"text":"\"I'm not forwarding that. It's cruel.\"","best":true},{"text":"\"Fine, sending it on.\""}],"relearn":"You can say no to spreading harm, plainly.","source":"upstander voice / online","cat":"find-the-words"},
  {"id":"su-1001","type":"role-play","persona":"Diya","hook":"Relatives tease a cousin: \"girls shouldn't be so loud.\"","setup":"Push back kindly. Say:","yourLine":[{"text":"\"She's allowed to speak up, same as anyone.\"","best":true},{"text":"Giggle along with them"}],"relearn":"You can defend someone shamed for their gender, even with family.","source":"upstander voice / norms","cat":"find-the-words"},
  {"id":"su-1002","type":"role-play","persona":"any","hook":"Two kids whisper a slur and look at a classmate.","setup":"Call it gently. Say:","yourLine":[{"text":"\"I heard that. Please don't.\"","best":true},{"text":"Whisper back with them"}],"relearn":"Naming what you heard, calmly, can stop it.","source":"upstander voice / name-calling","cat":"find-the-words"},
  {"id":"su-1003","type":"role-play","persona":"Aarav","hook":"Older boys call a younger one \"such a girl\" as an insult.","setup":"Flip it. Say:","yourLine":[{"text":"\"That's not even an insult. Drop it.\"","best":true},{"text":"Echo the insult to fit in"}],"relearn":"You can refuse to treat 'girl' as a put-down.","source":"upstander voice / norms","cat":"find-the-words"},
  {"id":"su-1004","type":"role-play","persona":"any","hook":"A teammate keeps grabbing a girl who said stop.","setup":"Back her 'no'. Say:","yourLine":[{"text":"\"She said stop. So stop.\"","best":true},{"text":"Pretend it's just messing around"}],"relearn":"Backing someone's 'no' out loud is a strong, safe line.","source":"upstander voice / touch","cat":"find-the-words"},
  {"id":"su-1005","type":"role-play","persona":"Diya","hook":"Someone reads out a teasing note about a girl's body.","setup":"Cut it short. Say:","yourLine":[{"text":"\"That's mean. Put it away.\"","best":true},{"text":"Snatch it and read more"}],"relearn":"A firm, short line can stop the cruelty fast.","source":"upstander voice / bodies","cat":"find-the-words"},
  {"id":"su-1006","type":"role-play","persona":"any","hook":"You're nervous but you've decided to speak.","setup":"Start small. Say:","yourLine":[{"text":"\"Hey. That's not okay.\"","best":true},{"text":"Wait for the perfect words"}],"relearn":"You don't need a speech; one short honest line is enough.","source":"upstander voice / simple line","cat":"find-the-words"},
  {"id":"su-1007","type":"role-play","persona":"Asha","hook":"A friend is scared to tell, so you offer to come along.","setup":"Offer the line. Say:","yourLine":[{"text":"\"I'll come with you to tell Asha didi.\"","best":true},{"text":"Tell them to handle it alone"}],"relearn":"Going with someone to ask for help is real support.","source":"upstander voice / help-seeking","cat":"find-the-words"},
  {"id":"su-1008","type":"role-play","persona":"any","hook":"People keep chanting a gendered taunt at a girl.","setup":"Interrupt it. Say:","yourLine":[{"text":"\"Stop chanting that. It's bullying.\"","best":true},{"text":"Mouth the chant quietly"}],"relearn":"Naming a taunt as bullying can break the chant.","source":"upstander voice / name-calling","cat":"find-the-words"},
  {"id":"su-1009","type":"role-play","persona":"Aarav","hook":"A boy is mocked for liking dance over cricket.","setup":"Have his back. Say:","yourLine":[{"text":"\"Dance takes real skill. Lay off.\"","best":true},{"text":"Roll your eyes and join in"}],"relearn":"Defending an interest someone's mocked for is upstander work.","source":"upstander voice / norms","cat":"find-the-words"},
  {"id":"su-1010","type":"role-play","persona":"any","hook":"Someone calls a girl \"useless\" for missing a shot.","setup":"Reframe it. Say:","yourLine":[{"text":"\"Everyone misses. That was uncalled for.\"","best":true},{"text":"Agree she's useless"}],"relearn":"You can shut down a gendered put-down with a calm line.","source":"upstander voice / name-calling","cat":"find-the-words"},
  {"id":"su-1011","type":"role-play","persona":"Diya","hook":"A girl's period stain shows; kids start pointing.","setup":"Cover and calm. Say:","yourLine":[{"text":"\"It's normal. Quit pointing.\"","best":true},{"text":"Point and laugh too"}],"relearn":"Normalising bodies while defending someone stops the teasing.","source":"upstander voice / bodies","cat":"find-the-words"},
  {"id":"su-1012","type":"role-play","persona":"any","hook":"Your first line was ignored; the harm goes on.","setup":"Switch to help. Say:","yourLine":[{"text":"\"I'm getting a teacher, this isn't stopping.\"","best":true},{"text":"Give up after one try"}],"relearn":"When one line fails, going for help is the next line.","source":"upstander voice / get help","cat":"find-the-words"},
  {"id":"su-1013","type":"role-play","persona":"Aarav","hook":"A kid is shoved and called \"weak\" for being gentle.","setup":"Step between, calmly. Say:","yourLine":[{"text":"\"Being gentle isn't weak. Back off.\"","best":true},{"text":"Watch and stay silent"}],"relearn":"You can defend someone without shouting or shoving.","source":"upstander voice / norms","cat":"find-the-words"},
  {"id":"su-1014","type":"role-play","persona":"any","hook":"A meme mocking a classmate's gender lands in chat.","setup":"Don't spread it. Say:","yourLine":[{"text":"\"Deleting, not sharing. This is bullying.\"","best":true},{"text":"Forward it to two friends"}],"relearn":"Refusing to forward, and saying why, is an upstander line.","source":"upstander voice / online","cat":"find-the-words"},
  {"id":"su-1015","type":"role-play","persona":"Diya","hook":"A girl is told \"girls can't lead the project.\"","setup":"Back her role. Say:","yourLine":[{"text":"\"She's leading. She's good at it.\"","best":true},{"text":"Nod that boys should lead"}],"relearn":"You can name exclusion and back the person being shut out.","source":"upstander voice / inclusion","cat":"find-the-words"},
  {"id":"su-1016","type":"role-play","persona":"any","hook":"Someone's voice shakes as they try to speak up.","setup":"Join them. Say:","yourLine":[{"text":"\"I'm with you. That's not okay.\"","best":true},{"text":"Let them stand alone"}],"relearn":"Adding your voice to a shaky one makes it stronger.","source":"upstander voice / allyship","cat":"find-the-words"},
  {"id":"su-1017","type":"role-play","persona":"Asha","hook":"You don't know which adult to tell about ongoing harm.","setup":"Ask the route. Say:","yourLine":[{"text":"\"Asha didi, who do I tell about this?\"","best":true},{"text":"Decide no one would help"}],"relearn":"Asking who to tell is itself a help-seeking line.","source":"upstander voice / help-seeking","cat":"find-the-words"},
  {"id":"su-1018","type":"role-play","persona":"any","hook":"A boy keeps 'accidentally' bumping a girl who moved away.","setup":"Name the pattern. Say:","yourLine":[{"text":"\"That's not an accident. Stop it.\"","best":true},{"text":"Assume it's nothing"}],"relearn":"Naming a repeated 'accident' as deliberate can stop it.","source":"upstander voice / touch","cat":"find-the-words"},
  {"id":"su-1019","type":"role-play","persona":"Aarav","hook":"After teasing ends, the targeted boy sits alone.","setup":"Check in later. Say:","yourLine":[{"text":"\"That was rough. You alright?\"","best":true},{"text":"Act like nothing happened"}],"relearn":"Check-in words after the moment count just as much.","source":"upstander voice / check in","cat":"find-the-words"},
  {"id":"su-1020","type":"role-play","persona":"any","hook":"Kids dare you to repeat a gendered insult for laughs.","setup":"Refuse the dare. Say:","yourLine":[{"text":"\"No. I'm not saying that about her.\"","best":true},{"text":"Say it to get the laugh"}],"relearn":"Refusing to be the mouthpiece for harm is an upstander move.","source":"upstander voice / name-calling","cat":"find-the-words"},
  {"id":"su-1021","type":"role-play","persona":"Diya","hook":"A girl is told to 'sit out, this is for boys.'","setup":"Open the door. Say:","yourLine":[{"text":"\"She's playing. We take turns here.\"","best":true},{"text":"Agree it's only for boys"}],"relearn":"You can challenge a gendered 'rule' that's really exclusion.","source":"upstander voice / inclusion","cat":"find-the-words"},
  {"id":"su-1022","type":"role-play","persona":"any","hook":"Someone keeps screenshotting a girl to mock her.","setup":"Tell them to stop. Say:","yourLine":[{"text":"\"Stop screenshotting her. That's harassment.\"","best":true},{"text":"Ask for the screenshots"}],"relearn":"Naming online harassment plainly is an upstander line.","source":"upstander voice / online","cat":"find-the-words"},
  {"id":"su-1023","type":"role-play","persona":"Aarav","hook":"You spoke up once and got laughed at; harm continues.","setup":"Try a calmer line. Say:","yourLine":[{"text":"\"I still mean it. Knock it off.\"","best":true},{"text":"Decide it's pointless now"}],"relearn":"Being laughed at once doesn't end it; you can say it again.","source":"upstander voice / second chance","cat":"find-the-words"},
  {"id":"su-1024","type":"role-play","persona":"any","hook":"A friend says \"why bother, it's not our problem.\"","setup":"Answer them. Say:","yourLine":[{"text":"\"It's our problem when we see it.\"","best":true},{"text":"Shrug and agree"}],"relearn":"You can name that witnessing harm makes it your business.","source":"upstander voice / allyship","cat":"find-the-words"},
  {"id":"su-1025","type":"role-play","persona":"Diya","hook":"A girl is mocked for asking about period products.","setup":"Normalise it. Say:","yourLine":[{"text":"\"Good question. Nothing to laugh at.\"","best":true},{"text":"Laugh with the others"}],"relearn":"Defending a normal question shuts down body-shaming.","source":"upstander voice / bodies","cat":"find-the-words"},
  {"id":"su-1026","type":"role-play","persona":"any","hook":"Someone yells a slur; shouting back would escalate.","setup":"Stay calm and firm. Say:","yourLine":[{"text":"\"That's not okay. Let's walk away.\"","best":true},{"text":"Yell an insult right back"}],"relearn":"Calm, direct words work better than shouting or insults back.","source":"upstander voice / steady","cat":"find-the-words"},
  {"id":"su-1027","type":"role-play","persona":"Asha","hook":"You're not sure your worry is 'big enough' to report.","setup":"Ask anyway. Say:","yourLine":[{"text":"\"It might be small, but can I tell you?\"","best":true},{"text":"Stay quiet to avoid fuss"}],"relearn":"You don't have to be certain to ask a trusted adult.","source":"upstander voice / help-seeking","cat":"find-the-words"},
  {"id":"su-1028","type":"role-play","persona":"any","hook":"A classmate is teased every day; today it's worse.","setup":"Step up today. Say:","yourLine":[{"text":"\"This has gone too far. Stop now.\"","best":true},{"text":"Hope a teacher notices"}],"relearn":"You can be the first to act, you don't have to wait.","source":"upstander voice / first to act","cat":"find-the-words"},
  {"id":"su-1029","type":"role-play","persona":"Aarav","hook":"A boy froze when his friend was being mocked.","setup":"Reassure, then plan. Say:","yourLine":[{"text":"\"Freezing happens. Let's check on him now.\"","best":true},{"text":"Tell him he failed"}],"relearn":"No one is shamed for freezing; the next move is a check-in.","source":"upstander voice / second chance","cat":"find-the-words"},
  {"id":"su-1030","type":"role-play","persona":"Diya","hook":"A girl is blamed for 'causing drama' by speaking up.","setup":"Defend her. Say:","yourLine":[{"text":"\"She's not the problem here. They are.\"","best":true},{"text":"Agree she overreacted"}],"relearn":"You never blame the person who was harmed for speaking up.","source":"upstander voice / no blame","cat":"find-the-words"},
  {"id":"su-1031","type":"branch","persona":"any","hook":"You have your line ready but your voice is shaking.","options":[{"text":"Say it anyway, shaky voice and all","consequence":"A shaky line still lands; it gets easier each time.","outcome":"brave","best":true},{"text":"Wait until you feel braver","consequence":"Bravery is acting through the nerves, not after them."},{"text":"Whisper it so no one hears","consequence":"Say it loud enough to be heard; a clear line works better."}],"debrief":"Nerves are normal; say your line anyway.","relearn":"You can speak up even with a shaking voice.","source":"upstander voice / courage","cat":"find-the-words"},
  {"id":"su-1032","type":"branch","persona":"Aarav","hook":"You froze before. The teasing just started again.","options":[{"text":"Use the short line you practised","consequence":"You act through the freeze; your voice shows up.","outcome":"brave","best":true},{"text":"Freeze and wait for it to stop","consequence":"Freezing is okay, but trying your line is braver still."}],"debrief":"A freeze last time doesn't decide this time.","relearn":"After freezing, you still get a chance to find your words.","source":"upstander voice / second chance","cat":"find-the-words"},
  {"id":"su-1033","type":"branch","persona":"any","hook":"Your calm line got ignored and the harm continues.","options":[{"text":"Switch moves: go get an adult","consequence":"Escalating to help is the next line, not giving up.","outcome":"persistent","best":true},{"text":"Repeat it louder and angrily","consequence":"Shouting can escalate; help is safer."},{"text":"Give up; one try failed","consequence":"One move failing means switch, not stop."}],"debrief":"If one line fails, switch to another, like getting help.","relearn":"If your first line fails, getting help is the next line.","source":"upstander voice / persistence","cat":"find-the-words"},
  {"id":"su-1034","type":"branch","persona":"any","hook":"Someone's being harmed and shouting back feels tempting.","options":[{"text":"Use a calm, firm line instead","consequence":"Calm words work better and keep it from escalating.","outcome":"calm","best":true},{"text":"Shout an insult back at them","consequence":"Insults back can escalate and pull you into the harm."}],"debrief":"Calm and direct beats loud and angry.","relearn":"Calm, direct words work better than shouting or insults.","source":"upstander voice / steady","cat":"find-the-words"},
  {"id":"su-1035","type":"branch","persona":"Asha","hook":"You want to tell an adult but worry it's 'tattling.'","options":[{"text":"Tell them, to keep your friend safe","consequence":"Telling for safety is help-seeking, never tattling.","outcome":"helpful","best":true},{"text":"Stay quiet so you're not a tattletale","consequence":"Silence leaves your friend alone; telling keeps them safe."}],"debrief":"Telling to keep someone safe is brave, not tattling.","relearn":"Asking an adult for help is a line, not a failure.","source":"upstander voice / help-seeking","cat":"find-the-words"},
  {"id":"su-1036","type":"branch","persona":"Diya","hook":"A girl was just teased and the crowd has moved on.","options":[{"text":"Go check in: 'you okay? that wasn't fair'","consequence":"Your check-in tells her she isn't alone.","outcome":"kind","best":true},{"text":"Say nothing; the moment's passed","consequence":"The moment passing is exactly when a check-in helps."}],"debrief":"Check-in words have their own moment, after it ends.","relearn":"Checking in afterwards has its own words that matter.","source":"upstander voice / check in","cat":"find-the-words"},
  {"id":"su-1037","type":"branch","persona":"any","hook":"You only have a second before the harm spreads online.","options":[{"text":"Type 'not okay' and don't forward","consequence":"A quick line plus not forwarding stops the spread.","outcome":"brave","best":true},{"text":"Forward it with a 'haha'","consequence":"Forwarding spreads the harm; a 'haha' joins it."},{"text":"Leave the chat silently","consequence":"Leaving quietly lets it spread; a line does more."}],"debrief":"Online, the line is 'not okay' plus 'I won't forward'.","relearn":"You can refuse to forward and say why, in one line.","source":"upstander voice / online","cat":"find-the-words"},
  {"id":"su-1038","type":"branch","persona":"Aarav","hook":"You don't know the 'perfect' thing to say.","options":[{"text":"Say a short, plain line: 'stop, that's enough'","consequence":"A short honest line works; it doesn't need to be perfect.","outcome":"brave","best":true},{"text":"Stay silent until you think of something clever","consequence":"Waiting for clever words means the moment passes."}],"debrief":"One short honest line beats a perfect speech you never say.","relearn":"You don't need a perfect speech; one short line is enough.","source":"upstander voice / simple line","cat":"find-the-words"},
  {"id":"su-1039","type":"branch","persona":"any","hook":"A friend whispers, 'don't get involved.'","options":[{"text":"Say your line anyway: 'this isn't right'","consequence":"You can be the one who acts, even if others won't.","outcome":"brave","best":true},{"text":"Follow your friend and stay out of it","consequence":"Everyone staying out is the trap; you can break it."}],"debrief":"You can be the first to speak, not wait for someone else.","relearn":"You don't have to wait; you can be the one who acts.","source":"upstander voice / first to act","cat":"find-the-words"},
  {"id":"su-1040","type":"reflect","persona":"any","hook":"Lensy: a line you've said before comes out easier next time. Worth keeping a few ready?","prompt":"What do you think?","options":["Yes","I'll keep some ready","Ready lines help"],"affirm":"A rehearsed line comes out far more easily under pressure.","relearn":"Practising a ready line helps you use it in the moment.","source":"upstander voice / reflect","cat":"find-the-words"},
  {"id":"su-1041","type":"reflect","persona":"any","hook":"Lensy: which short line feels most like you to say out loud?","prompt":"What do you think?","options":["\"That's not okay.\"","\"Stop, that's enough.\"","\"Leave them alone.\""],"affirm":"Any of these works; the best line is the one you'll actually say.","relearn":"Your honest, short line is enough; pick the one that fits you.","source":"upstander voice / reflect","cat":"find-the-words"},
  {"id":"su-1042","type":"reflect","persona":"any","hook":"Lensy: ever frozen and wished you'd spoken? You're not alone in that.","prompt":"What do you think?","options":["Yes, once","More than once","I've felt that"],"affirm":"Freezing is human; courage is finding your words the next time.","relearn":"Freezing is okay; you get another chance to find your words.","source":"upstander voice / reflect","cat":"find-the-words"},
  {"id":"su-1043","type":"reflect","persona":"any","hook":"Lensy: after the moment passes, a check-in still helps. How would you start?","prompt":"What do you think?","options":["\"You okay?\"","\"That wasn't fair.\"","\"I'm here.\""],"affirm":"Each of these is a real check-in; the words matter less than meaning them.","relearn":"Check-in words like 'you okay?' tell someone they're not alone.","source":"upstander voice / reflect","cat":"find-the-words"},
  {"id":"su-1044","type":"reflect","persona":"any","hook":"Lensy: who would you find easiest to tell if you saw harm?","prompt":"What do you think?","options":["A teacher","A parent","Asha didi"],"affirm":"Whoever you'd tell is a good route; telling keeps someone safe.","relearn":"Asking a trusted adult for help is a line, not a failure.","source":"upstander voice / reflect","cat":"find-the-words"},
  {"id":"su-1045","type":"reflect","persona":"any","hook":"Lensy: a calm line or a loud one, which do you think lands better?","prompt":"What do you think?","options":["Calm","Depends","Firm but calm"],"affirm":"Calm and firm usually lands best and keeps things from escalating.","relearn":"Calm, direct words work better than shouting or insults back.","source":"upstander voice / reflect","cat":"find-the-words"},
  {"id":"su-1046","type":"reflect","persona":"any","hook":"Lensy: imagine having one good line ready right now. How does that feel?","prompt":"What do you think?","options":["Safer","More prepared","Less scary"],"affirm":"Having a line ready takes some of the fear out of the moment.","relearn":"A ready line makes speaking up in the moment feel less scary.","source":"upstander voice / reflect","cat":"find-the-words"},
  {"id":"su-1047","type":"spot","persona":"any","hook":"Spot the 2 lines that DON'T help.","scene":[{"id":"a","text":"\"That's not okay, stop.\"","trick":false},{"id":"b","text":"\"You're so weak, just take it.\"","trick":true},{"id":"c","text":"\"Leave them alone.\"","trick":false},{"id":"d","text":"\"Whatever, not my problem.\"","trick":true},{"id":"e","text":"\"I'm getting a teacher.\"","trick":false}],"why":"Insulting the target or shrugging it off aren't upstander lines; calm, firm words are.","relearn":"Upstander lines are calm and firm; insults and shrugs aren't.","source":"upstander voice / spot lines","cat":"find-the-words"},
  {"id":"su-1048","type":"spot","persona":"Aarav","hook":"Spot the 2 lines that won't help him.","scene":[{"id":"a","text":"\"Being gentle isn't weak.\"","trick":false},{"id":"b","text":"\"Just toughen up and ignore it.\"","trick":true},{"id":"c","text":"\"Knock it off, that's enough.\"","trick":false},{"id":"d","text":"\"You kind of asked for it.\"","trick":true},{"id":"e","text":"\"You okay? That was unfair.\"","trick":false}],"why":"'Toughen up' and blaming him aren't upstander lines; defending and checking in are.","relearn":"Never tell the target to toughen up or that they asked for it.","source":"upstander voice / spot lines","cat":"find-the-words"},
  {"id":"su-1049","type":"spot","persona":"Diya","hook":"Spot the 2 lines that make it worse.","scene":[{"id":"a","text":"\"Everyone's body changes, stop teasing.\"","trick":false},{"id":"b","text":"\"Haha, point at her again!\"","trick":true},{"id":"c","text":"\"That's mean, put it away.\"","trick":false},{"id":"d","text":"\"She shouldn't have worn that.\"","trick":true},{"id":"e","text":"\"Come sit with us.\"","trick":false}],"why":"Joining the pointing or blaming her clothes are harm, not help; defending and including are.","relearn":"Defending and including help; joining in or blaming the girl don't.","source":"upstander voice / spot lines","cat":"find-the-words"},
  {"id":"su-1050","type":"spot","persona":"any","hook":"Spot the 2 lines that aren't real upstander moves.","scene":[{"id":"a","text":"\"I'm not forwarding that.\"","trick":false},{"id":"b","text":"\"Send it to me too.\"","trick":true},{"id":"c","text":"\"Deleting this, it's cruel.\"","trick":false},{"id":"d","text":"\"Let's screenshot and laugh.\"","trick":true},{"id":"e","text":"\"This is bullying, I'm telling.\"","trick":false}],"why":"Asking for the post or screenshotting to laugh spreads harm; refusing and reporting are the moves.","relearn":"Online, refusing and reporting help; forwarding or screenshotting don't.","source":"upstander voice / spot lines","cat":"find-the-words"},
  {"id":"su-1051","type":"spot","persona":"any","hook":"Spot the 2 lines that escalate instead of help.","scene":[{"id":"a","text":"\"That's not okay, let's walk away.\"","trick":false},{"id":"b","text":"\"Say that again and I'll hit you.\"","trick":true},{"id":"c","text":"\"Stop, please.\"","trick":false},{"id":"d","text":"\"You're an idiot, shut up.\"","trick":true},{"id":"e","text":"\"Come on, leave them be.\"","trick":false}],"why":"Threats and insults back can escalate danger; calm, firm lines de-escalate.","relearn":"Calm lines de-escalate; threats and insults back escalate.","source":"upstander voice / spot lines","cat":"find-the-words"},
  {"id":"su-1052","type":"spot","persona":"Asha","hook":"Spot the 2 lines that aren't asking for help.","scene":[{"id":"a","text":"\"Didi, I need to report something.\"","trick":false},{"id":"b","text":"\"I'll just keep it to myself.\"","trick":true},{"id":"c","text":"\"Can you help with this, please?\"","trick":false},{"id":"d","text":"\"It's none of my business.\"","trick":true},{"id":"e","text":"\"Who should I tell about this?\"","trick":false}],"why":"Keeping quiet or 'none of my business' aren't help-seeking; asking an adult clearly is.","relearn":"Asking an adult clearly is help-seeking; staying silent isn't.","source":"upstander voice / spot lines","cat":"find-the-words"},
  {"id":"su-1053","type":"spot","persona":"Aarav","hook":"You froze once. Spot the 2 lines that shame freezing.","scene":[{"id":"a","text":"\"Freezing happens, try again.\"","trick":false},{"id":"b","text":"\"You're a coward for freezing.\"","trick":true},{"id":"c","text":"\"Let's check on him now.\"","trick":false},{"id":"d","text":"\"You ruined it by doing nothing.\"","trick":true},{"id":"e","text":"\"Next time you'll find your words.\"","trick":false}],"why":"Calling someone a coward or blaming them for freezing is shaming; freezing gets a second chance.","relearn":"Never shame a freeze; offer a second chance instead.","source":"upstander voice / spot lines","cat":"find-the-words"},
  {"id":"su-1054","type":"spot","persona":"Diya","hook":"Spot the 2 lines that leave her out.","scene":[{"id":"a","text":"\"She's on my team, let's play.\"","trick":false},{"id":"b","text":"\"Girls can't play this.\"","trick":true},{"id":"c","text":"\"Pass her the ball.\"","trick":false},{"id":"d","text":"\"Sit out, this is for boys.\"","trick":true},{"id":"e","text":"\"We take turns here.\"","trick":false}],"why":"'Girls can't' and 'this is for boys' shut her out; inviting and sharing turns include her.","relearn":"Inclusion lines bring her in; 'girls can't' shuts her out.","source":"upstander voice / spot lines","cat":"find-the-words"},
  {"id":"su-1055","type":"strike-rewrite","persona":"any","hook":"\"You need the perfect words or don't bother.\"","myth":{"un":"You need the perfect words, or it's not worth saying.","re":"One short, honest line is enough to make a difference.","why":"The point is to be heard, not to give a speech."},"relearn":"One short, honest line is enough to make a difference.","source":"upstander voice / myth","cat":"find-the-words"},
  {"id":"su-1056","type":"strike-rewrite","persona":"Aarav","hook":"\"If you froze once, you've blown your chance.\"","myth":{"un":"Freezing once means you've missed your only chance.","re":"Freezing is okay; you get another chance to find your words.","why":"Courage is acting through the fear, not never feeling it."},"relearn":"Freezing is okay; you get another chance to find your words.","source":"upstander voice / myth","cat":"find-the-words"},
  {"id":"su-1057","type":"strike-rewrite","persona":"any","hook":"\"You have to shout to be taken seriously.\"","myth":{"un":"You have to shout for people to take you seriously.","re":"A calm, firm line works better than shouting.","why":"Calm words land and don't escalate the moment."},"relearn":"A calm, firm line works better than shouting.","source":"upstander voice / myth","cat":"find-the-words"},
  {"id":"su-1058","type":"strike-rewrite","persona":"Asha","hook":"\"Asking an adult for help means you failed.\"","myth":{"un":"Asking an adult for help means you couldn't handle it.","re":"Asking for help is a line too, and a brave one.","why":"Getting help is a smart move, not a failure."},"relearn":"Asking for help is a line too, and a brave one.","source":"upstander voice / myth","cat":"find-the-words"},
  {"id":"su-1059","type":"strike-rewrite","persona":"any","hook":"\"Standing up for a friend always starts a fight.\"","myth":{"un":"Speaking up for a friend always turns into a fight.","re":"You can speak up for a friend with a calm line, no fight.","why":"Direct, calm words can stop harm without escalating."},"relearn":"You can speak up for a friend with a calm line, no fight.","source":"upstander voice / myth","cat":"find-the-words"},
  {"id":"su-1060","type":"strike-rewrite","persona":"any","hook":"\"If you can't fix it in one line, give up.\"","myth":{"un":"If your first line doesn't work, there's nothing more to do.","re":"If one line fails, switch moves, like going to get help.","why":"Upstander moves can be combined and swapped."},"relearn":"If one line fails, switch moves, like going to get help.","source":"upstander voice / myth","cat":"find-the-words"},
  {"id":"su-1061","type":"strike-rewrite","persona":"any","hook":"\"Checking in afterwards is pointless once it's over.\"","myth":{"un":"Once the moment's over, saying anything is pointless.","re":"A check-in like 'you okay?' tells someone they're not alone.","why":"Words after the moment still reach the person who was hurt."},"relearn":"A check-in like 'you okay?' tells someone they're not alone.","source":"upstander voice / myth","cat":"find-the-words"},
  {"id":"su-1062","type":"strike-rewrite","persona":"any","hook":"\"Insulting them back is the strongest reply.\"","myth":{"un":"Hitting back with a worse insult is the strongest reply.","re":"Calm, direct words are stronger than an insult thrown back.","why":"An insult back just adds more harm to the moment."},"relearn":"Calm, direct words are stronger than an insult thrown back.","source":"upstander voice / myth","cat":"find-the-words"},
  {"id":"su-1063","type":"sort","persona":"any","hook":"Sort each line: helps, or doesn't?","items":[{"id":"a","text":"\"That's not okay, stop.\""},{"id":"b","text":"\"Not my problem.\""},{"id":"c","text":"\"Leave them alone.\""},{"id":"d","text":"\"You deserved it.\""},{"id":"e","text":"\"You okay? That was unfair.\""},{"id":"f","text":"\"Just ignore it forever.\""}],"bins":[{"id":"help","label":"Upstander line","valence":"tell"},{"id":"no","label":"Doesn't help","valence":"neg"}],"key":{"a":"help","b":"no","c":"help","d":"no","e":"help","f":"no"},"relearn":"Calm, firm, caring lines help; shrugs and blame don't.","source":"upstander voice / sort lines","cat":"find-the-words"},
  {"id":"su-1064","type":"sort","persona":"any","hook":"Sort: which words say it calmly, which escalate?","items":[{"id":"a","text":"\"Stop, please, that's enough.\""},{"id":"b","text":"\"I'll smash you for that.\""},{"id":"c","text":"\"That's not okay.\""},{"id":"d","text":"\"You're an idiot, shut up.\""},{"id":"e","text":"\"Let's walk away from this.\""},{"id":"f","text":"\"Say it again, I dare you.\""}],"bins":[{"id":"calm","label":"Calm & firm","valence":"pos"},{"id":"esc","label":"Escalates","valence":"neg"}],"key":{"a":"calm","b":"esc","c":"calm","d":"esc","e":"calm","f":"esc"},"relearn":"Calm, firm lines de-escalate; threats and insults back escalate.","source":"upstander voice / sort lines","cat":"find-the-words"},
  {"id":"su-1065","type":"sort","persona":"Asha","hook":"Sort: which lines ask for help, which stay silent?","items":[{"id":"a","text":"\"Didi, I need to report this.\""},{"id":"b","text":"\"I'll keep it to myself.\""},{"id":"c","text":"\"Can you help, please?\""},{"id":"d","text":"\"It's none of my business.\""},{"id":"e","text":"\"Who do I tell about this?\""},{"id":"f","text":"\"Better not make a fuss.\""}],"bins":[{"id":"ask","label":"Asks for help","valence":"tell"},{"id":"quiet","label":"Stays silent","valence":"uhoh"}],"key":{"a":"ask","b":"quiet","c":"ask","d":"quiet","e":"ask","f":"quiet"},"relearn":"Asking a trusted adult is help-seeking; staying silent leaves someone alone.","source":"upstander voice / sort lines","cat":"find-the-words"},
  {"id":"su-1066","type":"sort","persona":"any","hook":"Sort each line by its move.","items":[{"id":"a","text":"\"Stop, that's not okay.\""},{"id":"b","text":"\"You okay? That wasn't fair.\""},{"id":"c","text":"\"Leave them alone.\""},{"id":"d","text":"\"I'm here if you want to talk.\""},{"id":"e","text":"\"Enough, knock it off.\""},{"id":"f","text":"\"That was rough, you alright?\""}],"bins":[{"id":"now","label":"Say it now (Direct)","valence":"tell"},{"id":"after","label":"Check in after (Delay)","valence":"pos"}],"key":{"a":"now","b":"after","c":"now","d":"after","e":"now","f":"after"},"relearn":"Direct lines name it in the moment; check-in lines come after it passes.","source":"upstander voice / sort lines","cat":"find-the-words"},
  {"id":"su-1067","type":"sort","persona":"Diya","hook":"Sort: which lines include her, which leave her out?","items":[{"id":"a","text":"\"Come sit with us.\""},{"id":"b","text":"\"Girls can't play this.\""},{"id":"c","text":"\"She's on my team.\""},{"id":"d","text":"\"This is for boys only.\""},{"id":"e","text":"\"Pass her the ball.\""},{"id":"f","text":"\"She can just watch.\""}],"bins":[{"id":"in","label":"Includes her","valence":"pos"},{"id":"out","label":"Leaves her out","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"out","e":"in","f":"out"},"relearn":"Inviting and sharing turns include her; 'girls can't' shuts her out.","source":"upstander voice / sort lines","cat":"find-the-words"},
  {"id":"su-1068","type":"sort","persona":"any","hook":"Online: sort the helpful lines from the harmful ones.","items":[{"id":"a","text":"\"I'm not forwarding that.\""},{"id":"b","text":"\"Send it to me too.\""},{"id":"c","text":"\"Deleting this, it's cruel.\""},{"id":"d","text":"\"Let's screenshot and laugh.\""},{"id":"e","text":"\"This is bullying, I'm telling.\""},{"id":"f","text":"\"Add a laughing emoji.\""}],"bins":[{"id":"help","label":"Helps online","valence":"tell"},{"id":"harm","label":"Spreads harm","valence":"neg"}],"key":{"a":"help","b":"harm","c":"help","d":"harm","e":"help","f":"harm"},"relearn":"Refusing and reporting help online; forwarding and screenshotting spread harm.","source":"upstander voice / sort lines","cat":"find-the-words"},
  {"id":"su-1069","type":"sort","persona":"Aarav","hook":"Sort: which lines honour a freeze, which shame it?","items":[{"id":"a","text":"\"Freezing happens, try again.\""},{"id":"b","text":"\"You're a coward for freezing.\""},{"id":"c","text":"\"Next time you'll find your words.\""},{"id":"d","text":"\"You ruined it by doing nothing.\""},{"id":"e","text":"\"Let's check on him together.\""},{"id":"f","text":"\"You always chicken out.\""}],"bins":[{"id":"kind","label":"Honours the freeze","valence":"pos"},{"id":"shame","label":"Shames it","valence":"neg"}],"key":{"a":"kind","b":"shame","c":"kind","d":"shame","e":"kind","f":"shame"},"relearn":"Freezing gets a kind second chance, never shame.","source":"upstander voice / sort lines","cat":"find-the-words"},
  {"id":"su-1070","type":"sort","persona":"any","hook":"Sort: brave help-seeking, or just tattling?","items":[{"id":"a","text":"\"Miss, someone needs help.\""},{"id":"b","text":"\"Miss, he forgot his homework!\""},{"id":"c","text":"\"This harm has to stop.\""},{"id":"d","text":"\"She's chewing gum in class!\""},{"id":"e","text":"\"I'm telling so they're safe.\""},{"id":"f","text":"\"I'll snitch to get him punished.\""}],"bins":[{"id":"tell","label":"Telling (keeps safe)","valence":"tell"},{"id":"tattle","label":"Tattling (gets in trouble)","valence":"uhoh"}],"key":{"a":"tell","b":"tattle","c":"tell","d":"tattle","e":"tell","f":"tattle"},"relearn":"Telling keeps someone safe; tattling just gets someone in trouble.","source":"upstander voice / sort lines","cat":"find-the-words"},
  {"id":"su-1071","type":"match","persona":"any","hook":"Match each moment to the line that fits.","pairs":[{"left":"Name-calling right now","right":"\"That's not okay, stop.\""},{"left":"A friend left out","right":"\"Come sit with us.\""},{"left":"Someone froze","right":"\"Freezing happens, try again.\""},{"left":"After it's over","right":"\"You okay? That wasn't fair.\""},{"left":"A cruel post to share","right":"\"I'm not forwarding that.\""}],"relearn":"Each moment has a line that fits it best.","source":"upstander voice / match lines","cat":"find-the-words"},
  {"id":"su-1072","type":"match","persona":"any","hook":"Match the harm to the upstander line.","pairs":[{"left":"A gendered slur","right":"\"That word's a put-down. Cut it out.\""},{"left":"Grabbing after a 'no'","right":"\"She said stop. So stop.\""},{"left":"Mocking a changing body","right":"\"Everyone's body changes. Leave her alone.\""},{"left":"\"Girls can't play\"","right":"\"She's on my team. Let's play.\""},{"left":"A mean meme in chat","right":"\"Not okay. I'm not laughing at this.\""}],"relearn":"Match the shape of harm to the line that meets it.","source":"upstander voice / match lines","cat":"find-the-words"},
  {"id":"su-1073","type":"match","persona":"Asha","hook":"Match the worry to who you'd tell.","pairs":[{"left":"Serious or scary harm","right":"Childline 1098 / 112"},{"left":"A school problem","right":"A teacher"},{"left":"Something at home","right":"A parent"},{"left":"You won't tell parents","right":"Asha didi"},{"left":"Feeling overwhelmed","right":"The school counsellor"}],"relearn":"Match the situation to the right helper; serious harm goes to Childline 1098 / 112.","source":"upstander voice / match help","cat":"find-the-words"},
  {"id":"su-1074","type":"match","persona":"any","hook":"Match each move to its line.","pairs":[{"left":"Say something (Direct)","right":"\"Stop, that's not okay.\""},{"left":"Distract","right":"\"Hey, can you help me with this?\""},{"left":"Get help (Delegate)","right":"\"I'm getting a teacher.\""},{"left":"Check in (Delay)","right":"\"You okay? That was unfair.\""},{"left":"Report (Document)","right":"\"I'll save it and tell an adult.\""}],"relearn":"Each of the five moves has words you can actually say.","source":"upstander voice / match moves","cat":"find-the-words"},
  {"id":"su-1075","type":"match","persona":"Diya","hook":"Match the teasing to the line that shuts it down.","pairs":[{"left":"Period-teasing","right":"\"It's normal. Quit pointing.\""},{"left":"\"You throw like a girl\"","right":"\"That's not an insult. Drop it.\""},{"left":"Leaving a girl out","right":"\"We take turns here.\""},{"left":"Whispered slur","right":"\"I heard that. Please don't.\""},{"left":"Mocking a question","right":"\"Good question. Nothing to laugh at.\""}],"relearn":"A short, fitting line can shut down each kind of teasing.","source":"upstander voice / match lines","cat":"find-the-words"},
  {"id":"su-1076","type":"match","persona":"any","hook":"Match what they say to your steady reply.","pairs":[{"left":"\"Why do you even care?\"","right":"\"Because it's not okay.\""},{"left":"\"Mind your own business.\"","right":"\"It's my business when it's unfair.\""},{"left":"\"It was just a joke.\"","right":"\"It didn't feel like one to them.\""},{"left":"\"Don't be so dramatic.\"","right":"\"This isn't drama, it's harm.\""},{"left":"\"No one else minds.\"","right":"\"I do, and I'm saying so.\""}],"relearn":"You can keep a calm, steady reply ready for the pushback.","source":"upstander voice / match lines","cat":"find-the-words"},
  {"id":"su-1077","type":"match","persona":"Aarav","hook":"Match the situation to the second-chance line.","pairs":[{"left":"You froze last time","right":"\"Enough. Leave him alone.\""},{"left":"You got laughed at before","right":"\"I still mean it. Knock it off.\""},{"left":"A friend froze too","right":"\"Freezing happens. Let's check on him.\""},{"left":"You're scared to speak","right":"\"Hey. That's not okay.\""},{"left":"First line was ignored","right":"\"I'm getting a teacher.\""}],"relearn":"After a freeze or a fail, there's always a next line to try.","source":"upstander voice / match lines","cat":"find-the-words"},
  {"id":"su-1078","type":"match","persona":"any","hook":"Match each line to the move it belongs to.","pairs":[{"left":"\"That's not okay, stop.\"","right":"Say something"},{"left":"\"Want to come get water with me?\"","right":"Distract"},{"left":"\"Come on, let's tell the teacher.\"","right":"Get help"},{"left":"\"That wasn't fair, you alright?\"","right":"Check in"},{"left":"\"I saved it; I'm telling an adult.\"","right":"Report"}],"relearn":"Each upstander line belongs to one of the five moves.","source":"upstander voice / match moves","cat":"find-the-words"},
  {"id":"su-1080","cat":"five-moves","type":"branch","hook":"In the tuition queue, a boy keeps flicking a girl's dupatta and laughing. It feels safe to speak.","options":[{"text":"Say calmly \"stop, that's not okay\"","consequence":"Naming it plainly makes the flicking stop.","outcome":"direct","best":true},{"text":"Laugh along so it's not awkward","consequence":"A calm Direct line names it; laughing along lets it carry on."}],"debrief":"Direct: when it's safe and clear, just say it isn't okay.","relearn":"Move 1 (Direct): name the behaviour calmly when it feels safe.","persona":"any","source":"5 Ds / Direct"},
  {"id":"su-1081","cat":"five-moves","type":"branch","hook":"Two older boys are cornering a younger one near the back gate. Going in alone feels unsafe.","options":[{"text":"Run and get the gate guard or a teacher","consequence":"An adult steps in fast, and no one gets hurt.","outcome":"delegate","best":true},{"text":"Shove the older boys yourself","consequence":"For a scary corner, Get help (an adult) is the safe move."}],"debrief":"Delegate: anything scary or physical means get an adult, fast.","relearn":"Move 3 (Delegate): get a trusted adult for serious or scary harm.","persona":"any","source":"5 Ds / Delegate"},
  {"id":"su-1082","cat":"five-moves","type":"branch","hook":"Boys are mocking a classmate for crying. Confronting them head-on feels too risky.","options":[{"text":"Drop your bag and ask him to help you pick up","consequence":"The moment breaks; the mocking loses its audience.","outcome":"distract","best":true},{"text":"Yell at the whole group","consequence":"Direct feels unsafe; a sideways Distract works, no clash."}],"debrief":"Distract: derail the moment when speaking up feels risky.","relearn":"Move 2 (Distract): interrupt sideways when direct feels unsafe.","persona":"Aarav","source":"5 Ds / Distract"},
  {"id":"su-1083","cat":"five-moves","type":"branch","hook":"A girl was teased about a period stain. The moment passed, but she's curled up alone.","options":[{"text":"Sit by her: \"that wasn't fair, are you okay?\"","consequence":"She feels less alone and a little safer.","outcome":"delay","best":true},{"text":"Pretend you didn't notice","consequence":"A Check in afterwards tells her she wasn't alone."}],"debrief":"Check in: after the moment, a warm word helps a person heal.","relearn":"Move 4 (Check in): check in once the moment has passed.","persona":"Diya","source":"5 Ds / Delay"},
  {"id":"su-1084","cat":"five-moves","type":"branch","hook":"A cruel meme about a classmate is spreading on the class group. Which move?","options":[{"text":"Don't forward it; screenshot it and tell a teacher","consequence":"You stop the spread and keep proof for an adult.","outcome":"report","best":true},{"text":"Forward it to ask if it's true","consequence":"Don't pass it on; reporting it and telling an adult is the move."}],"debrief":"Report: save proof, tell an adult, and never forward the harm.","relearn":"Move 5 (Report): report online harm and don't forward it.","persona":"any","source":"5 Ds / Document-report"},
  {"id":"su-1085","cat":"five-moves","type":"branch","hook":"A boy keeps saying \"girls can't bowl.\" It's annoying but not scary. Which move fits?","options":[{"text":"A calm Direct: \"she's on the team, let her bowl\"","consequence":"Direct fits a loud-but-safe, clear moment.","outcome":"direct","best":true},{"text":"Get a teacher straight away","consequence":"This is safe and clear, so a calm Direct fits."}],"debrief":"Match the move: loud-but-safe and clear suits a calm Direct.","relearn":"Pick the move that fits; Direct suits a safe, clear moment.","persona":"any","source":"5 Ds / choosing"},
  {"id":"su-1086","cat":"five-moves","type":"branch","hook":"Someone is being grabbed and won't let go, in a packed bus aisle. Which move?","options":[{"text":"Call out to the conductor for help right away","consequence":"An adult with authority can stop it safely.","outcome":"delegate","best":true},{"text":"Try to pull them apart by yourself","consequence":"Physical and scary means Get help; bring an adult in fast."}],"debrief":"For anything physical, Get help every time, never go in alone.","relearn":"Physical or scary harm: get an adult rather than going in alone.","persona":"any","source":"5 Ds / safety"},
  {"id":"su-1087","cat":"five-moves","type":"branch","hook":"You can do TWO moves here: a girl is mocked, then sits alone. What's the upstander play?","options":[{"text":"Distract to break it up, then check in with her after","consequence":"You stop the moment and make sure she's okay.","outcome":"distract","best":true},{"text":"Only watch and feel bad","consequence":"You can combine moves: Distract first, then Check in after."}],"debrief":"Moves combine: a Distract now and a Check in later do more together.","relearn":"You can combine moves, like Distract then Check in.","persona":"any","source":"5 Ds / combining"},
  {"id":"su-1088","cat":"five-moves","type":"branch","hook":"Aarav froze last time. A boy is teased again today. He wants to try a safe move.","options":[{"text":"Quietly ask the boy to walk to the canteen with him","consequence":"A gentle Distract works, and Aarav got to act.","outcome":"distract","best":true},{"text":"Decide he's no good at this and give up","consequence":"Freezing once is okay; a small Distract is a real move."}],"debrief":"A second chance counts: even a small, safe move is upstanding.","relearn":"Froze once? A small safe move next time still counts.","persona":"Aarav","source":"5 Ds / second chance"},
  {"id":"su-1089","cat":"five-moves","type":"branch","hook":"A new girl is left out of games with \"girls slow us down.\" Which move includes her?","options":[{"text":"\"Come on, you're with us\" and pass her the ball","consequence":"She's in the game; the exclusion ends quietly.","outcome":"direct","best":true},{"text":"Wait for someone braver to invite her","consequence":"Including her is a real upstander move; you can be first."}],"debrief":"Including an excluded child is an upstander move; you can be first.","relearn":"Including someone left out is an upstander move.","persona":"any","source":"5 Ds / be first"},
  {"id":"su-1090","cat":"five-moves","type":"branch","hook":"A classmate is taunted in the corridor. You think \"someone else will say something.\"","options":[{"text":"Be the one: step in with a calm \"that's enough\"","consequence":"Because you acted, it stopped; you didn't wait.","outcome":"direct","best":true},{"text":"Keep waiting for someone else","consequence":"If everyone waits, no one acts; you can be the one who does."}],"debrief":"The bystander trap: when all wait, none act. You can be the one.","relearn":"Don't wait for someone else; you can be the upstander.","persona":"any","source":"5 Ds / bystander trap"},
  {"id":"su-1091","cat":"five-moves","type":"branch","hook":"A boy is mocked for wearing pink and called a \"girl.\" It's loud, not dangerous. Which move?","options":[{"text":"Calmly: \"pink's just a colour, drop it\"","consequence":"Direct names it; the mocking loses its steam.","outcome":"direct","best":true},{"text":"Tell him to fight back","consequence":"A calm Direct line fits; the game never asks anyone to fight."}],"debrief":"Direct works for loud-but-safe teasing; we never ask anyone to fight.","relearn":"Calm, direct words beat fighting back for loud teasing.","persona":"Aarav","source":"5 Ds / Direct"},
  {"id":"su-1092","cat":"five-moves","type":"branch","hook":"On the way home, a much bigger group is hurting someone. It looks dangerous. Which move?","options":[{"text":"Get a nearby adult or call Childline 1098 / 112","consequence":"Real help arrives, and you stay safe.","outcome":"delegate","best":true},{"text":"Jump into the middle of the group","consequence":"Danger means Get help: an adult or Childline 1098 / 112."}],"debrief":"For real danger, Get help: an adult or Childline 1098 / 112.","relearn":"Danger: get an adult or Childline 1098 / 112, never go in alone.","persona":"any","source":"5 Ds / Delegate"},
  {"id":"su-1093","cat":"five-moves","type":"branch","hook":"A girl's photo is shared with a nasty caption in a school chat. Which move fits?","options":[{"text":"Report it, don't forward it, and tell an adult","consequence":"The spread slows and an adult can act on it.","outcome":"report","best":true},{"text":"Save it to show friends later","consequence":"Online harm: Report it, don't forward, tell an adult."}],"debrief":"Report: for online harm, save proof for an adult, never forward.","relearn":"Online harm: report it, don't forward, tell an adult.","persona":"any","source":"5 Ds / Report"},
  {"id":"su-1094","cat":"five-moves","type":"branch","hook":"You want to help a teased classmate but you're shy and your voice shakes. Still a move?","options":[{"text":"A quiet Distract: ask them to come pick teams","consequence":"You helped without a big speech; shy is fine.","outcome":"distract","best":true},{"text":"Decide you're too shy to do anything","consequence":"You needn't be loud; a quiet Distract is a real move."}],"debrief":"Shy is okay: a quiet Distract helps without a big speech.","relearn":"You don't have to be loud; a quiet move still helps.","persona":"any","source":"5 Ds / safe options"},
  {"id":"su-1095","cat":"five-moves","type":"branch","hook":"A boy keeps making period jokes about a girl in class. A teacher is right there. Which move?","options":[{"text":"Quietly tell the teacher what's happening","consequence":"The teacher can step in with authority.","outcome":"delegate","best":true},{"text":"Make a louder joke to top him","consequence":"With a teacher right there, Get help is quick and strong."}],"debrief":"When a trusted adult is right there, Get help is fast and strong.","relearn":"An adult nearby? Telling them is a smart Get-help move.","persona":"Diya","source":"5 Ds / Delegate"},
  {"id":"su-1096","cat":"five-moves","type":"branch","hook":"You used a Distract and it worked, the teasing stopped. The person still looks shaken. Now what?","options":[{"text":"Check in: \"that was rotten, are you alright?\"","consequence":"They feel seen, and the help feels complete.","outcome":"delay","best":true},{"text":"Walk off, job done","consequence":"A Check in after a Distract finishes the help and shows you cared."}],"debrief":"After a Distract, a Check in completes the help; moves work together.","relearn":"Distract then Check in: moves combine to help fully.","persona":"any","source":"5 Ds / combining"},
  {"id":"su-1097","cat":"five-moves","type":"branch","hook":"Three moves could fit a loud, safe taunt by the water tank. Which is the calm first choice?","options":[{"text":"A calm Direct: \"hey, knock it off\"","consequence":"Direct fits a safe, clear moment best.","outcome":"direct","best":true},{"text":"Secretly film it on a phone","consequence":"For safe-and-clear, a calm Direct is the simple right move."}],"debrief":"There's rarely one move for all; here safe-and-clear means Direct.","relearn":"Judgement matters; safe and clear usually means Direct.","persona":"any","source":"5 Ds / judgement"},
  {"id":"su-1098","cat":"five-moves","type":"branch","hook":"A friend whispers \"just ignore it, it's not our problem.\" A girl beside you is being mocked.","options":[{"text":"Say \"it is our problem\" and use a calm Direct line","consequence":"You named it and the mocking eased.","outcome":"direct","best":true},{"text":"Agree and look away","consequence":"Seeing harm makes it your business too; a safe move still helps."}],"debrief":"Witnessing harm makes it your business; you still have a safe move.","relearn":"Seeing harm makes it yours to act on, safely.","persona":"any","source":"5 Ds / agency"},
  {"id":"su-1099","cat":"five-moves","type":"branch","hook":"A boy keeps grabbing a girl's water bottle to make her chase him; she's upset. Which calm move?","options":[{"text":"Step in: \"give it back, she said no\"","consequence":"Direct names her no; he hands it back.","outcome":"direct","best":true},{"text":"Tell her to just let it go","consequence":"\"She said no\" is a calm, clear Direct line, and it respects her."}],"debrief":"Direct can stand up for a no without escalating anything.","relearn":"Backing up someone's no is a clear, calm Direct move.","persona":"any","source":"5 Ds / Direct"},
  {"id":"su-1100","cat":"five-moves","type":"branch","hook":"A classmate gets mean DMs with gendered slurs. She shows you, scared. Which move?","options":[{"text":"Help her screenshot them and tell an adult together","consequence":"There's proof, and an adult can step in.","outcome":"report","best":true},{"text":"Tell her to delete them and forget it","consequence":"Save proof and tell an adult; deleting loses it."}],"debrief":"Report: keep proof and tell an adult; don't just delete.","relearn":"Online slurs: save proof and tell a trusted adult.","persona":"any","source":"5 Ds / Report"},
  {"id":"su-1101","cat":"five-moves","type":"branch","hook":"It's the assembly line, noisy. A boy keeps elbowing a girl who keeps moving away. Which move?","options":[{"text":"Distract: pull her into a chat about the song list","consequence":"The pestering stops as she steps away with you.","outcome":"distract","best":true},{"text":"Elbow him back","consequence":"A Distract pulls her out safely; we never trade shoves."}],"debrief":"Distract can pull someone out of a moment without any clash.","relearn":"Distract: draw the person away to break the moment safely.","persona":"any","source":"5 Ds / Distract"},
  {"id":"su-1102","cat":"five-moves","type":"reflect","hook":"Lensy: five moves means you've always got at least one move that fits you. Comforting?","prompt":"What do you think?","options":["Really comforting","There's always a way","I can pick one"],"affirm":"Whatever the moment, one of the five moves will fit you.","relearn":"With five moves, there's always a safe one that fits you.","persona":"Lensy","source":"5 Ds"},
  {"id":"su-1103","cat":"five-moves","type":"reflect","hook":"Lensy: of the five moves, which would feel easiest for you to try first?","prompt":"Pick one.","options":["Distract","Check in","Get help","Report"],"affirm":"Start with the one that feels easiest; the others grow with you.","relearn":"Begin with the move that feels easiest; the rest come with practice.","persona":"Lensy","source":"5 Ds"},
  {"id":"su-1104","cat":"five-moves","type":"reflect","hook":"Lensy: which move do you think helps a person feel less alone afterwards?","prompt":"What feels right?","options":["Check in","A kind word later","Sitting with them"],"affirm":"A simple Check in afterwards can mean the world to someone.","relearn":"Checking in after tells someone they weren't alone.","persona":"Lensy","source":"5 Ds / Delay"},
  {"id":"su-1105","cat":"five-moves","type":"reflect","hook":"Asha: it's okay if you'd reach for Get help first. Does that feel right for you?","prompt":"How about you?","options":["Yes, that's me","I'd get an adult","Depends on the day"],"affirm":"Choosing Get help isn't backing down; it's a strong, smart move.","relearn":"Reaching for Get help is a strong choice, never a weak one.","persona":"Asha","source":"5 Ds / Delegate"},
  {"id":"su-1106","cat":"five-moves","type":"reflect","hook":"Lensy: which move would you want a friend to use if YOU were the one being teased?","prompt":"Pick one.","options":["Check in with me","Speak up for me","Get help"],"affirm":"Knowing a friend would use a move is exactly why we learn them.","relearn":"The moves are how friends show up for each other.","persona":"Lensy","source":"5 Ds"},
  {"id":"su-1107","cat":"five-moves","type":"reflect","hook":"Lensy: you don't have to be loud to be an upstander. Which quiet move feels like you?","prompt":"What suits you?","options":["A quiet Distract","Get help","Check in later"],"affirm":"Quiet moves count just as much as loud ones.","relearn":"Quiet upstander moves help just as much as loud ones.","persona":"Lensy","source":"5 Ds / safe options"},
  {"id":"su-1108","cat":"five-moves","type":"reflect","hook":"Asha: which move do you think is bravest, the loud one or getting an adult?","prompt":"What's your take?","options":["Getting an adult is brave","Both are brave","Speaking up"],"affirm":"Getting help is brave too; there's no single 'bravest' move.","relearn":"Every move takes courage; Get help is brave, not a cop-out.","persona":"Asha","source":"5 Ds"},
  {"id":"su-1109","cat":"five-moves","type":"reflect","hook":"Lensy: if you froze once and didn't act, how do you feel about trying again?","prompt":"How does it sit?","options":["I'd try again","Next time I'll move","Still nervous, but yes"],"affirm":"Freezing once is human; the brave part is trying again.","relearn":"Freezing once is okay; courage is acting through the fear next time.","persona":"Aarav","source":"5 Ds / second chance"},
  {"id":"su-1110","cat":"five-moves","type":"reflect","hook":"Lensy: two moves can team up. Which pair would you reach for?","prompt":"Pick a pair.","options":["Distract, then Check in","Get help, then Check in","Direct, then Check in"],"affirm":"Pairing moves is smart; the Check in is a lovely finish.","relearn":"Moves can be combined; a Check in is a kind way to finish.","persona":"Lensy","source":"5 Ds / combining"},
  {"id":"su-1111","cat":"five-moves","type":"sort","hook":"Sort: which move fits, speak up now, or distract sideways?","items":[{"id":"a","text":"It's safe and you can say it plainly"},{"id":"b","text":"Confronting feels too risky right now"},{"id":"c","text":"You're calm and the moment is clear"},{"id":"d","text":"You'd rather break the moment quietly"},{"id":"e","text":"You can name it without a clash"},{"id":"f","text":"You drop your books to interrupt"}],"bins":[{"id":"direct","label":"Say something","valence":"tell"},{"id":"distract","label":"Distract","valence":"neutral"}],"key":{"a":"direct","b":"distract","c":"direct","d":"distract","e":"direct","f":"distract"},"relearn":"Direct is for safe and clear; Distract is for when direct feels risky.","persona":"any","source":"5 Ds / choosing"},
  {"id":"su-1112","cat":"five-moves","type":"sort","hook":"Sort: an upstander move, or a bystander choice?","items":[{"id":"a","text":"Getting a teacher"},{"id":"b","text":"Filming and laughing"},{"id":"c","text":"Checking in after"},{"id":"d","text":"Looking away on purpose"},{"id":"e","text":"Distracting to break it up"},{"id":"f","text":"Joining in the teasing"}],"bins":[{"id":"upstander","label":"Upstander move","valence":"pos"},{"id":"bystander","label":"Bystander choice","valence":"neg"}],"key":{"a":"upstander","b":"bystander","c":"upstander","d":"bystander","e":"upstander","f":"bystander"},"relearn":"Upstanders act safely to help; bystanders look away or join in.","persona":"any","source":"5 Ds / upstander vs bystander"},
  {"id":"su-1113","cat":"five-moves","type":"sort","hook":"Sort: needs an adult's help, or you can handle it with a safe move?","items":[{"id":"a","text":"Someone is being grabbed and hurt"},{"id":"b","text":"A boy says \"girls can't bowl\""},{"id":"c","text":"A scary group you can't stop"},{"id":"d","text":"A loud, safe taunt in class"},{"id":"e","text":"Someone won't stop touching another"},{"id":"f","text":"A friend left out of a game"}],"bins":[{"id":"adult","label":"Get an adult","valence":"tell"},{"id":"you","label":"A safe move you can do","valence":"pos"}],"key":{"a":"adult","b":"you","c":"adult","d":"you","e":"adult","f":"you"},"relearn":"Physical or scary needs an adult; loud-but-safe you can handle.","persona":"any","source":"5 Ds / safety"},
  {"id":"su-1114","cat":"five-moves","type":"sort","hook":"Sort online: a Report move, or makes the harm spread?","items":[{"id":"a","text":"Telling a trusted adult"},{"id":"b","text":"Forwarding the post"},{"id":"c","text":"Saving a screenshot for proof"},{"id":"d","text":"Sharing it 'as a warning'"},{"id":"e","text":"Reporting it in the app"},{"id":"f","text":"Adding it to your status"}],"bins":[{"id":"report","label":"Report move","valence":"pos"},{"id":"spread","label":"Spreads the harm","valence":"neg"}],"key":{"a":"report","b":"spread","c":"report","d":"spread","e":"report","f":"spread"},"relearn":"Report and save proof for an adult; sharing it, even as a warning, spreads it.","persona":"any","source":"5 Ds / Report"},
  {"id":"su-1115","cat":"five-moves","type":"sort","hook":"Sort: a move that happens DURING the harm, or AFTER it?","items":[{"id":"a","text":"Saying \"stop, that's not okay\""},{"id":"b","text":"\"Are you okay? that wasn't fair\""},{"id":"c","text":"Dropping books to interrupt"},{"id":"d","text":"Sitting with them at lunch later"},{"id":"e","text":"Getting a teacher right away"},{"id":"f","text":"Walking them home and listening"}],"bins":[{"id":"during","label":"During the moment","valence":"tell"},{"id":"after","label":"After the moment","valence":"neutral"}],"key":{"a":"during","b":"after","c":"during","d":"after","e":"during","f":"after"},"relearn":"Direct, Distract and Get help act in the moment; Check in comes after.","persona":"any","source":"5 Ds / timing"},
  {"id":"su-1116","cat":"five-moves","type":"sort","hook":"Sort: this helps the person, or only feels like helping but doesn't?","items":[{"id":"a","text":"Telling a trusted adult"},{"id":"b","text":"Posting 'thoughts and prayers'"},{"id":"c","text":"Checking in afterwards"},{"id":"d","text":"Gossiping about what happened"},{"id":"e","text":"Distracting to break it up"},{"id":"f","text":"Telling them they overreacted"}],"bins":[{"id":"real","label":"Really helps","valence":"pos"},{"id":"not","label":"Doesn't help","valence":"neg"}],"key":{"a":"real","b":"not","c":"real","d":"not","e":"real","f":"not"},"relearn":"Real moves help the person; gossip or 'you overreacted' don't.","persona":"any","source":"5 Ds / real help"},
  {"id":"su-1117","cat":"five-moves","type":"sort","hook":"Sort each line to its move.","items":[{"id":"a","text":"\"That's not okay, stop\""},{"id":"b","text":"\"Miss, can you come quick?\""},{"id":"c","text":"\"Hey, come help me find my book\""},{"id":"d","text":"\"Are you alright? that was unfair\""},{"id":"e","text":"\"I won't forward it, I'll report it\""},{"id":"f","text":"\"Oi, the bell's gone, let's go\""}],"bins":[{"id":"speak","label":"Say something / Get help","valence":"tell"},{"id":"break","label":"Distract / Check in / Report","valence":"neutral"}],"key":{"a":"speak","b":"speak","c":"break","d":"break","e":"break","f":"break"},"relearn":"Naming it and calling an adult speak up; the others break, check, or report.","persona":"any","source":"5 Ds / lines"},
  {"id":"su-1118","cat":"five-moves","type":"sort","hook":"Sort: safe upstander move, or risky 'hero' move?","items":[{"id":"a","text":"Getting the gate guard"},{"id":"b","text":"Snatching back the bag yourself"},{"id":"c","text":"A calm \"stop, that's enough\""},{"id":"d","text":"Chasing the bully to the road"},{"id":"e","text":"Reporting a cruel post"},{"id":"f","text":"Throwing a punch to 'teach them'"}],"bins":[{"id":"safe","label":"Safe move","valence":"pos"},{"id":"hero","label":"Risky 'hero' move","valence":"neg"}],"key":{"a":"safe","b":"hero","c":"safe","d":"hero","e":"safe","f":"hero"},"relearn":"Upstander moves help safely; chasing or fighting is risky, not heroic.","persona":"any","source":"5 Ds / safety over heroics"},
  {"id":"su-1119","cat":"five-moves","type":"sort","hook":"Sort: which Lensy 'D' is it, get help or report?","items":[{"id":"a","text":"Fetching a teacher for a scary fight"},{"id":"b","text":"Screenshotting a mean post for an adult"},{"id":"c","text":"Calling Childline 1098 / 112 in danger"},{"id":"d","text":"Not forwarding a cruel meme"},{"id":"e","text":"Telling a counsellor about bullying"},{"id":"f","text":"Saving proof of online slurs"}],"bins":[{"id":"gethelp","label":"Get help","valence":"tell"},{"id":"report","label":"Report","valence":"neutral"}],"key":{"a":"gethelp","b":"report","c":"gethelp","d":"report","e":"gethelp","f":"report"},"relearn":"Get help brings an adult in; Report saves proof of online harm.","persona":"any","source":"5 Ds"},
  {"id":"su-1120","cat":"five-moves","type":"sort","hook":"Sort: which fits a loud-but-safe moment, or a scary-and-physical one?","items":[{"id":"a","text":"A calm Direct line"},{"id":"b","text":"Getting an adult fast"},{"id":"c","text":"A quiet Distract"},{"id":"d","text":"Calling Childline 1098 / 112"},{"id":"e","text":"Checking in afterwards"},{"id":"f","text":"Fetching the nearest teacher"}],"bins":[{"id":"loud","label":"Loud but safe","valence":"pos"},{"id":"scary","label":"Scary or physical","valence":"tell"}],"key":{"a":"loud","b":"scary","c":"loud","d":"scary","e":"loud","f":"scary"},"relearn":"Loud-but-safe: your own move. Scary or physical: always Get help.","persona":"any","source":"5 Ds / safety"},
  {"id":"su-1121","cat":"five-moves","type":"sort","hook":"Sort: a calm upstander line, or words that make it worse?","items":[{"id":"a","text":"\"That's not okay, stop\""},{"id":"b","text":"\"You're such an idiot, shut up\""},{"id":"c","text":"\"Leave them alone, please\""},{"id":"d","text":"\"Fight me then\""},{"id":"e","text":"\"She said no, give it back\""},{"id":"f","text":"\"You're asking for it\""}],"bins":[{"id":"calm","label":"Calm upstander line","valence":"pos"},{"id":"worse","label":"Makes it worse","valence":"neg"}],"key":{"a":"calm","b":"worse","c":"calm","d":"worse","e":"calm","f":"worse"},"relearn":"Calm, clear lines help; insults, threats, or blame make it worse.","persona":"any","source":"5 Ds / Direct voice"},
  {"id":"su-1122","cat":"five-moves","type":"sort","hook":"Sort: this is being an upstander, or just watching?","items":[{"id":"a","text":"Inviting the left-out girl to play"},{"id":"b","text":"Filming for a laugh"},{"id":"c","text":"Walking a teased friend to class"},{"id":"d","text":"Saying 'not my problem'"},{"id":"e","text":"Telling a trusted adult"},{"id":"f","text":"Pretending you saw nothing"}],"bins":[{"id":"up","label":"Being an upstander","valence":"pos"},{"id":"watch","label":"Just watching","valence":"neg"}],"key":{"a":"up","b":"watch","c":"up","d":"watch","e":"up","f":"watch"},"relearn":"Upstanders act, including someone or telling an adult; watchers look away.","persona":"any","source":"5 Ds / upstander identity"},
  {"id":"su-1123","cat":"five-moves","type":"role-play","hook":"You choose the Direct move on a \"girls can't play\" taunt.","setup":"Say it calm and clear:","yourLine":[{"text":"\"She's on the team. Let her play.\"","best":true},{"text":"\"...\" (look at the ground)"}],"relearn":"A calm \"let her play\" is a strong Direct move against exclusion.","persona":"any","source":"5 Ds / Direct voice"},
  {"id":"su-1124","cat":"five-moves","type":"role-play","hook":"You use a Distract to break up some mocking near the lockers.","setup":"Make it casual. Say:","yourLine":[{"text":"\"Hey, can you help me carry these? The bell's about to go.\"","best":true},{"text":"\"Don't mind me, carry on.\""}],"relearn":"A casual ask is a smooth, safe Distract.","persona":"any","source":"5 Ds / Distract voice"},
  {"id":"su-1125","cat":"five-moves","type":"role-play","hook":"You use Get help when something feels scary.","setup":"Find an adult and say it plainly:","yourLine":[{"text":"\"Sir, please come, someone's getting hurt by the gate.\"","best":true},{"text":"\"Um, maybe later, it's probably fine.\""}],"relearn":"Telling an adult clearly is a strong Get-help move.","persona":"Asha","source":"5 Ds / Delegate voice"},
  {"id":"su-1126","cat":"five-moves","type":"role-play","hook":"You use the Check-in move after a girl was period-teased.","setup":"Be gentle. Say:","yourLine":[{"text":"\"That was so unfair on you. Are you okay?\"","best":true},{"text":"Say nothing so it's less awkward"}],"relearn":"A gentle \"are you okay?\" afterwards helps her feel less alone.","persona":"Diya","source":"5 Ds / Delay voice"},
  {"id":"su-1127","cat":"five-moves","type":"role-play","hook":"You use the Report move about a cruel post in the class chat.","setup":"Tell a trusted adult. Say:","yourLine":[{"text":"\"I didn't forward it, but please look, this post is hurting her.\"","best":true},{"text":"\"It's nothing, just a forward.\""}],"relearn":"Reporting without forwarding, and telling an adult, is the Report move.","persona":"any","source":"5 Ds / Report voice"},
  {"id":"su-1128","cat":"five-moves","type":"role-play","hook":"Aarav froze last time; today he tries the Direct move on a gentle-boy taunt.","setup":"Aarav steadies himself and says:","yourLine":[{"text":"\"Being kind isn't being weak. Cut it out.\"","best":true},{"text":"\"...\" (freeze again and walk off)"}],"relearn":"Acting through the fear is courage; gentle is never weak.","persona":"Aarav","source":"5 Ds / second chance"},
  {"id":"su-1129","cat":"five-moves","type":"role-play","hook":"You pair two moves: first a Distract, then a Check in.","setup":"You broke the moment; now check in. Say:","yourLine":[{"text":"\"Glad that's over. You alright? That wasn't fair.\"","best":true},{"text":"\"Anyway, see you around.\""}],"relearn":"After a Distract, a warm Check in completes the help.","persona":"any","source":"5 Ds / combining"},
  {"id":"su-1130","cat":"five-moves","type":"role-play","hook":"You use the Direct move to back up a friend's \"no.\"","setup":"Stand beside them and say:","yourLine":[{"text":"\"She said no. Give it back.\"","best":true},{"text":"\"It's just a joke, relax.\""}],"relearn":"Backing up a 'no' calmly is a clear Direct move.","persona":"any","source":"5 Ds / Direct voice"},
  {"id":"su-1131","cat":"five-moves","type":"role-play","hook":"You use Get help by going to Asha, the near-peer educator.","setup":"You'd rather tell Asha than a teacher. Say:","yourLine":[{"text":"\"Asha didi, can I tell you something that's been happening?\"","best":true},{"text":"Decide there's no one to tell"}],"relearn":"A near-peer like Asha is a real Get-help route too.","persona":"Asha","source":"5 Ds / Delegate voice"},
  {"id":"su-1132","cat":"five-moves","type":"spot","hook":"Lunch break. Spot the safe moves; two aren't.","scene":[{"id":"a","text":"A girl asks the teased boy to sit with her","trick":false},{"id":"b","text":"Someone runs to fetch a teacher","trick":false},{"id":"c","text":"A kid films the teasing to post later","trick":true},{"id":"d","text":"A boy checks in: \"you okay?\"","trick":false},{"id":"e","text":"Two kids chant along with the teasing","trick":true}],"why":"Filming to post and chanting along spread the harm; they aren't moves.","relearn":"Including, getting help, and checking in are moves; filming isn't.","persona":"any","source":"5 Ds / spot the move"},
  {"id":"su-1133","cat":"five-moves","type":"spot","hook":"A boy is mocked for crying. Spot the safe moves; two aren't.","scene":[{"id":"a","text":"A friend drops books to break the moment","trick":false},{"id":"b","text":"Someone calmly says \"that's enough\"","trick":false},{"id":"c","text":"A kid shoves the loudest mocker hard","trick":true},{"id":"d","text":"A girl fetches the class teacher","trick":false},{"id":"e","text":"Someone dares him to fight back","trick":true}],"why":"Shoving and daring a fight aren't moves; we never ask anyone to fight.","relearn":"Distract, Direct and Get help are safe; shoving or daring a fight aren't.","persona":"Aarav","source":"5 Ds / safety over heroics"},
  {"id":"su-1134","cat":"five-moves","type":"spot","hook":"A scary fight breaks out on the field. Spot the safe moves; two are risky.","scene":[{"id":"a","text":"Running to get the PT sir","trick":false},{"id":"b","text":"Calling Childline 1098 / 112","trick":false},{"id":"c","text":"Jumping in to split them up","trick":true},{"id":"d","text":"Keeping a safe distance while getting help","trick":false},{"id":"e","text":"Grabbing the biggest kid from behind","trick":true}],"why":"For danger, Get help and stay back; going in yourself isn't safe.","relearn":"Scary or physical: Get help and stay safe, never go in alone.","persona":"any","source":"5 Ds / Delegate"},
  {"id":"su-1135","cat":"five-moves","type":"spot","hook":"A mean post is going around online. Spot the Report-style moves; two make it worse.","scene":[{"id":"a","text":"Screenshotting it as proof for an adult","trick":false},{"id":"b","text":"Reporting the post in the app","trick":false},{"id":"c","text":"Forwarding it 'just to one friend'","trick":true},{"id":"d","text":"Telling a trusted teacher about it","trick":false},{"id":"e","text":"Adding a laughing comment under it","trick":true}],"why":"Forwarding it, even to one person, and piling on spread the harm.","relearn":"Save proof, report, and tell an adult; never forward or pile on.","persona":"any","source":"5 Ds / Report"},
  {"id":"su-1136","cat":"five-moves","type":"spot","hook":"The teasing has stopped. Spot the real Check-in moves; two only look like it.","scene":[{"id":"a","text":"Sitting beside her: \"that wasn't fair, okay?\"","trick":false},{"id":"b","text":"Walking her to class and listening","trick":false},{"id":"c","text":"Telling everyone the details later","trick":true},{"id":"d","text":"A quiet \"I've got your back\"","trick":false},{"id":"e","text":"Saying \"you kind of started it\"","trick":true}],"why":"Gossiping and blaming her aren't checking in; they hurt more.","relearn":"Checking in is warm and private; gossip or blame isn't a move.","persona":"Diya","source":"5 Ds / Delay"},
  {"id":"su-1137","cat":"five-moves","type":"spot","hook":"A girl is left out of the cricket game. Spot the upstander moves; two aren't.","scene":[{"id":"a","text":"\"You're with us, take the next over\"","trick":false},{"id":"b","text":"Quietly passing her the bat","trick":false},{"id":"c","text":"Agreeing \"yeah, girls slow us down\"","trick":true},{"id":"d","text":"Telling the captain it isn't fair to leave her out","trick":false},{"id":"e","text":"Laughing and turning away","trick":true}],"why":"Agreeing with the exclusion or turning away is being a bystander, not an upstander.","relearn":"Including someone is an upstander move; agreeing to exclude is not.","persona":"any","source":"5 Ds / be the upstander"},
  {"id":"su-1138","cat":"five-moves","type":"spot","hook":"Spot the moves that ask for help the right way; two don't.","scene":[{"id":"a","text":"\"Miss, please come, he won't stop\"","trick":false},{"id":"b","text":"Telling the counsellor what's going on","trick":false},{"id":"c","text":"Bragging \"I'll sort him out myself\"","trick":true},{"id":"d","text":"Calling Childline 1098 / 112 in danger","trick":false},{"id":"e","text":"Staying quiet: 'telling is tattling'","trick":true}],"why":"Handling danger alone, or staying silent, isn't asking for help.","relearn":"Telling an adult is brave, not tattling; help-seeking is a move.","persona":"Asha","source":"5 Ds / Delegate"},
  {"id":"su-1139","cat":"five-moves","type":"spot","hook":"A loud-but-safe taunt in class. Spot the calm Direct-style moves; two go too far.","scene":[{"id":"a","text":"\"That's not okay, leave them alone\"","trick":false},{"id":"b","text":"\"Knock it off, that's enough\"","trick":false},{"id":"c","text":"\"Say that again and I'll hit you\"","trick":true},{"id":"d","text":"\"They're my friend, back off\"","trick":false},{"id":"e","text":"\"You're a loser, shut up\"","trick":true}],"why":"Threats and insults aren't the Direct move; calm, clear words are.","relearn":"Direct means calm and clear, not threats or insults back.","persona":"any","source":"5 Ds / Direct voice"},
  {"id":"su-1140","cat":"five-moves","type":"strike-rewrite","hook":"\"If you can't fight the bully, there's nothing you can do.\"","myth":{"un":"If you can't fight the bully, you can't help at all.","re":"There are five safe moves, and at least one always fits.","why":"Helping never means fighting; the moves work without any danger."},"relearn":"You don't have to fight; a safe move always fits.","persona":"any","source":"5 Ds / safety over heroics"},
  {"id":"su-1141","cat":"five-moves","type":"strike-rewrite","hook":"\"Getting an adult is just running away.\"","myth":{"un":"Going to get an adult is the same as running away.","re":"Get help is a chosen move that brings real support fast.","why":"For serious or scary harm, an adult is the strongest help there is."},"relearn":"Getting an adult is a smart move, not running away.","persona":"Asha","source":"5 Ds / Delegate"},
  {"id":"su-1142","cat":"five-moves","type":"strike-rewrite","hook":"\"If you don't speak up loudly, you didn't really help.\"","myth":{"un":"Only a loud, brave speech counts as helping.","re":"A quiet Distract or a later Check in helps just as much.","why":"The moves are about the person being safe, not about being loud."},"relearn":"Quiet moves help as much as loud ones.","persona":"any","source":"5 Ds / safe options"},
  {"id":"su-1143","cat":"five-moves","type":"strike-rewrite","hook":"\"You should always say something to the bully's face.\"","myth":{"un":"The right move is always to confront the bully directly.","re":"Direct is for safe and clear; when it isn't, you Distract or Get help.","why":"Matching the move to the moment keeps you and the other person safe."},"relearn":"Direct isn't always right; match the move to the moment.","persona":"any","source":"5 Ds / choosing"},
  {"id":"su-1144","cat":"five-moves","type":"strike-rewrite","hook":"\"Checking in afterwards is too little, too late.\"","myth":{"un":"A kind word after the harm is too late to matter.","re":"A Check in afterwards helps the person feel less alone.","why":"Being seen and supported helps someone recover, even later."},"relearn":"Checking in afterwards still matters a lot.","persona":"Diya","source":"5 Ds / Delay"},
  {"id":"su-1145","cat":"five-moves","type":"strike-rewrite","hook":"\"If you froze and did nothing, you've blown your only chance.\"","myth":{"un":"Freeze once and you've lost your chance to ever help.","re":"Freezing is human; you get a second chance to try a safe move.","why":"Courage is acting through the fear the next time, not never freezing."},"relearn":"Froze once? You still get a second chance to act.","persona":"Aarav","source":"5 Ds / second chance"},
  {"id":"su-1146","cat":"five-moves","type":"strike-rewrite","hook":"\"The only way to help online is to delete the post and forget it.\"","myth":{"un":"For online harm, just delete it and move on.","re":"Save proof, report it, and tell an adult; don't forward it.","why":"Proof helps an adult act; deleting leaves the person with nothing."},"relearn":"Online harm: save proof, report, and tell an adult.","persona":"any","source":"5 Ds / Report"},
  {"id":"su-1147","cat":"five-moves","type":"strike-rewrite","hook":"\"Real upstanders rush in and stop it themselves.\"","myth":{"un":"A real upstander charges in and stops the harm alone.","re":"The bravest move is often Get help; the badge is for helping safely.","why":"Safety beats heroics; no one earns anything by getting hurt."},"relearn":"Being an upstander means helping safely, not charging in.","persona":"any","source":"5 Ds / safety over heroics"},
  {"id":"su-1148","cat":"five-moves","type":"match","hook":"Match the moment to the upstander move that fits.","pairs":[{"left":"Safe, clear taunt you can name","right":"Say something"},{"left":"Confronting feels too risky","right":"Distract"},{"left":"Serious or scary harm","right":"Get help"},{"left":"The person is hurt afterwards","right":"Check in"},{"left":"A cruel post is spreading online","right":"Report"}],"relearn":"Each moment has a move that fits; match it to stay safe and helpful.","persona":"any","source":"5 Ds / choosing"},
  {"id":"su-1149","cat":"five-moves","type":"match","hook":"Match each upstander move to a line that fits it.","pairs":[{"left":"Say something","right":"\"That's not okay, stop\""},{"left":"Distract","right":"\"Come help me carry these\""},{"left":"Get help","right":"\"Sir, please come quick\""},{"left":"Check in","right":"\"You okay? that wasn't fair\""},{"left":"Report","right":"\"I won't forward it, I'll report it\""}],"relearn":"Each move has its own words; the right line makes the move work.","persona":"any","source":"5 Ds / lines"},
  {"id":"su-1150","cat":"five-moves","type":"match","hook":"Match the move to when you'd use it.","pairs":[{"left":"Direct","right":"When it feels safe and clear"},{"left":"Distract","right":"When direct feels unsafe"},{"left":"Get help","right":"For anything serious or scary"},{"left":"Check in","right":"After the moment has passed"},{"left":"Report","right":"For online harm"}],"relearn":"Knowing when each move fits is half of being an upstander.","persona":"any","source":"5 Ds / timing"},
  {"id":"su-1151","cat":"five-moves","type":"match","hook":"Match each move to what it does.","pairs":[{"left":"Say something","right":"Names the behaviour calmly"},{"left":"Distract","right":"Breaks the moment sideways"},{"left":"Get help","right":"Brings in a trusted adult"},{"left":"Check in","right":"Helps them feel less alone"},{"left":"Report","right":"Saves proof, doesn't forward"}],"relearn":"Five moves, five jobs; together they're your upstander toolkit.","persona":"any","source":"5 Ds"},
  {"id":"su-1152","cat":"five-moves","type":"match","hook":"Match the scary or serious moment to the right helper.","pairs":[{"left":"A fight that looks dangerous","right":"A teacher or PT sir, fast"},{"left":"Harm you can't tell parents","right":"Asha, the near-peer educator"},{"left":"Real danger after school","right":"Childline 1098 / 112"},{"left":"Ongoing bullying at school","right":"The school counsellor"},{"left":"Online harm spreading","right":"A trusted adult, with proof"}],"relearn":"For serious harm, match the situation to the right helper.","persona":"Asha","source":"5 Ds / Delegate"},
  {"id":"su-1153","cat":"five-moves","type":"match","hook":"Match each move to a moment it does NOT fit (the safer move instead).","pairs":[{"left":"A dangerous group fight","right":"Get help, not Direct"},{"left":"A quiet, hurt friend later","right":"Check in, not a loud line"},{"left":"A risky corner alone","right":"Distract or Get help, not confront"},{"left":"A spreading cruel post","right":"Report, not forward"},{"left":"A safe, clear taunt","right":"Direct, not film it"}],"relearn":"The wrong move can backfire; the safer move is usually clear.","persona":"any","source":"5 Ds / judgement"},
  {"id":"su-1154","cat":"five-moves","type":"match","hook":"Match each upstander move to its Lensy nickname.","pairs":[{"left":"Direct","right":"Say something"},{"left":"Distract","right":"Break the moment"},{"left":"Delegate","right":"Get help"},{"left":"Delay","right":"Check in"},{"left":"Document","right":"Report"}],"relearn":"The five D's have kid-friendly names; same five moves, easy to remember.","persona":"Lensy","source":"5 Ds"},
  {"id":"su-1170","cat":"get-help","type":"match","hook":"Match the worry to the right helper.","pairs":[{"left":"Being teased about your changing body","right":"A trusted teacher or didi"},{"left":"Someone followed you home","right":"A parent, then 1098 / 112"},{"left":"A classmate seems unsafe at home","right":"The school counsellor"},{"left":"Mean messages in the class group","right":"A trusted adult, with proof saved"},{"left":"You just need to talk it out","right":"Asha, the near-peer didi"}],"relearn":"Each worry has a right helper; match it and you're not alone.","persona":"Asha","source":"get help / who-to-turn-to"},
  {"id":"su-1171","cat":"get-help","type":"match","hook":"Match what Childline 1098 is to what it's for.","pairs":[{"left":"Childline 1098","right":"Free, 24-hour help for children"},{"left":"112","right":"The national emergency number"},{"left":"A school counsellor","right":"Private support inside school"},{"left":"A trusted relative","right":"Help close to home"},{"left":"A class teacher","right":"Help during school hours"}],"relearn":"Knowing what each helper does makes asking for help easier.","persona":"any","source":"get help / routes / help.ts"},
  {"id":"su-1172","cat":"get-help","type":"match","hook":"Match the doubt to the answer.","pairs":[{"left":"\"Telling is being a tattle-tale\"","right":"Telling keeps a friend safe"},{"left":"\"I'm too small to do anything\"","right":"Even small steps bring help"},{"left":"\"What if no adult believes me?\"","right":"Tell another, and another"},{"left":"\"It's not my problem\"","right":"Seeing harm makes it yours too"},{"left":"\"Asking help is babyish\"","right":"Asking help is brave and smart"}],"relearn":"The doubts that stop us from telling each have a true answer.","persona":"any","source":"get help / tattle-vs-tell"},
  {"id":"su-1173","cat":"get-help","type":"match","hook":"Match the place to a safe grown-up there.","pairs":[{"left":"In the classroom","right":"Your class teacher"},{"left":"On the school bus","right":"The bus didi or driver bhaiya"},{"left":"At the tuition centre","right":"The tuition sir or madam"},{"left":"In your gully or building","right":"A trusted neighbour aunty"},{"left":"Anywhere, anytime","right":"Childline 1098 / 112"}],"relearn":"Wherever you are, there's usually a safe grown-up to turn to.","persona":"any","source":"get help / there-is-always-someone"},
  {"id":"su-1174","cat":"get-help","type":"match","hook":"Match the step to when it helps.","pairs":[{"left":"Save the proof first","right":"When harm is online"},{"left":"Bring a friend along","right":"When you're scared to tell alone"},{"left":"Write a note","right":"When the words won't come"},{"left":"Tell a second adult","right":"When the first didn't act"},{"left":"Call 1098 / 112","right":"When it's urgent and serious"}],"relearn":"There's a smart first step for every kind of trouble.","persona":"any","source":"get help / first-steps"},
  {"id":"su-1175","cat":"get-help","type":"match","hook":"Match the helper to where you'd find them.","pairs":[{"left":"School counsellor","right":"A quiet room at school"},{"left":"RKSK / NGO didi","right":"The youth or health club"},{"left":"Ward member or panchayat","right":"The village office"},{"left":"Childline","right":"A phone call to 1098"},{"left":"Your guardian","right":"At home"}],"relearn":"Real helpers exist all around you, near home and at school.","persona":"Asha","source":"get help / routes / RKSK"},
  {"id":"su-1176","cat":"get-help","type":"match","hook":"Match the situation to the safest move.","pairs":[{"left":"A boy is being threatened after class","right":"Get a teacher fast"},{"left":"A girl is left out every game","right":"Tell her you'll play with her"},{"left":"A nasty photo is being shared","right":"Don't forward it; tell an adult"},{"left":"A friend cries but won't say why","right":"Check in, then bring an adult"},{"left":"Someone is in real danger now","right":"Call 1098 / 112"}],"relearn":"The safest move depends on the scene; match it well.","persona":"any","source":"get help / judgement"},
  {"id":"su-1177","cat":"get-help","type":"match","hook":"Match the kind of harm to the right route.","pairs":[{"left":"Mean comments on a friend's photo","right":"Save proof and report it"},{"left":"Being shoved and threatened","right":"Get a trusted adult now"},{"left":"Left out for being a girl","right":"Tell a teacher and include her"},{"left":"A scary secret a friend shared","right":"Tell a safe adult kindly"},{"left":"An emergency right now","right":"1098 / 112"}],"relearn":"Different harms need different routes; pick the right one.","persona":"any","source":"get help / online + offline"},
  {"id":"su-1178","cat":"get-help","type":"match","hook":"Match the question to who can answer it.","pairs":[{"left":"\"Is this serious enough to report?\"","right":"A trusted adult"},{"left":"\"I feel anxious all the time\"","right":"A school counsellor"},{"left":"\"Who do I call if it's urgent?\"","right":"Childline 1098 / 112"},{"left":"\"Can I tell someone my own age first?\"","right":"Asha, the near-peer didi"},{"left":"\"Will telling get me in trouble?\"","right":"A parent you trust"}],"relearn":"For every question about getting help, someone has the answer.","persona":"Asha","source":"get help / who-answers"},
  {"id":"su-1179","cat":"get-help","type":"match","hook":"Match the brave move to its reward.","pairs":[{"left":"Telling an adult about harm","right":"Someone gets kept safe"},{"left":"Bringing a scared friend to help","right":"They feel less alone"},{"left":"Saving proof of online harm","right":"The adult can act on it"},{"left":"Asking when you're unsure","right":"You get guidance, not guesses"},{"left":"Trying again after one adult ignored you","right":"You reach one who helps"}],"relearn":"Every brave help-seeking move leads to something good.","persona":"any","source":"get help / help-seeking strength"},
  {"id":"su-1180","cat":"get-help","type":"match","hook":"Match the myth to the truth that beats it.","pairs":[{"left":"\"Telling is snitching\"","right":"Telling keeps people safe"},{"left":"\"Real kids handle it alone\"","right":"Even brave people get backup"},{"left":"\"Adults never listen\"","right":"Keep going till one does"},{"left":"\"It'll just make things worse\"","right":"A safe adult makes things better"},{"left":"\"I'd be overreacting\"","right":"When unsure, just ask"}],"relearn":"Each silencing myth has a truth that frees you to get help.","persona":"any","source":"get help / myth-vs-truth"},
  {"id":"su-1181","cat":"get-help","type":"match","hook":"Match the helper to the harm at the right time.","pairs":[{"left":"Right now, someone's in danger","right":"112"},{"left":"After school, you need to tell","right":"A parent at home"},{"left":"During break, a fight starts","right":"The teacher on duty"},{"left":"You feel scared but it's not urgent","right":"The counsellor tomorrow"},{"left":"Any time, day or night","right":"Childline 1098"}],"relearn":"The right helper depends on how urgent things are.","persona":"any","source":"get help / urgency"},
  {"id":"su-1182","cat":"get-help","type":"match","hook":"Match how to start telling to the worry it solves.","pairs":[{"left":"\"I need to tell you something\"","right":"When you don't know how to begin"},{"left":"\"Can we talk somewhere quiet?\"","right":"When others are listening"},{"left":"\"It's to keep a friend safe\"","right":"When you fear sounding like a tattle"},{"left":"Handing over a written note","right":"When your voice shakes"},{"left":"\"Can you help me figure this out?\"","right":"When you're unsure it's serious"}],"relearn":"The right opening line makes telling far less scary.","persona":"any","source":"get help / find the words to tell"},
  {"id":"su-1183","cat":"get-help","type":"match","hook":"Match the helper to one true thing about them.","pairs":[{"left":"Childline 1098","right":"Free, and there to help"},{"left":"112","right":"For real emergencies"},{"left":"School counsellor","right":"Trained to listen"},{"left":"A trusted teacher","right":"Knows the school rules"},{"left":"A near-peer didi","right":"Close to your own age"}],"relearn":"Each helper has a real strength; match the need to it.","persona":"Asha","source":"get help / helper-strengths"},
  {"id":"su-1184","cat":"get-help","type":"match","hook":"Match the wrong turn to the safer turn.","pairs":[{"left":"Confronting a bully alone","right":"Bring a teacher with you"},{"left":"Trusting a stranger online","right":"Tell a known, safe adult"},{"left":"Keeping a scary secret","right":"Tell a trusted grown-up"},{"left":"Forwarding a mean photo","right":"Save proof and report it"},{"left":"Giving up after one 'no'","right":"Ask the next safe adult"}],"relearn":"For every risky shortcut, there's a safer route to help.","persona":"any","source":"get help / safer-route"},
  {"id":"su-1185","cat":"get-help","type":"branch","hook":"You overhear a younger child being threatened in the stairwell.","options":[{"text":"Quietly go get a teacher right away","consequence":"A grown-up steps in fast and the child is safe.","outcome":"quick-thinking","best":true},{"text":"Rush in and shout at the older kid yourself","consequence":"Confronting alone isn't safe; fetch an adult instead."}],"debrief":"For something scary, the bravest move is fetching an adult fast.","relearn":"For scary or physical harm, get a trusted adult right away.","persona":"any","source":"get help / get-help move"},
  {"id":"su-1186","cat":"get-help","type":"branch","hook":"You want to tell, but the only adult around is a teacher you don't know well.","options":[{"text":"Tell them anyway; any safe teacher can help","consequence":"They listen and act; you didn't have to wait.","outcome":"resourceful","best":true},{"text":"Wait days for your favourite teacher instead","consequence":"Waiting lets harm go on; any safe adult can start."}],"debrief":"You don't need your favourite adult; any safe one can help today.","relearn":"Any trusted adult can be your first step, not just your favourite.","persona":"any","source":"get help / any-safe-adult"},
  {"id":"su-1187","cat":"get-help","type":"branch","hook":"A friend shows you cruel messages but says \"don't tell, I'll sort it.\"","options":[{"text":"Help save the proof and gently bring an adult in","consequence":"You both get backup and the messages can be acted on.","outcome":"savvy","best":true},{"text":"Reply to the bully with worse messages","consequence":"That pulls you into a fight; save proof and tell instead."}],"debrief":"For online harm: save proof, don't fight back, bring an adult in.","relearn":"For online harm, save proof, don't reply, and tell a trusted adult.","persona":"any","source":"get help / report move"},
  {"id":"su-1188","cat":"get-help","type":"branch","hook":"You told your class teacher and nothing seems to have changed.","options":[{"text":"Tell the counsellor too, and keep going","consequence":"A second adult takes it up and things start to move.","outcome":"persistent","best":true},{"text":"Decide adults just never help and stop","consequence":"If one adult doesn't act, the next one might; keep going."}],"debrief":"If the first adult doesn't act, tell another, and another.","relearn":"Keep telling trusted adults until someone really helps.","persona":"any","source":"get help / persistence"},
  {"id":"su-1189","cat":"get-help","type":"branch","hook":"You're scared that telling about a bully will make them target you.","options":[{"text":"Tell a trusted adult and ask them to keep it private","consequence":"A good adult protects you and handles it carefully.","outcome":"brave","best":true},{"text":"Stay silent so the bully never finds out","consequence":"Silence lets harm continue; a careful adult can protect you."}],"debrief":"A good adult can act on harm while keeping you safe.","relearn":"Telling a trusted adult is safe; they can protect your privacy.","persona":"Aarav","source":"get help / fear of telling"},
  {"id":"su-1190","cat":"get-help","type":"branch","hook":"Diya is too embarrassed to tell anyone she's being teased about her period.","options":[{"text":"Offer to go with her to a teacher or didi she trusts","consequence":"With you beside her, Diya finds the courage to tell.","outcome":"caring","best":true},{"text":"Tell her to just ignore it and toughen up","consequence":"Teasing isn't hers to bear alone; help her tell someone."}],"debrief":"Going with someone makes asking for help far less scary.","relearn":"Being beside someone helps them find the courage to get help.","persona":"Diya","source":"get help / support / never-blamed"},
  {"id":"su-1191","cat":"get-help","type":"branch","hook":"A new student shares a secret about being hurt, then begs you to keep it.","options":[{"text":"Gently say this one needs a safe adult","consequence":"You keep them safe even if they're upset for now.","outcome":"caring","best":true},{"text":"Promise to keep it secret no matter what","consequence":"Some secrets aren't safe to keep; tell an adult."}],"debrief":"A secret about someone being hurt is not a safe one to keep.","relearn":"For serious harm, tell a trusted adult even if asked to keep it secret.","persona":"any","source":"get help / safe vs unsafe secrets"},
  {"id":"su-1192","cat":"get-help","type":"branch","hook":"It's late evening and a child nearby is in real danger, no grown-up in sight.","options":[{"text":"Call Childline 1098 or 112 straight away","consequence":"Help is reached fast; that's exactly what the number is for.","outcome":"clear-headed","best":true},{"text":"Try to rescue the child by yourself","consequence":"Don't put yourself in danger; call for help first."}],"debrief":"When it's urgent and no adult is around, the helpline is the route.","relearn":"For real danger with no adult around, call Childline 1098 / 112.","persona":"any","source":"get help / helpline"},
  {"id":"su-1193","cat":"get-help","type":"branch","hook":"You're not sure if what you saw was 'bad enough' to bother an adult about.","options":[{"text":"Ask a trusted adult to help you decide","consequence":"You get guidance instead of guessing on your own.","outcome":"smart","best":true},{"text":"Decide alone it's probably nothing","consequence":"When unsure, an adult can help you judge; just ask."}],"debrief":"When you're unsure, asking an adult is itself a smart move.","relearn":"When unsure if something is serious, ask a trusted adult.","persona":"any","source":"get help / when-unsure"},
  {"id":"su-1194","cat":"get-help","type":"branch","hook":"A friend says \"no point telling, teachers here never do anything.\"","options":[{"text":"Suggest the counsellor or Childline instead","consequence":"You find a route that works even when one door is shut.","outcome":"resourceful","best":true},{"text":"Agree and give up on getting any help","consequence":"If one route is stuck, another can work; don't give up."}],"debrief":"If one route feels stuck, there's always another way to get help.","relearn":"If school feels stuck, a counsellor or Childline 1098 is another route.","persona":"any","source":"get help / alternate routes"},
  {"id":"su-1195","cat":"get-help","type":"branch","hook":"Your friend wants to call for help but freezes when it's time to speak.","options":[{"text":"Sit beside them and help say the first words","consequence":"With you there, the words come and help is reached.","outcome":"supportive","best":true},{"text":"Tell them to call back when they're braver","consequence":"Courage is acting through fear; help them start now."}],"debrief":"Helping say the first words turns a freeze into a brave call.","relearn":"You can help a frozen friend find the first words to get help.","persona":"any","source":"get help / find-the-words / freezing-ok"},
  {"id":"su-1196","cat":"get-help","type":"branch","hook":"You'd rather tell someone your own age than a parent or teacher.","options":[{"text":"Talk to Asha, the NGO didi kids confide in","consequence":"A near-peer you trust counts as real help too.","outcome":"open","best":true},{"text":"Post about it for strangers online to weigh in","consequence":"Strangers aren't safe; a trusted near-peer is."}],"debrief":"A trusted near-peer like Asha is a real route when adults feel hard.","relearn":"A trusted near-peer counts as a real route to help.","persona":"Asha","source":"get help / near-peer route"},
  {"id":"su-1197","cat":"get-help","type":"branch","hook":"You saw harm but worry telling an adult makes you a tattle-tale.","options":[{"text":"Tell anyway; this keeps a classmate safe","consequence":"Telling to keep someone safe is the right kind of telling.","outcome":"clear","best":true},{"text":"Stay quiet so no one calls you a snitch","consequence":"Telling to protect isn't snitching; go ahead and tell."}],"debrief":"Telling to keep someone safe is the opposite of tattling.","relearn":"Telling to keep someone safe is not tattling.","persona":"any","source":"get help / tattle-vs-tell"},
  {"id":"su-1198","cat":"get-help","type":"branch","hook":"A friend is being harmed at home and feels no one could help.","options":[{"text":"Tell them about Childline 1098, free and for kids","consequence":"They learn there's a safe, private number any time.","outcome":"informed","best":true},{"text":"Tell them nothing can be done about home stuff","consequence":"Help exists for this too; tell them about Childline 1098."}],"debrief":"Even when home feels stuck, Childline 1098 is there for children.","relearn":"Childline 1098 is free, private help for children, any hour.","persona":"any","source":"get help / childline awareness"},
  {"id":"su-1199","cat":"get-help","type":"branch","hook":"You told a friend's secret about being hurt; now they're angry.","options":[{"text":"Explain you told a safe adult because you care","consequence":"They see you acted to keep them safe, not to betray them.","outcome":"honest","best":true},{"text":"Promise never to tell anyone anything again","consequence":"For serious harm, telling a safe adult is still right."}],"debrief":"Telling a safe adult about real harm is caring, even if it upsets them.","relearn":"Telling a safe adult about serious harm is caring, not betrayal.","persona":"any","source":"get help / why-we-tell"},
  {"id":"su-1200","cat":"get-help","type":"strike-rewrite","hook":"\"Telling an adult is just snitching.\"","myth":{"un":"Telling an adult is just snitching.","re":"Telling to keep someone safe is not snitching.","why":"Snitching gets someone in trouble; telling keeps someone safe."},"relearn":"Telling to keep someone safe is different from snitching.","persona":"Asha","source":"get help / tattle-vs-tell"},
  {"id":"su-1201","cat":"get-help","type":"strike-rewrite","hook":"\"If I tell, it'll only make things worse.\"","myth":{"un":"If I tell, it'll only make things worse.","re":"A trusted adult can make a harmful situation better.","why":"Adults can do things to stop harm that a child can't alone."},"relearn":"A trusted adult can make a harmful situation better, not worse.","persona":"any","source":"get help / help works"},
  {"id":"su-1202","cat":"get-help","type":"strike-rewrite","hook":"\"Helplines are only for huge emergencies, not kids like me.\"","myth":{"un":"Childline isn't really for ordinary kids.","re":"Childline 1098 is free, private help for any child.","why":"It runs all day and night, just for children who need help."},"relearn":"Childline 1098 is for any child who needs help, any time.","persona":"any","source":"get help / childline"},
  {"id":"su-1203","cat":"get-help","type":"strike-rewrite","hook":"\"I should sort my own problems out without bothering anyone.\"","myth":{"un":"I should sort serious problems out all by myself.","re":"Getting help with serious harm is the smart, strong choice.","why":"Even brave people reach for backup when it's serious."},"relearn":"Getting help with serious harm is smart and strong, not weak.","persona":"Aarav","source":"get help / help-seeking strength"},
  {"id":"su-1204","cat":"get-help","type":"strike-rewrite","hook":"\"If I'm not totally sure it's serious, I shouldn't say anything.\"","myth":{"un":"If I'm not sure it's serious, I shouldn't say anything.","re":"When you're unsure, asking an adult is exactly the right move.","why":"An adult can help you judge instead of guessing alone."},"relearn":"When unsure, asking a trusted adult is the right move.","persona":"any","source":"get help / when-unsure"},
  {"id":"su-1205","cat":"get-help","type":"strike-rewrite","hook":"\"If one teacher won't help, no one will.\"","myth":{"un":"If one teacher won't help, no one ever will.","re":"If one adult doesn't act, another one can.","why":"There's more than one safe grown-up to turn to."},"relearn":"If one adult doesn't help, another one can; keep going.","persona":"any","source":"get help / persistence"},
  {"id":"su-1206","cat":"get-help","type":"strike-rewrite","hook":"\"A real friend keeps every secret, no matter what.\"","myth":{"un":"A real friend keeps every secret, no matter what.","re":"Some secrets need a safe adult to keep a friend safe.","why":"A secret about someone getting hurt is not safe to keep."},"relearn":"A secret about someone being hurt needs a safe adult.","persona":"any","source":"get help / safe vs unsafe secrets"},
  {"id":"su-1207","cat":"get-help","type":"strike-rewrite","hook":"\"Asking for help means I can't handle anything.\"","myth":{"un":"Asking for help means I can't handle anything.","re":"Asking for the right help is a sign of good sense.","why":"Knowing when to get backup is its own kind of strong."},"relearn":"Asking for the right help shows good sense, not weakness.","persona":"any","source":"get help / help-seeking"},
  {"id":"su-1208","cat":"get-help","type":"sort","hook":"Sort: a safe place to get help, or not?","items":[{"id":"a","text":"The school counsellor's room"},{"id":"b","text":"A chat with a stranger in a game app"},{"id":"c","text":"Telling a parent you trust at home"},{"id":"d","text":"Asking the older boy who started it"},{"id":"e","text":"Calling Childline 1098"},{"id":"f","text":"A private message from an unknown account"}],"bins":[{"id":"safe","label":"Safe to use","valence":"pos"},{"id":"unsafe","label":"Not safe","valence":"neg"}],"key":{"a":"safe","b":"unsafe","c":"safe","d":"unsafe","e":"safe","f":"unsafe"},"relearn":"Get help from trusted people and real helplines, not strangers.","persona":"any","source":"get help / safe routes"},
  {"id":"su-1209","cat":"get-help","type":"sort","hook":"Sort: that's telling, or that's tattling?","items":[{"id":"a","text":"Reporting a child being threatened"},{"id":"b","text":"Reporting that a friend whispered in class"},{"id":"c","text":"Telling so someone stays safe"},{"id":"d","text":"Telling just to get a classmate scolded"},{"id":"e","text":"Saying a kid is being hurt at home"},{"id":"f","text":"Complaining a friend took the last ladoo"}],"bins":[{"id":"tell","label":"Telling","valence":"tell"},{"id":"tattle","label":"Tattling","valence":"uhoh"}],"key":{"a":"tell","b":"tattle","c":"tell","d":"tattle","e":"tell","f":"tattle"},"relearn":"Telling keeps someone safe; tattling just gets someone in trouble.","persona":"any","source":"get help / tattle-vs-tell"},
  {"id":"su-1210","cat":"get-help","type":"sort","hook":"Sort: handle it yourself, or this one needs an adult?","items":[{"id":"a","text":"A friend won't share the cricket bat"},{"id":"b","text":"Someone is being threatened and scared"},{"id":"c","text":"You disagree on the rules of a game"},{"id":"d","text":"A child is being hurt over and over"},{"id":"e","text":"Two classmates are sulking"},{"id":"f","text":"Cruel photos of a girl are being shared"}],"bins":[{"id":"self","label":"You can handle it","valence":"neutral"},{"id":"adult","label":"Get an adult","valence":"tell"}],"key":{"a":"self","b":"adult","c":"self","d":"adult","e":"self","f":"adult"},"relearn":"Small stuff you can handle; serious harm always needs an adult.","persona":"any","source":"get help / judgement"},
  {"id":"su-1211","cat":"get-help","type":"sort","hook":"Sort: a real route to help, or a dead end?","items":[{"id":"a","text":"A trusted teacher"},{"id":"b","text":"Pretending you saw nothing"},{"id":"c","text":"The school counsellor"},{"id":"d","text":"Waiting for it to fix itself"},{"id":"e","text":"Childline 1098 / 112"},{"id":"f","text":"Hoping someone else acts"}],"bins":[{"id":"route","label":"A real route","valence":"pos"},{"id":"dead","label":"A dead end","valence":"neg"}],"key":{"a":"route","b":"dead","c":"route","d":"dead","e":"route","f":"dead"},"relearn":"Real routes to help are people and helplines, not waiting and hoping.","persona":"any","source":"get help / routes"},
  {"id":"su-1212","cat":"get-help","type":"sort","hook":"Sort: a smart first step, or a risky one?","items":[{"id":"a","text":"Saving proof of online harm"},{"id":"b","text":"Forwarding the mean photo to friends"},{"id":"c","text":"Bringing a friend when you tell"},{"id":"d","text":"Confronting a bully all alone"},{"id":"e","text":"Writing a note when words won't come"},{"id":"f","text":"Trusting a stranger to 'sort it'"}],"bins":[{"id":"smart","label":"Smart step","valence":"pos"},{"id":"risky","label":"Risky step","valence":"neg"}],"key":{"a":"smart","b":"risky","c":"smart","d":"risky","e":"smart","f":"risky"},"relearn":"Smart steps keep you safe; risky ones can make things worse.","persona":"any","source":"get help / first-steps"},
  {"id":"su-1213","cat":"get-help","type":"sort","hook":"Sort each helper by when you'd reach for them.","items":[{"id":"a","text":"112, when someone's in danger now"},{"id":"b","text":"The counsellor, when you feel low"},{"id":"c","text":"Childline 1098, any hour you need it"},{"id":"d","text":"A parent, to talk it over at home"},{"id":"e","text":"The teacher, for trouble at school"},{"id":"f","text":"Asha didi, to confide in a near-peer"}],"bins":[{"id":"urgent","label":"For urgent danger","valence":"tell"},{"id":"support","label":"For ongoing support","valence":"pos"}],"key":{"a":"urgent","b":"support","c":"urgent","d":"support","e":"support","f":"support"},"relearn":"Some helpers are for urgent danger; others for steady support.","persona":"Asha","source":"get help / urgency"},
  {"id":"su-1214","cat":"get-help","type":"sort","hook":"Sort: that belief helps you get help, or holds you back?","items":[{"id":"a","text":"\"Asking for help is brave\""},{"id":"b","text":"\"Telling makes me a snitch\""},{"id":"c","text":"\"Any safe adult can be my first step\""},{"id":"d","text":"\"I'm too small to do anything\""},{"id":"e","text":"\"If one adult won't act, I'll tell another\""},{"id":"f","text":"\"It's none of my business\""}],"bins":[{"id":"helps","label":"Helps you act","valence":"pos"},{"id":"holds","label":"Holds you back","valence":"neg"}],"key":{"a":"helps","b":"holds","c":"helps","d":"holds","e":"helps","f":"holds"},"relearn":"Some beliefs free you to get help; others keep you stuck and silent.","persona":"any","source":"get help / beliefs"},
  {"id":"su-1215","cat":"get-help","type":"sort","hook":"Sort: who is a safe grown-up to tell, or not?","items":[{"id":"a","text":"Your class teacher"},{"id":"b","text":"A grown-up who tells you to keep it secret"},{"id":"c","text":"A neighbour aunty you trust"},{"id":"d","text":"The person who did the harm"},{"id":"e","text":"The school counsellor"},{"id":"f","text":"A stranger who messaged you first"}],"bins":[{"id":"safe","label":"Safe to tell","valence":"pos"},{"id":"notsafe","label":"Not safe","valence":"neg"}],"key":{"a":"safe","b":"notsafe","c":"safe","d":"notsafe","e":"safe","f":"notsafe"},"relearn":"Safe grown-ups listen and help; they don't push you to stay silent.","persona":"any","source":"get help / who-is-safe"},
  {"id":"su-1216","cat":"get-help","type":"role-play","hook":"You're walking your nervous friend to the counsellor's room.","setup":"Steady them at the door. Say:","yourLine":[{"text":"\"I'll wait right here while you talk to them.\"","best":true},{"text":"\"Good luck, you're on your own from here.\""}],"relearn":"Staying close makes asking for help feel possible.","persona":"Diya","source":"get help / support"},
  {"id":"su-1217","cat":"get-help","type":"role-play","hook":"You need to start a hard conversation with a trusted teacher.","setup":"Open it clearly. Say:","yourLine":[{"text":"\"Sir, can we talk privately? It's important.\"","best":true},{"text":"Mumble something and hope they ask"}],"relearn":"A clear opening helps a trusted adult understand and act.","persona":"any","source":"get help / voice"},
  {"id":"su-1218","cat":"get-help","type":"role-play","hook":"A friend says telling an adult would make them a tattle-tale.","setup":"Reassure them. Say:","yourLine":[{"text":"\"This is telling to keep you safe, not tattling.\"","best":true},{"text":"\"Maybe you're right, let's just stay quiet.\""}],"relearn":"Naming the difference helps a friend feel okay about telling.","persona":"Asha","source":"get help / tattle-vs-tell"},
  {"id":"su-1219","cat":"get-help","type":"role-play","hook":"Your friend doesn't know how to begin telling about ongoing harm.","setup":"Give them an easy first line. Say:","yourLine":[{"text":"\"Just say: I need help with something serious.\"","best":true},{"text":"\"Only tell if you can explain the whole thing perfectly.\""}],"relearn":"One short, honest line is enough to begin asking for help.","persona":"any","source":"get help / find-the-words"},
  {"id":"su-1220","cat":"get-help","type":"role-play","hook":"A friend feels silly calling a helpline over something scary.","setup":"Encourage them. Say:","yourLine":[{"text":"\"Childline 1098 is exactly for moments like this.\"","best":true},{"text":"\"You'll probably just be wasting their time.\""}],"relearn":"Helplines are meant for scary moments; using them is right.","persona":"any","source":"get help / childline"},
  {"id":"su-1221","cat":"get-help","type":"role-play","hook":"Your friend wants to give up after one adult brushed them off.","setup":"Keep them going. Say:","yourLine":[{"text":"\"Let's try the counsellor; one no isn't the end.\"","best":true},{"text":"\"I guess no one's going to help, let's drop it.\""}],"relearn":"One 'no' isn't the end; the next adult might be the one.","persona":"any","source":"get help / persistence"},
  {"id":"su-1222","cat":"get-help","type":"role-play","hook":"A friend is unsure whether what happened is 'serious enough' to report.","setup":"Help them decide. Say:","yourLine":[{"text":"\"Let's ask an adult to help us figure it out.\"","best":true},{"text":"\"If you're not sure, just forget about it.\""}],"relearn":"When unsure, asking an adult to help decide is the smart move.","persona":"any","source":"get help / when-unsure"},
  {"id":"su-1223","cat":"get-help","type":"role-play","hook":"Aarav froze last time and now hesitates to ask a teacher for help.","setup":"Give him a second-chance line. Say:","yourLine":[{"text":"\"You froze before; this time we'll tell together.\"","best":true},{"text":"\"You missed your chance already, so why bother now.\""}],"relearn":"Freezing once is okay; you always get another chance to ask.","persona":"Aarav","source":"get help / second chance"},
  {"id":"su-1224","cat":"get-help","type":"spot","hook":"Tap the things that show safely getting help.","scene":[{"id":"a","text":"A girl quietly tells the counsellor","trick":false},{"id":"b","text":"A boy saves proof of mean messages","trick":false},{"id":"c","text":"A kid keeps a 'I'm being hurt' secret","trick":true},{"id":"d","text":"Two friends go to the teacher together","trick":false},{"id":"e","text":"A child meets a stranger to 'fix it'","trick":true}],"why":"Counsellors, saved proof and a teacher are safe; harm-secrets and strangers are not.","relearn":"Safe help is trusted people, not harm-secrets or strangers.","persona":"any","source":"get help / spot-safe-help"},
  {"id":"su-1225","cat":"get-help","type":"spot","hook":"Tap the moves that are real telling, not tattling.","scene":[{"id":"a","text":"Reporting that a child is being threatened","trick":false},{"id":"b","text":"Telling to keep a friend safe","trick":false},{"id":"c","text":"Reporting a classmate just to get them scolded","trick":true},{"id":"d","text":"Saying a kid is being hurt and needs help","trick":false},{"id":"e","text":"Telling on a friend to win a fight with them","trick":true}],"why":"Telling to keep someone safe is real telling; doing it for trouble is tattling.","relearn":"Telling keeps someone safe; tattling just gets someone in trouble.","persona":"any","source":"get help / spot-tell-vs-tattle"},
  {"id":"su-1226","cat":"get-help","type":"spot","hook":"Tap the choices that are safe ways to get help.","scene":[{"id":"a","text":"Calling Childline 1098 when it's urgent","trick":false},{"id":"b","text":"Bringing a friend along to tell a teacher","trick":false},{"id":"c","text":"Confronting the bully alone in the field","trick":true},{"id":"d","text":"Telling a parent you trust at home","trick":false},{"id":"e","text":"Asking the person who did the harm to fix it","trick":true}],"why":"A helpline, a friend along and a trusted parent are safe; facing a bully alone is not.","relearn":"Safe routes don't put you alone with the bully or harm-doer.","persona":"any","source":"get help / spot-safe-routes"},
  {"id":"su-1227","cat":"get-help","type":"spot","hook":"Tap the trusted helpers you'd be right to turn to.","scene":[{"id":"a","text":"A school counsellor trained to listen","trick":false},{"id":"b","text":"A stranger online promising to 'sort it'","trick":true},{"id":"c","text":"Childline 1098, free help for children","trick":false},{"id":"d","text":"A teacher you trust","trick":false},{"id":"e","text":"An older bully who says he'll handle it","trick":true}],"why":"Counsellors, Childline and a trusted teacher really help; a stranger online or a bully are not safe.","relearn":"Turn to trusted helpers, not strangers online or the bully.","persona":"any","source":"get help / spot-trusted"},
  {"id":"su-1228","cat":"get-help","type":"spot","hook":"Tap the true things about asking for help.","scene":[{"id":"a","text":"Asking for help is brave and smart","trick":false},{"id":"b","text":"You only get one chance to ask","trick":true},{"id":"c","text":"Any safe adult can be your first step","trick":false},{"id":"d","text":"Helplines are only for grown-ups","trick":true},{"id":"e","text":"If one adult won't act, you can tell another","trick":false}],"why":"You can ask again and again, any safe adult can start, and Childline 1098 is for children too.","relearn":"You can keep asking; any safe adult and Childline 1098 are there.","persona":"any","source":"get help / spot-true-help"},
  {"id":"su-1229","cat":"get-help","type":"spot","hook":"Tap the smart steps for online harm.","scene":[{"id":"a","text":"Save a screenshot as proof","trick":false},{"id":"b","text":"Tell a trusted adult what's happening","trick":false},{"id":"c","text":"Forward the mean post to your group","trick":true},{"id":"d","text":"Stop replying to the person harming you","trick":false},{"id":"e","text":"Reply with something even nastier","trick":true}],"why":"Save proof, tell an adult and stop replying; never forward harm or fire back.","relearn":"For online harm: save proof, tell an adult, don't forward or fire back.","persona":"any","source":"get help / spot-online"},
  {"id":"su-1230","cat":"get-help","type":"spot","hook":"Tap what a good, safe adult does when you ask for help.","scene":[{"id":"a","text":"Listens carefully without blaming you","trick":false},{"id":"b","text":"Takes it seriously and acts","trick":false},{"id":"c","text":"Tells you to keep it a secret from everyone","trick":true},{"id":"d","text":"Helps keep you safe","trick":false},{"id":"e","text":"Says it was probably your own fault","trick":true}],"why":"A safe adult listens, acts and protects you; one who blames you or demands secrecy is not safe.","relearn":"A safe adult listens and protects you; never blames or silences you.","persona":"any","source":"get help / spot-safe-adult"},
  {"id":"su-1231","cat":"get-help","type":"spot","hook":"Tap the safe ways to start telling a trusted adult.","scene":[{"id":"a","text":"\"Can we talk somewhere quiet?\"","trick":false},{"id":"b","text":"\"I need help with something serious\"","trick":false},{"id":"c","text":"Wait until you can give a perfect speech","trick":true},{"id":"d","text":"Hand over a written note if words won't come","trick":false},{"id":"e","text":"Only tell if you have no fear at all","trick":true}],"why":"A quiet start, a short line or a note all work; you never need a perfect speech or zero fear.","relearn":"A quiet word, short line or note is enough; no perfect speech needed.","persona":"any","source":"get help / spot-how-to-tell"},
  {"id":"su-1232","cat":"get-help","type":"reflect","hook":"Lensy asks who you'd feel safest telling.","prompt":"If something felt scary, who would you most want to tell first?","options":["A parent or guardian","A teacher I trust","The school counsellor","Childline 1098 / 112"],"affirm":"Knowing your go-to person makes asking for help so much easier.","relearn":"Having a go-to person makes asking for help easier.","persona":"Lensy","source":"get help / identity"},
  {"id":"su-1233","cat":"get-help","type":"reflect","hook":"Lensy asks what makes telling feel hard for you.","prompt":"What makes it hardest for you to ask a grown-up for help?","options":["Worry I'm overreacting","Fear of being called a tattle","Not knowing the right words","Thinking I should handle it alone"],"affirm":"Noticing what holds you back is the first step to telling anyway.","relearn":"Noticing what holds you back is the first step to telling anyway.","persona":"Lensy","source":"get help / self-awareness"},
  {"id":"su-1234","cat":"get-help","type":"reflect","hook":"Lensy asks what would help a friend feel brave enough to tell.","prompt":"If a friend was scared to ask for help, what would you do?","options":["Go with them","Help them find the words","Remind them it's brave","Sit with them while they call"],"affirm":"Any of these makes you the kind of friend who helps someone get help.","relearn":"Going along, finding words or just being there all help a friend tell.","persona":"Lensy","source":"get help / empathy"},
  {"id":"su-1235","cat":"get-help","type":"reflect","hook":"Lensy asks where you'd start if you didn't know who to trust.","prompt":"If you weren't sure who to trust, where might you start?","options":["Any safe adult nearby","A teacher I know a little","Childline 1098","Asha, a near-peer didi"],"affirm":"There's always a first door to knock on; you don't have to be sure.","relearn":"You don't have to be sure who to trust to take a first step.","persona":"Lensy","source":"get help / there-is-always-someone"},
  {"id":"su-1236","cat":"get-help","type":"reflect","hook":"Lensy asks how it feels to imagine asking for help.","prompt":"When you picture asking a grown-up for help, how does it feel?","options":["Scary but doable","A bit of a relief","Still pretty hard","Better with a friend beside me"],"affirm":"However it feels, choosing to ask is a brave and caring thing to do.","relearn":"However it feels, choosing to ask for help is brave.","persona":"Lensy","source":"get help / feelings"},
  {"id":"su-1237","cat":"get-help","type":"reflect","hook":"Lensy asks what you'd want a younger kid to know about help.","prompt":"What's one thing you'd tell a younger child about getting help?","options":["Telling isn't tattling","There's always someone to turn to","Asking is brave, not weak","Childline 1098 is there day and night"],"affirm":"Passing this on makes you an upstander for the kids coming after you.","relearn":"Passing on what you know about help makes you an upstander.","persona":"Lensy","source":"get help / pass-it-on"},
  {"id":"su-1238","cat":"get-help","type":"reflect","hook":"Lensy asks what kind of helper you'd want to be one day.","prompt":"If a child came to you for help, what would you want to be like?","options":["Someone who listens","Someone who believes them","Someone who never blames them","Someone who helps them stay safe"],"affirm":"Wanting to be that helper says a lot about the upstander you are.","relearn":"Wanting to listen, believe and protect is what a helper does.","persona":"Lensy","source":"get help / identity-helper"},
  {"id":"su-1239","cat":"get-help","type":"reflect","hook":"Lensy asks what would make your school easier to get help in.","prompt":"What would make it easier for kids at your school to ask for help?","options":["A counsellor everyone knows","Teachers who really listen","Knowing about Childline 1098","Friends who go along with you"],"affirm":"Caring about easier help for everyone is upstander thinking.","relearn":"Wanting help to be easier for everyone is upstander thinking.","persona":"Lensy","source":"get help / belonging"},
  {"id":"su-1260","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / chores","hook":"In the kitchen. Spot what's harmful.","why":"Mocking a boy for housework treats helping as shameful by gender.","relearn":"Mocking a boy for doing chores 'like a girl' is gender-based harm.","scene":[{"id":"a","text":"Cousins mock a boy for washing dishes, calling it 'girls' work'","trick":true},{"id":"b","text":"The tap is running","trick":false},{"id":"c","text":"\"You're not a real boy,\" they laugh","trick":true},{"id":"d","text":"Plates are drying on the rack","trick":false},{"id":"e","text":"Someone wipes the counter","trick":false}]},
  {"id":"su-1261","cat":"name-the-harm","type":"spot","persona":"Diya","source":"gender-based harm / period","hook":"Near the staircase. Spot what's harmful.","why":"Whispering and pointing about a period stain shames a girl for her body.","relearn":"Teasing a girl over a period stain is body-mocking harm.","scene":[{"id":"a","text":"Two boys point and whisper at a stain on Diya's skirt","trick":true},{"id":"b","text":"Students climb the stairs","trick":false},{"id":"c","text":"One mimics her walk to get a laugh","trick":true},{"id":"d","text":"A poster hangs on the wall","trick":false},{"id":"e","text":"The corridor light is on","trick":false}]},
  {"id":"su-1262","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / online","hook":"On the phone. Spot what's harmful.","why":"Rating girls' looks for a 'list' reduces them to bodies; it's online harm.","relearn":"Making a 'rating list' of girls' bodies is online gender-based harm.","scene":[{"id":"a","text":"A boy makes a chat 'list' rating girls' bodies out of ten","trick":true},{"id":"b","text":"The phone is at low battery","trick":false},{"id":"c","text":"He dares others to add 'scores'","trick":true},{"id":"d","text":"A meme about exams is posted","trick":false},{"id":"e","text":"Someone shares a song link","trick":false}]},
  {"id":"su-1263","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / threats","hook":"Behind the school. Spot what's harmful.","why":"Threatening a girl to scare her into doing what you say is serious harm.","relearn":"Threatening to scare or control a girl is harm; that's a get-help moment.","scene":[{"id":"a","text":"An older boy threatens a girl to scare her into doing what he says","trick":true},{"id":"b","text":"There's a wall with graffiti","trick":false},{"id":"c","text":"\"Do what I say or you'll be sorry,\" he warns","trick":true},{"id":"d","text":"A dog naps in the shade","trick":false},{"id":"e","text":"Bicycles lean by the gate","trick":false}]},
  {"id":"su-1264","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / exclusion","hook":"In the computer lab. Spot what's harmful.","why":"Pushing girls off the keyboards because 'tech is for boys' is exclusion harm.","relearn":"Blocking girls from tech 'because it's for boys' is exclusion harm.","scene":[{"id":"a","text":"Boys hog all the keyboards, saying 'coding isn't for girls'","trick":true},{"id":"b","text":"The screens are switched on","trick":false},{"id":"c","text":"They shoo a girl away from a seat","trick":true},{"id":"d","text":"A chart of mouse parts is on the wall","trick":false},{"id":"e","text":"The teacher logs into a laptop","trick":false}]},
  {"id":"su-1265","cat":"name-the-harm","type":"spot","persona":"Aarav","source":"gender-based harm / norms","hook":"In the changing room. Spot what's harmful.","why":"Cornering and shoving a boy for being 'soft' is harm, not toughening him up.","relearn":"Shoving a boy for being 'soft' is gender-based harm, not toughening.","scene":[{"id":"a","text":"Boys corner Aarav and shove him for 'crying like a girl'","trick":true},{"id":"b","text":"Kit bags are on the bench","trick":false},{"id":"c","text":"\"Toughen up or stay out,\" they sneer","trick":true},{"id":"d","text":"A water bottle sits on the floor","trick":false},{"id":"e","text":"Jerseys hang on hooks","trick":false}]},
  {"id":"su-1266","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / public","hook":"At the bus stop. Spot what's harmful.","why":"Calling out 'comments' about a girl's body is harassment, not a compliment.","relearn":"Unwanted 'comments' on a girl's body in public is harassment.","scene":[{"id":"a","text":"Some boys call out unwanted 'comments' about a schoolgirl's body","trick":true},{"id":"b","text":"An auto waits at the corner","trick":false},{"id":"c","text":"They keep it up even as she looks away, uncomfortable","trick":true},{"id":"d","text":"A vendor sells peanuts","trick":false},{"id":"e","text":"The bus is a little late","trick":false}]},
  {"id":"su-1267","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / rumour","hook":"In the canteen. Spot what's harmful.","why":"Spreading a sexual rumour about a girl damages her on purpose; it's harm.","relearn":"Spreading a sexual rumour about a girl is gender-based harm.","scene":[{"id":"a","text":"Kids spread a made-up 'who she likes' rumour to shame a girl","trick":true},{"id":"b","text":"Trays are stacked by the counter","trick":false},{"id":"c","text":"They add cruel made-up details each time","trick":true},{"id":"d","text":"Samosas are being served","trick":false},{"id":"e","text":"A bench wobbles slightly","trick":false}]},
  {"id":"su-1268","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / exclusion","hook":"On the field. Spot what's harmful.","why":"Giving girls only the 'fetch the ball' role keeps them out of the real game.","relearn":"Sidelining girls into non-playing roles by gender is exclusion harm.","scene":[{"id":"a","text":"Boys make girls 'just fetch the ball' and never let them play","trick":true},{"id":"b","text":"The pitch is freshly marked","trick":false},{"id":"c","text":"\"Girls only watch,\" the captain rules","trick":true},{"id":"d","text":"A whistle hangs on a cord","trick":false},{"id":"e","text":"Cones mark the goal","trick":false}]},
  {"id":"su-1269","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / online","hook":"In the group chat. Spot what's harmful.","why":"Photoshopping a classmate's face onto a cruel body image is online harm.","relearn":"Editing a classmate's photo into a cruel image is online harm.","scene":[{"id":"a","text":"Someone edits a girl's face onto a humiliating picture and posts it","trick":true},{"id":"b","text":"The chat has 30 members","trick":false},{"id":"c","text":"They tag her so she sees it","trick":true},{"id":"d","text":"A timetable photo is pinned","trick":false},{"id":"e","text":"An emoji poll is running","trick":false}]},
  {"id":"su-1270","cat":"name-the-harm","type":"spot","persona":"Diya","source":"gender-based harm / shaming","hook":"In the corridor. Spot what's harmful.","why":"Calling a girl 'dirty' for menstruating shames a normal, healthy body.","relearn":"Calling a girl 'dirty' for menstruating is body-shaming harm.","scene":[{"id":"a","text":"A boy calls Diya 'dirty' for needing the toilet during class","trick":true},{"id":"b","text":"A notice board lists exam dates","trick":false},{"id":"c","text":"He tells others to 'stay away from her'","trick":true},{"id":"d","text":"Shoes are lined by a door","trick":false},{"id":"e","text":"A bell schedule is taped up","trick":false}]},
  {"id":"su-1271","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / control","hook":"Near the gate. Spot what's harmful.","why":"Grabbing a girl's wrist to stop her leaving controls her by force; it's harm.","relearn":"Grabbing someone to control where they go is harm.","scene":[{"id":"a","text":"An older boy grabs a girl's wrist so she can't walk away","trick":true},{"id":"b","text":"A guard checks ID cards","trick":false},{"id":"c","text":"\"You're not going anywhere,\" he says","trick":true},{"id":"d","text":"A rickshaw idles outside","trick":false},{"id":"e","text":"Students file out at home time","trick":false}]},
  {"id":"su-1272","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / mocking","hook":"In art class. Spot what's harmful.","why":"Tearing a boy's painting because 'boys don't do flowers' is gender-based harm.","relearn":"Destroying a boy's work to enforce gender rules is harm.","scene":[{"id":"a","text":"Kids rip a boy's flower painting, saying it's 'girly rubbish'","trick":true},{"id":"b","text":"Brushes soak in a jar","trick":false},{"id":"c","text":"\"Paint something manly,\" they taunt","trick":true},{"id":"d","text":"A still-life is set on the table","trick":false},{"id":"e","text":"Aprons hang by the sink","trick":false}]},
  {"id":"su-1273","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / online","hook":"After a video call. Spot what's harmful.","why":"Screenshotting a girl to mock her body and sharing it is online harm.","relearn":"Screenshotting and mocking someone's body online is harm.","scene":[{"id":"a","text":"A boy screenshots a girl on a call to mock her body in another chat","trick":true},{"id":"b","text":"The call had eight people","trick":false},{"id":"c","text":"He captions it with a cruel gendered joke","trick":true},{"id":"d","text":"Someone shares notes after","trick":false},{"id":"e","text":"The wifi drops for a second","trick":false}]},
  {"id":"su-1274","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / exclusion","hook":"At the science fair. Spot what's harmful.","why":"Crediting only the boys for a mixed team's project erases the girls' work.","relearn":"Erasing girls' work and crediting only boys is gender-based harm.","scene":[{"id":"a","text":"Boys take all credit, saying 'the girls didn't really build it'","trick":true},{"id":"b","text":"A volcano model bubbles","trick":false},{"id":"c","text":"They tell judges to 'ignore the girls'","trick":true},{"id":"d","text":"Posters line the hall","trick":false},{"id":"e","text":"A fan cools the room","trick":false}]},
  {"id":"su-1275","cat":"name-the-harm","type":"spot","persona":"Aarav","source":"gender-based harm / norms","hook":"In the queue. Spot what's harmful.","why":"Snatching a boy's tiffin and calling his food 'girly' is bullying, not banter.","relearn":"Bullying a boy over 'girly' choices is gender-based harm.","scene":[{"id":"a","text":"Boys snatch Aarav's lunch, sneering his pink box is 'for girls'","trick":true},{"id":"b","text":"The line moves slowly","trick":false},{"id":"c","text":"\"Boys don't carry that,\" they jeer","trick":true},{"id":"d","text":"A water cooler hums","trick":false},{"id":"e","text":"A teacher counts heads","trick":false}]},
  {"id":"su-1276","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / touch","hook":"On the stairs. Spot what's harmful.","why":"Deliberately brushing against a girl and pretending it's an accident is harm.","relearn":"Deliberate 'accidental' touching of someone is harm.","scene":[{"id":"a","text":"A boy keeps 'accidentally' brushing a girl, ignoring her moving away","trick":true},{"id":"b","text":"Students go up and down","trick":false},{"id":"c","text":"He smirks each time she steps aside","trick":true},{"id":"d","text":"A handrail is loose","trick":false},{"id":"e","text":"A poster peels at one corner","trick":false}]},
  {"id":"su-1277","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / online","hook":"In the gaming chat. Spot what's harmful.","why":"Telling a girl gamer to 'get out, this is for boys' with slurs is online harm.","relearn":"Driving a girl out of a game with gendered slurs is online harm.","scene":[{"id":"a","text":"Players spam a girl with slurs to push her out of the game","trick":true},{"id":"b","text":"The match has six rounds","trick":false},{"id":"c","text":"\"Girls can't play, leave,\" they repeat","trick":true},{"id":"d","text":"Someone shares a strategy tip","trick":false},{"id":"e","text":"The scoreboard updates","trick":false}]},
  {"id":"su-1278","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / shaming","hook":"At assembly. Spot what's harmful.","why":"Mocking a girl's voice as 'too loud for a girl' polices her by gender.","relearn":"Policing a girl's voice as 'unladylike' is gender-based harm.","scene":[{"id":"a","text":"Boys mock a girl for speaking up, calling her 'loud and unladylike'","trick":true},{"id":"b","text":"Lines stand for the anthem","trick":false},{"id":"c","text":"They tell her 'girls should be quiet'","trick":true},{"id":"d","text":"A flag is being raised","trick":false},{"id":"e","text":"A microphone squeaks","trick":false}]},
  {"id":"su-1279","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / threats","hook":"Outside the shop. Spot what's harmful.","why":"Threatening to spread lies about a girl to control her is harm, not a joke.","relearn":"Threatening to spread lies to control a girl is harm.","scene":[{"id":"a","text":"An older boy threatens a girl, saying he'll spread lies if she won't do as he says","trick":true},{"id":"b","text":"The shop sells stationery","trick":false},{"id":"c","text":"He blocks her path until she answers","trick":true},{"id":"d","text":"A cat sits on the step","trick":false},{"id":"e","text":"A bell jingles on the door","trick":false}]},
  {"id":"su-1280","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / exclusion","hook":"In the library. Spot what's harmful.","why":"Snatching books from a girl saying 'study is wasted on girls' is harm.","relearn":"Saying 'study is wasted on girls' and blocking her is exclusion harm.","scene":[{"id":"a","text":"Boys snatch a girl's books, saying 'girls don't need to study'","trick":true},{"id":"b","text":"Shelves are full of books","trick":false},{"id":"c","text":"They hide her notes so she can't revise","trick":true},{"id":"d","text":"A clock ticks on the wall","trick":false},{"id":"e","text":"Someone reads quietly","trick":false}]},
  {"id":"su-1281","cat":"name-the-harm","type":"spot","persona":"Diya","source":"gender-based harm / isolation","hook":"In the friend group. Spot what's harmful.","why":"Turning a whole group against a girl to freeze her out is relational harm.","relearn":"Turning a group against a girl to isolate her is gender-based harm.","scene":[{"id":"a","text":"Girls are told to drop Diya 'or you're out too'","trick":true},{"id":"b","text":"They share a bench at lunch","trick":false},{"id":"c","text":"Anyone who talks to her is mocked","trick":true},{"id":"d","text":"A skipping rope lies nearby","trick":false},{"id":"e","text":"Bags are piled in a corner","trick":false}]},
  {"id":"su-1282","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / online","hook":"On the new app. Spot what's harmful.","why":"An anonymous account sending a girl cruel gendered messages is online harm.","relearn":"Anonymous cruel gendered messages to a girl are online harm.","scene":[{"id":"a","text":"A faceless account floods a girl with gendered insults","trick":true},{"id":"b","text":"The app shows online dots","trick":false},{"id":"c","text":"It threatens to 'find her' if she blocks it","trick":true},{"id":"d","text":"A friend posts a meme","trick":false},{"id":"e","text":"A profile photo is a cartoon","trick":false}]},
  {"id":"su-1283","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / mocking","hook":"In drama club. Spot what's harmful.","why":"Laughing a boy off the dance role because 'dance is for girls' is harm.","relearn":"Mocking a boy off a role for being 'girly' is gender-based harm.","scene":[{"id":"a","text":"Kids laugh a boy out of the dance, jeering 'that's for girls'","trick":true},{"id":"b","text":"Costumes hang on a rack","trick":false},{"id":"c","text":"\"Pick a man's part,\" they sneer","trick":true},{"id":"d","text":"A spotlight is being tested","trick":false},{"id":"e","text":"Scripts are stacked on a chair","trick":false}]},
  {"id":"su-1284","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / appearance","hook":"Near the mirror. Spot what's harmful.","why":"Ranking girls 'pretty or ugly' to their faces reduces them to looks; it's harm.","relearn":"Ranking girls by looks to shame them is gender-based harm.","scene":[{"id":"a","text":"Boys loudly rank passing girls 'pretty or ugly' to their faces","trick":true},{"id":"b","text":"A mirror hangs by the door","trick":false},{"id":"c","text":"They jeer at the ones they call 'ugly'","trick":true},{"id":"d","text":"A bin stands in the corner","trick":false},{"id":"e","text":"Someone fixes their tie","trick":false}]},
  {"id":"su-1285","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / chores-norms","hook":"At home, guests over. Spot what's harmful.","why":"Making only the daughter serve while sons relax sets harm as a 'rule'.","relearn":"Forcing only girls to serve by gender is unfair gender-based harm.","scene":[{"id":"a","text":"Only the daughter is made to serve, scolded that 'boys don't do this'","trick":true},{"id":"b","text":"Guests sit in the front room","trick":false},{"id":"c","text":"She's mocked when she asks her brother to help","trick":true},{"id":"d","text":"Tea is on the stove","trick":false},{"id":"e","text":"Shoes are at the door","trick":false}]},
  {"id":"su-1286","cat":"name-the-harm","type":"spot","persona":"any","source":"gender-based harm / online","hook":"In replies. Spot what's harmful.","why":"Pile-on comments telling a girl to 'go back to the kitchen' are online harm.","relearn":"A pile-on of gendered insults on a girl's post is online harm.","scene":[{"id":"a","text":"Dozens reply 'go back to the kitchen' to a girl's project post","trick":true},{"id":"b","text":"The post has a few likes","trick":false},{"id":"c","text":"They dare each other to write worse","trick":true},{"id":"d","text":"A friend leaves a kind note","trick":false},{"id":"e","text":"The caption mentions a science club","trick":false}]},
  {"id":"su-1287","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm / shapes","hook":"Sort: which shape of harm is this?","relearn":"Harm has shapes: words, leaving-out, touch, and online.","items":[{"id":"a","text":"A gendered slur shouted across the room"},{"id":"b","text":"Never picking a girl for any team"},{"id":"c","text":"Grabbing someone who said stop"},{"id":"d","text":"Forwarding a cruel meme about a classmate"},{"id":"e","text":"'You can't sit here, you're a girl'"},{"id":"f","text":"An anonymous insult sent online"}],"bins":[{"id":"words","label":"Hurtful words","valence":"neg"},{"id":"out","label":"Leaving out","valence":"neg"},{"id":"touch","label":"Unwanted touch","valence":"neg"},{"id":"online","label":"Online harm","valence":"neg"}],"key":{"a":"words","b":"out","c":"touch","d":"online","e":"out","f":"online"}},
  {"id":"su-1288","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm / joke-cover","hook":"Sort: real joke, or harm hiding as a joke?","relearn":"A 'joke' that humiliates by gender is harm, not a joke.","items":[{"id":"a","text":"A riddle the whole class giggles at"},{"id":"b","text":"A 'joke' nickname about a girl's period"},{"id":"c","text":"Teasing a boy 'jokingly' for crying"},{"id":"d","text":"A funny mix-up you both laugh at"},{"id":"e","text":"A 'joke' that a girl 'belongs in the kitchen'"},{"id":"f","text":"A silly pun about the timetable"}],"bins":[{"id":"joke","label":"Real joke","valence":"pos"},{"id":"harm","label":"Harm as 'joke'","valence":"neg"}],"key":{"a":"joke","b":"harm","c":"harm","d":"joke","e":"harm","f":"joke"}},
  {"id":"su-1289","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm / blame","hook":"Sort: naming the harm, or blaming the target?","relearn":"Name the harm and the doer, never blame the one hurt.","items":[{"id":"a","text":"'That slur was cruel and wrong'"},{"id":"b","text":"'She must have asked for it'"},{"id":"c","text":"'He had no right to grab her'"},{"id":"d","text":"'If she dressed differently it wouldn't happen'"},{"id":"e","text":"'Spreading that rumour was harm'"},{"id":"f","text":"'Maybe he provoked them somehow'"}],"bins":[{"id":"name","label":"Names the harm","valence":"tell"},{"id":"blame","label":"Blames the target","valence":"neg"}],"key":{"a":"name","b":"blame","c":"name","d":"blame","e":"name","f":"blame"}},
  {"id":"su-1290","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm / scene-roles","hook":"Sort: who's doing harm and who's helping?","relearn":"A scene has a harm-doer and often an upstander; spot both.","items":[{"id":"a","text":"Shoves a boy for being 'girly'"},{"id":"b","text":"Steps in: 'leave him alone'"},{"id":"c","text":"Spreads a gendered rumour"},{"id":"d","text":"Walks the targeted girl to a teacher"},{"id":"e","text":"Films it to forward later"},{"id":"f","text":"Checks in: 'are you okay?'"}],"bins":[{"id":"harm","label":"Doing harm","valence":"neg"},{"id":"up","label":"Helping (upstander)","valence":"tell"}],"key":{"a":"harm","b":"up","c":"harm","d":"up","e":"harm","f":"up"}},
  {"id":"su-1291","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm / online","hook":"Sort: online harm, or okay online?","relearn":"Cruel gendered posts and forwarding are online harm; kindness is okay.","items":[{"id":"a","text":"Forwarding a mean meme about a girl"},{"id":"b","text":"Sharing a study link with friends"},{"id":"c","text":"Posting an anonymous gendered insult"},{"id":"d","text":"Tagging a friend in a fun photo they like"},{"id":"e","text":"Editing a cruel image of a classmate"},{"id":"f","text":"Wishing a friend happy birthday"}],"bins":[{"id":"harm","label":"Online harm","valence":"neg"},{"id":"ok","label":"Okay online","valence":"pos"}],"key":{"a":"harm","b":"ok","c":"harm","d":"ok","e":"harm","f":"ok"}},
  {"id":"su-1292","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm / seriousness","hook":"Sort: handle with a safe move, or get an adult fast?","relearn":"Loud-but-not-physical: a safe move. Physical or scary: get help fast.","items":[{"id":"a","text":"A one-off mean nickname"},{"id":"b","text":"Someone grabbed and won't let go"},{"id":"c","text":"A teasing comment you can answer calmly"},{"id":"d","text":"A scary threat to hurt a girl"},{"id":"e","text":"Boys hogging the swings"},{"id":"f","text":"An adult being scary and pushy with a kid"}],"bins":[{"id":"safe","label":"Safe move","valence":"tell"},{"id":"adult","label":"Get an adult fast","valence":"uhoh"}],"key":{"a":"safe","b":"adult","c":"safe","d":"adult","e":"safe","f":"adult"}},
  {"id":"su-1293","cat":"name-the-harm","type":"sort","persona":"Diya","source":"naming harm / period","hook":"Sort: harm, or just a normal body fact?","relearn":"Periods are normal; teasing about them is harm.","items":[{"id":"a","text":"Mocking a girl for a period stain"},{"id":"b","text":"Periods are a healthy part of growing up"},{"id":"c","text":"Calling a menstruating girl 'dirty'"},{"id":"d","text":"Quietly lending a friend a pad"},{"id":"e","text":"Whispering 'gross' about her body"},{"id":"f","text":"A nurse explaining the cycle in class"}],"bins":[{"id":"harm","label":"Harm","valence":"neg"},{"id":"normal","label":"Normal / kind","valence":"pos"}],"key":{"a":"harm","b":"normal","c":"harm","d":"normal","e":"harm","f":"normal"}},
  {"id":"su-1294","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm / norms","hook":"Sort: gendered put-down, or fair comment?","relearn":"Put-downs aimed at a gender are harm; fair feedback isn't.","items":[{"id":"a","text":"'Girls can't do maths'"},{"id":"b","text":"'Let's check that answer together'"},{"id":"c","text":"'Boys who cry are weak'"},{"id":"d","text":"'Good effort, try again'"},{"id":"e","text":"'You throw like a girl'"},{"id":"f","text":"'Nice idea, let's build it'"}],"bins":[{"id":"harm","label":"Gendered put-down","valence":"neg"},{"id":"fair","label":"Fair comment","valence":"pos"}],"key":{"a":"harm","b":"fair","c":"harm","d":"fair","e":"harm","f":"fair"}},
  {"id":"su-1295","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm / exclusion","hook":"Sort: shutting out by gender, or including?","relearn":"Shutting someone out by gender is harm; including is the opposite.","items":[{"id":"a","text":"'No girls in this game'"},{"id":"b","text":"'Come join, we need one more'"},{"id":"c","text":"Pushing a girl off the keyboard"},{"id":"d","text":"Saving a seat for the new kid"},{"id":"e","text":"'Boys only at this table'"},{"id":"f","text":"Asking a left-out kid to play"}],"bins":[{"id":"out","label":"Shutting out","valence":"neg"},{"id":"in","label":"Including","valence":"pos"}],"key":{"a":"out","b":"in","c":"out","d":"in","e":"out","f":"in"}},
  {"id":"su-1296","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm / touch","hook":"Sort: respects a 'no', or ignores it?","relearn":"Stopping at 'no' respects it; ignoring 'no' is harm.","items":[{"id":"a","text":"Keeps hugging after 'stop'"},{"id":"b","text":"Lets go the moment they say 'no'"},{"id":"c","text":"'Accidentally' brushing past on purpose"},{"id":"d","text":"Asks 'is a high-five okay?'"},{"id":"e","text":"Grabs a wrist so she can't leave"},{"id":"f","text":"Steps back when waved away"}],"bins":[{"id":"ignore","label":"Ignores 'no'","valence":"neg"},{"id":"respect","label":"Respects 'no'","valence":"pos"}],"key":{"a":"ignore","b":"respect","c":"ignore","d":"respect","e":"ignore","f":"respect"}},
  {"id":"su-1297","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm / online-roles","hook":"Sort: making online harm worse, or stopping it?","relearn":"Forwarding spreads online harm; reporting and not sharing stops it.","items":[{"id":"a","text":"Forwards the cruel meme on"},{"id":"b","text":"Reports the post and tells an adult"},{"id":"c","text":"Adds a nastier caption"},{"id":"d","text":"Refuses to share and saves proof"},{"id":"e","text":"Tags the girl so she sees it"},{"id":"f","text":"Messages her: 'that wasn't fair'"}],"bins":[{"id":"worse","label":"Makes it worse","valence":"neg"},{"id":"stop","label":"Helps stop it","valence":"tell"}],"key":{"a":"worse","b":"stop","c":"worse","d":"stop","e":"worse","f":"stop"}},
  {"id":"su-1298","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm / who-to-blame","hook":"Sort: on the person who did it, or on the target?","relearn":"Harm is always the doer's choice, never the target's fault.","items":[{"id":"a","text":"The boy chose to spread the rumour"},{"id":"b","text":"'She made him do it' (false)"},{"id":"c","text":"The kids chose to exclude her"},{"id":"d","text":"'He deserved the teasing' (false)"},{"id":"e","text":"The one who grabbed is responsible"},{"id":"f","text":"'Her clothes caused it' (false)"}],"bins":[{"id":"doer","label":"On the doer","valence":"pos"},{"id":"target","label":"Blames target (wrong)","valence":"neg"}],"key":{"a":"doer","b":"target","c":"doer","d":"target","e":"doer","f":"target"}},
  {"id":"su-1299","cat":"name-the-harm","type":"sort","persona":"Aarav","source":"naming harm / norms","hook":"Sort: harm to a boy, or just fine?","relearn":"Bullying a boy over gender norms is harm too.","items":[{"id":"a","text":"Shoving a boy for liking dance"},{"id":"b","text":"Cheering a friend's goal"},{"id":"c","text":"'Real boys don't cry'"},{"id":"d","text":"'Want to team up?'"},{"id":"e","text":"Mocking his 'girly' lunchbox"},{"id":"f","text":"'Great catch!'"}],"bins":[{"id":"harm","label":"Harm","valence":"neg"},{"id":"fine","label":"Just fine","valence":"pos"}],"key":{"a":"harm","b":"fine","c":"harm","d":"fine","e":"harm","f":"fine"}},
  {"id":"su-1300","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm / severity-online","hook":"Sort: a safe move handles it, or it needs an adult fast?","relearn":"Most online unkindness: report and block. Scary threats: tell an adult now.","items":[{"id":"a","text":"A single rude comment to ignore and report"},{"id":"b","text":"A scary message threatening to hurt her"},{"id":"c","text":"An unfunny meme you can flag"},{"id":"d","text":"A stranger pressuring a girl to chat in secret"},{"id":"e","text":"A name-call you can block"},{"id":"f","text":"Messages saying 'I'll find you'"}],"bins":[{"id":"safe","label":"Safe move","valence":"tell"},{"id":"adult","label":"Adult, fast","valence":"uhoh"}],"key":{"a":"safe","b":"adult","c":"safe","d":"adult","e":"safe","f":"adult"}},
  {"id":"su-1301","cat":"name-the-harm","type":"sort","persona":"any","source":"naming harm / intent-vs-impact","hook":"Sort: still harm, or genuinely not harm?","relearn":"Harm is about the impact, not whether the doer 'meant it as fun'.","items":[{"id":"a","text":"'I didn't mean it' after humiliating a girl"},{"id":"b","text":"An honest mistake you say sorry for"},{"id":"c","text":"'Just teasing' that left a boy in tears"},{"id":"d","text":"A compliment a friend liked"},{"id":"e","text":"'It was only a joke' about her body"},{"id":"f","text":"Cheering someone up kindly"}],"bins":[{"id":"harm","label":"Still harm","valence":"neg"},{"id":"not","label":"Not harm","valence":"pos"}],"key":{"a":"harm","b":"not","c":"harm","d":"not","e":"harm","f":"not"}},
  {"id":"su-1302","cat":"name-the-harm","type":"strike-rewrite","persona":"any","source":"naming harm / online","hook":"\"It's only online, so it's not real harm.\"","myth":{"un":"Anything online isn't real, so it can't really hurt anyone.","re":"Online insults and shared cruel images hurt a real person.","why":"The screen doesn't make the hurt less real."},"relearn":"Online harm is real harm to a real person."},
  {"id":"su-1303","cat":"name-the-harm","type":"strike-rewrite","persona":"any","source":"naming harm / blame","hook":"\"If she didn't want it, she shouldn't dress that way.\"","myth":{"un":"If a girl is harmed, her clothes must have caused it.","re":"Harm is the choice of the person who does it, never the clothes.","why":"Blaming clothes shifts blame off the one who chose to harm."},"relearn":"What someone wears never makes harm their fault."},
  {"id":"su-1304","cat":"name-the-harm","type":"strike-rewrite","persona":"any","source":"naming harm / exclusion","hook":"\"Leaving girls out of the game is just the rule.\"","myth":{"un":"Keeping girls out of a game is just a rule, not harm.","re":"A 'rule' that shuts someone out by gender is exclusion harm.","why":"Calling unfairness a 'rule' doesn't make it fair."},"relearn":"'No girls allowed' is harm, not a fair rule."},
  {"id":"su-1305","cat":"name-the-harm","type":"strike-rewrite","persona":"Aarav","source":"naming harm / norms","hook":"\"Teasing just toughens a boy up.\"","myth":{"un":"Teasing a boy is harmless; it just toughens him up.","re":"Mocking a boy for being 'girly' is gender-based harm too.","why":"Pain isn't a lesson, and boys feel hurt the same."},"relearn":"Boys are harmed by gendered teasing, not toughened by it."},
  {"id":"su-1306","cat":"name-the-harm","type":"strike-rewrite","persona":"any","source":"naming harm / silence","hook":"\"If nobody complains, nothing harmful happened.\"","myth":{"un":"If no one speaks up, the harm must not have been real.","re":"People often stay silent out of fear; the harm still happened.","why":"Silence can mean fear, not that nothing was wrong."},"relearn":"Harm is real even when no one dares to complain."},
  {"id":"su-1307","cat":"name-the-harm","type":"strike-rewrite","persona":"any","source":"naming harm / online-forward","hook":"\"Forwarding a mean post isn't the same as making it.\"","myth":{"un":"Forwarding a cruel post is harmless; you didn't create it.","re":"Forwarding spreads the harm to more people; that's harm too.","why":"Each share makes the hurt bigger and harder to undo."},"relearn":"Forwarding a cruel post spreads the harm."},
  {"id":"su-1308","cat":"name-the-harm","type":"strike-rewrite","persona":"Diya","source":"naming harm / period","hook":"\"Period jokes are just normal banter.\"","myth":{"un":"Joking about a girl's period is just normal, harmless banter.","re":"Mocking a girl's period shames a normal body; it's harm.","why":"Common doesn't mean okay; it still humiliates her."},"relearn":"Period 'jokes' are body-shaming harm, not banter."},
  {"id":"su-1309","cat":"name-the-harm","type":"strike-rewrite","persona":"any","source":"naming harm / authority","hook":"\"If an older kid does it, it must be allowed.\"","myth":{"un":"If someone older does something, it must be allowed.","re":"Being older never makes harming someone okay.","why":"Age gives no one the right to hurt or control another."},"relearn":"An older kid harming someone is still harm."},
  {"id":"su-1310","cat":"name-the-harm","type":"reflect","persona":"any","source":"naming harm / empathy","hook":"Lensy: think of a time a 'joke' didn't feel funny to you.","prompt":"How did it feel?","options":["It stung","I hid it","I went quiet"],"affirm":"If a 'joke' can hurt you, it can hurt others; that feeling helps you name harm.","relearn":"Your own feelings help you recognise when a 'joke' is really harm."},
  {"id":"su-1311","cat":"name-the-harm","type":"reflect","persona":"any","source":"naming harm / shapes","hook":"Lensy: harm can be words, leaving-out, touch, or online.","prompt":"Which shape do you notice most around you?","options":["Words","Leaving-out","Online"],"affirm":"Noticing the shapes is the first step; every shape you can name, you can help stop.","relearn":"Naming the shape of harm is the first step to stopping it."},
  {"id":"su-1312","cat":"name-the-harm","type":"reflect","persona":"Diya","source":"naming harm / empathy","hook":"Lensy: imagine being teased for something your body just does.","prompt":"What might that feel like?","options":["Embarrassing","Lonely","Unfair"],"affirm":"Bodies change for everyone; teasing about it is harm, and it's never the target's fault.","relearn":"Body-teasing is harm; the person teased is never to blame."},
  {"id":"su-1313","cat":"name-the-harm","type":"reflect","persona":"any","source":"naming harm / hidden-hurt","hook":"Lensy: someone can laugh along and still be hurting inside.","prompt":"How can you tell someone might be hurt?","options":["They go quiet","Forced laugh","They leave"],"affirm":"You can't measure hurt by tears; a laugh can hide real harm worth noticing.","relearn":"A laugh can hide hurt; don't judge harm by tears alone."},
  {"id":"su-1314","cat":"name-the-harm","type":"reflect","persona":"Aarav","source":"naming harm / norms","hook":"Lensy: 'girly' is used as an insult, but it just means 'like a girl'.","prompt":"What does using it as an insult tell us?","options":["It puts girls down","It's unfair","It limits boys"],"affirm":"Turning 'like a girl' into an insult harms everyone; spotting that helps you name the harm.","relearn":"Using 'girly' as an insult is a put-down rooted in gender harm."},
  {"id":"su-1315","cat":"name-the-harm","type":"reflect","persona":"any","source":"naming harm / not-to-blame","hook":"Lensy: when harm happens, whose choice was it?","prompt":"Where does the responsibility sit?","options":["With the doer","Not the target","On who chose it"],"affirm":"Harm is always the doer's choice; the person hurt is never to blame for it.","relearn":"Responsibility for harm sits with the doer, never the target."},
  {"id":"su-1316","cat":"name-the-harm","type":"reflect","persona":"any","source":"naming harm / upstander-eye","hook":"Lensy: in any scene there can be harm and someone helping.","prompt":"What's worth looking for in a scene?","options":["Who's hurt","Who's helping","What's the harm"],"affirm":"Training your eye to spot both the harm and the helper makes you ready to be one.","relearn":"Spotting both the harm and the helper prepares you to act."},
  {"id":"su-1317","cat":"name-the-harm","type":"branch","persona":"any","source":"naming harm / is-it-harm","hook":"Friends laugh at a 'joke' mocking a girl's body. Is it harm?","debrief":"Naming it as harm, even when others laugh, is the first upstander step.","relearn":"A 'joke' that humiliates a girl's body is harm, even if others laugh.","options":[{"text":"Name it: that's body-mocking, not a joke","consequence":"You see the harm clearly and can choose to act.","best":true,"outcome":"upstander"},{"text":"Laugh along so you fit in","consequence":"Laughing along lets the harm look normal; you can name it instead."}]},
  {"id":"su-1318","cat":"name-the-harm","type":"branch","persona":"any","source":"naming harm / not-my-business","hook":"A boy is shoved for being 'girly'. You think it's not your business.","debrief":"Witnessing harm makes it your business too; naming it is where helping starts.","relearn":"Seeing harm makes it your business; naming it is the first step.","options":[{"text":"Recognise it as real harm worth acting on","consequence":"You're ready to step in or get help safely.","best":true,"outcome":"upstander"},{"text":"Decide it's nothing to do with you","consequence":"If you saw harm, it is your business; naming it is the start."}]},
  {"id":"su-1319","cat":"name-the-harm","type":"branch","persona":"any","source":"naming harm / online","hook":"A meme mocking a girl lands in your chat. What do you call it?","debrief":"Naming forwarding as harm stops you adding to it; report and don't share.","relearn":"A cruel gendered meme is online harm; forwarding it spreads the harm.","options":[{"text":"Name it as online harm and don't forward it","consequence":"The harm stops with you, and you can report it.","best":true,"outcome":"upstander"},{"text":"Forward it because 'it's just a meme'","consequence":"Forwarding spreads real harm; naming and not sharing is safer."}]},
  {"id":"su-1320","cat":"name-the-harm","type":"branch","persona":"Diya","source":"naming harm / target-blame","hook":"Kids say Diya 'asked for it' by speaking up. Do you agree?","debrief":"The target is never to blame; harm is always the doer's choice.","relearn":"The person harmed is never to blame; 'they asked for it' is false.","options":[{"text":"Say no one 'asks' to be harmed for speaking","consequence":"You name the harm correctly and don't blame Diya.","best":true,"outcome":"upstander"},{"text":"Agree she brought it on herself","consequence":"No one asks to be harmed; blaming the target is never right."}]},
  {"id":"su-1321","cat":"name-the-harm","type":"branch","persona":"any","source":"naming harm / joke-excuse","hook":"Someone insults a girl, then says 'relax, it's a joke'.","debrief":"The 'joke' label never turns harm into not-harm; the impact is what counts.","relearn":"Calling harm 'a joke' doesn't stop it being harm.","options":[{"text":"Point out the 'joke' still hurt and was harm","consequence":"You refuse the joke-excuse and name the harm.","best":true,"outcome":"upstander"},{"text":"Accept 'it's a joke' and drop it","consequence":"'It's a joke' doesn't undo harm; you can still name it."}]},
  {"id":"su-1322","cat":"name-the-harm","type":"branch","persona":"Aarav","source":"naming harm / freeze","hook":"Aarav freezes seeing a boy teased for being gentle. Then what?","debrief":"Freezing is okay; you still get a second chance to name and act.","relearn":"Freezing is okay; you can still name the harm and act afterwards.","options":[{"text":"Once unfrozen, name it and check on the boy","consequence":"You act through the freeze; that still counts.","best":true,"outcome":"upstander"},{"text":"Decide it's too late since you froze","consequence":"It's never too late; checking in afterwards still helps."}]},
  {"id":"su-1323","cat":"name-the-harm","type":"branch","persona":"any","source":"naming harm / severity","hook":"An adult is making scary advances at a girl. What's this?","debrief":"Scary or physical harm from an adult means get help fast, not handle alone.","relearn":"Serious or scary harm needs an adult or Childline 1098 / 112, fast.","options":[{"text":"Name it as serious and get an adult fast","consequence":"Help comes quickly and safely; you don't face it alone.","best":true,"outcome":"upstander"},{"text":"Try to sort it out by yourself","consequence":"Serious harm needs an adult fast, not a child handling it alone."}]},
  {"id":"su-1324","cat":"name-the-harm","type":"branch","persona":"any","source":"naming harm / rumour","hook":"Friends start a sexual rumour about a classmate 'for fun'.","debrief":"A rumour made to shame someone is harm; refusing to spread it names it.","relearn":"A rumour built to shame a classmate is gender-based harm.","options":[{"text":"Name it as harm and refuse to pass it on","consequence":"The rumour loses its fuel and you can tell an adult.","best":true,"outcome":"upstander"},{"text":"Repeat it since 'everyone's saying it'","consequence":"Repeating spreads the harm; naming and stopping it is better."}]},
  {"id":"su-1325","cat":"name-the-harm","type":"role-play","persona":"any","source":"naming harm / name-it","hook":"A friend calls a slur 'just a joke'. Name what it really is.","setup":"Say it plainly:","yourLine":[{"text":"\"That's not a joke, that's a put-down.\"","best":true},{"text":"\"...\" (let it pass)"}],"relearn":"Naming a 'joke' as a put-down is the first upstander move."},
  {"id":"su-1326","cat":"name-the-harm","type":"role-play","persona":"Diya","source":"naming harm / period","hook":"Boys tease Diya's period stain. Name the harm out loud.","setup":"Say it clear:","yourLine":[{"text":"\"Mocking her body isn't funny, it's mean.\"","best":true},{"text":"\"...\" (look away)"}],"relearn":"Naming body-teasing as harm helps it stop."},
  {"id":"su-1327","cat":"name-the-harm","type":"role-play","persona":"any","source":"naming harm / exclusion","hook":"Kids say 'no girls allowed'. Name it for what it is.","setup":"Say it calm:","yourLine":[{"text":"\"Leaving someone out for being a girl isn't fair.\"","best":true},{"text":"\"...\" (shrug)"}],"relearn":"Naming exclusion as unfair is a strong first step."},
  {"id":"su-1328","cat":"name-the-harm","type":"role-play","persona":"Aarav","source":"naming harm / norms","hook":"Boys mock Aarav for being gentle. Name the harm.","setup":"Say it steady:","yourLine":[{"text":"\"Being kind isn't girly or weak, it's good.\"","best":true},{"text":"\"...\" (say nothing)"}],"relearn":"Naming gendered mockery as harm refuses the put-down."},
  {"id":"su-1329","cat":"name-the-harm","type":"role-play","persona":"any","source":"naming harm / online","hook":"A cruel meme spreads. Name why forwarding is wrong.","setup":"Say it firm:","yourLine":[{"text":"\"Forwarding this just spreads the meanness.\"","best":true},{"text":"\"...\" (forward it)"}],"relearn":"Naming forwarding as harm stops you adding to it."},
  {"id":"su-1330","cat":"name-the-harm","type":"role-play","persona":"any","source":"naming harm / touch","hook":"Someone keeps touching a kid who said stop. Name it.","setup":"Say it clear:","yourLine":[{"text":"\"They said stop, so stop means stop.\"","best":true},{"text":"\"...\" (look down)"}],"relearn":"Naming ignored-'no' as harm backs up the person."},
  {"id":"su-1331","cat":"name-the-harm","type":"role-play","persona":"any","source":"naming harm / blame","hook":"Kids say a teased girl 'asked for it'. Name the truth.","setup":"Say it firmly:","yourLine":[{"text":"\"No one asks to be treated like that.\"","best":true},{"text":"\"...\" (stay quiet)"}],"relearn":"Naming victim-blaming as wrong protects the target."},
  {"id":"su-1332","cat":"name-the-harm","type":"role-play","persona":"any","source":"naming harm / threat","hook":"A boy makes a scary threat to frighten a girl. Name it.","setup":"Say it and get help:","yourLine":[{"text":"\"That's a serious threat, we need an adult.\"","best":true},{"text":"\"...\" (hope it stops)"}],"relearn":"Naming a threat as serious points it to an adult fast."},
  {"id":"su-1333","cat":"name-the-harm","type":"match","persona":"any","source":"naming harm / shapes","hook":"Match the example to the shape of harm.","relearn":"Harm comes in shapes: name them to spot them.","pairs":[{"left":"'You can't play, you're a girl'","right":"Exclusion"},{"left":"A gendered slur to get laughs","right":"Hurtful words"},{"left":"Grabbing after a 'stop'","right":"Unwanted touch"},{"left":"Forwarding a cruel meme","right":"Online harm"},{"left":"Mocking a girl's changing body","right":"Body-mocking"}]},
  {"id":"su-1334","cat":"name-the-harm","type":"match","persona":"any","source":"naming harm / label","hook":"Match the situation to what it really is.","relearn":"Putting the right name to a situation is naming the harm.","pairs":[{"left":"'It's just a joke' after an insult","right":"Harm with an excuse"},{"left":"A kid steps in to help","right":"An upstander"},{"left":"'She asked for it'","right":"Victim-blaming"},{"left":"Telling an adult to keep someone safe","right":"Telling, not tattling"},{"left":"A scary, physical threat","right":"Get-help situation"}]},
  {"id":"su-1335","cat":"name-the-harm","type":"match","persona":"any","source":"naming harm / online-acts","hook":"Match the online act to whether it helps or harms.","relearn":"Forwarding harms; reporting and not sharing helps.","pairs":[{"left":"Forwarding a mean post","right":"Spreads harm"},{"left":"Reporting and not sharing","right":"Helps stop it"},{"left":"Adding a crueller caption","right":"Worsens harm"},{"left":"Saving proof for an adult","right":"A helpful step"},{"left":"Tagging the target to mock","right":"Targets them"}]},
  {"id":"su-1336","cat":"name-the-harm","type":"match","persona":"any","source":"naming harm / who-helps","hook":"Match the serious situation to a safe route to help.","relearn":"Serious or scary harm goes to a trusted adult or Childline 1098 / 112.","pairs":[{"left":"Harm at school","right":"A trusted teacher"},{"left":"Harm at home","right":"A trusted adult or relative"},{"left":"A serious emergency","right":"Childline 1098 / 112"},{"left":"Won't tell parents or teachers","right":"A near-peer educator"},{"left":"Need someone to talk to","right":"A school counsellor"}]},
  {"id":"su-1337","cat":"name-the-harm","type":"match","persona":"any","source":"naming harm / move-fit","hook":"Match the harm to a safe upstander move.","relearn":"Match the move to the moment: direct, distract, get help, check in.","pairs":[{"left":"A clear, safe-to-name taunt","right":"Say something"},{"left":"Direct feels unsafe","right":"Distract"},{"left":"Something scary or physical","right":"Get help"},{"left":"After the moment passes","right":"Check in"},{"left":"A cruel post online","right":"Report it"}]},
  {"id":"su-1338","cat":"name-the-harm","type":"match","persona":"any","source":"naming harm / true-false","hook":"Match each saying to true or false about harm.","relearn":"Spot which sayings about harm are true and which are myths.","pairs":[{"left":"'A joke can still be harm'","right":"True"},{"left":"'Online harm isn't real'","right":"False"},{"left":"'The target is never to blame'","right":"Also true"},{"left":"'Boys can't be harmed'","right":"Also false"},{"left":"'Silence keeps no one safe'","right":"True as well"}]},
  {"id":"su-1339","cat":"name-the-harm","type":"match","persona":"Diya","source":"naming harm / period-facts","hook":"Match the period statement to harm or normal.","relearn":"Periods are normal; teasing about them is harm.","pairs":[{"left":"Mocking a period stain","right":"Harm"},{"left":"Periods are healthy and normal","right":"A body fact"},{"left":"Calling her 'dirty'","right":"Also harm"},{"left":"Quietly lending a pad","right":"A kind act"},{"left":"Whispering 'gross' at her","right":"Harm too"}]},
  {"id":"su-1340","cat":"name-the-harm","type":"match","persona":"any","source":"naming harm / role-in-scene","hook":"Match each person to their role in the scene.","relearn":"A scene has a doer of harm and often an upstander; spot both.","pairs":[{"left":"Shoves a boy for being gentle","right":"Doing harm"},{"left":"Says 'leave him alone'","right":"Upstander"},{"left":"Films it to forward","right":"Making it worse"},{"left":"Walks the kid to a teacher","right":"Getting help"},{"left":"Checks in after","right":"Caring upstander"}]},
  {"id":"su-1350","cat":"why-speak-up","type":"strike-rewrite","hook":"\"It's their fight, not mine.\"","myth":{"un":"If the harm isn't aimed at me, it's not my problem.","re":"Once you see harm, helping is everyone's business.","why":"Looking away leaves the person to face it alone."},"relearn":"Seeing harm makes it your business too.","persona":"any","source":"why speak up / allyship"},
  {"id":"su-1351","cat":"why-speak-up","type":"strike-rewrite","hook":"\"If I say something, I'll just make it worse.\"","myth":{"un":"Speaking up always makes things worse.","re":"A calm word, or fetching an adult, usually helps, not harms.","why":"You can pick a safe move instead of staying silent."},"relearn":"Speaking up safely usually helps; silence rarely does.","persona":"any","source":"why speak up / safety"},
  {"id":"su-1352","cat":"why-speak-up","type":"strike-rewrite","hook":"\"They never told a teacher, so it can't be that bad.\"","myth":{"un":"If the person hasn't told anyone, the harm must be small.","re":"People stay quiet from fear or shame, not because it's fine.","why":"Silence from the target is not proof there's no harm."},"relearn":"Staying quiet often means scared, not okay.","persona":"any","source":"why speak up / bystander"},
  {"id":"su-1353","cat":"why-speak-up","type":"strike-rewrite","hook":"\"There's a whole crowd, someone bigger will sort it.\"","myth":{"un":"In a big crowd, someone else is sure to step in.","re":"In a crowd everyone waits, so often nobody acts.","why":"That's the bystander trap; you can be the first."},"relearn":"In a crowd, be the one who acts first.","persona":"any","source":"why speak up / bystander effect"},
  {"id":"su-1354","cat":"why-speak-up","type":"strike-rewrite","hook":"\"She brought it on herself by sitting with the boys.\"","myth":{"un":"If someone's teased, they must have invited it somehow.","re":"Nobody invites harm by where they sit or what they wear.","why":"Blaming the target lets the teaser off the hook."},"relearn":"Harm is never the target's fault.","persona":"Diya","source":"why speak up / no victim-blaming"},
  {"id":"su-1355","cat":"why-speak-up","type":"strike-rewrite","hook":"\"I'm only a kid, what difference can I make?\"","myth":{"un":"A kid is too small to change anything.","re":"Kids stop harm every day, just by saying stop or fetching help.","why":"Your action counts even when you're young."},"relearn":"You're a kid and your action still counts.","persona":"any","source":"why speak up / kid agency"},
  {"id":"su-1356","cat":"why-speak-up","type":"strike-rewrite","hook":"\"Reporting the group chat is just snitching.\"","myth":{"un":"Telling an adult about a cruel group chat is snitching.","re":"Snitching is to get someone in trouble; telling keeps someone safe.","why":"Saving proof and telling protects the person being targeted."},"relearn":"Telling to keep someone safe is not snitching.","persona":"Asha","source":"why speak up / tattle-vs-tell"},
  {"id":"su-1357","cat":"why-speak-up","type":"strike-rewrite","hook":"\"If I ignore it, it'll blow over on its own.\"","myth":{"un":"Ignoring harm makes it fade away.","re":"Ignored harm often grows, because nobody told it to stop.","why":"Silence can read like permission to keep going."},"relearn":"Ignored harm often grows; silence isn't neutral.","persona":"any","source":"why speak up / silence"},
  {"id":"su-1358","cat":"why-speak-up","type":"strike-rewrite","hook":"\"Boys mocking a boy for crying isn't really harm.\"","myth":{"un":"Teasing a boy for being soft is just normal fun.","re":"Mocking someone for their feelings is harm worth stopping.","why":"It tells everyone watching that being gentle is shameful."},"relearn":"Mocking a boy for being gentle is harm, not fun.","persona":"Aarav","source":"why speak up / gentle is not weak"},
  {"id":"su-1359","cat":"why-speak-up","type":"strike-rewrite","hook":"\"I didn't start it, so it's nothing to do with me.\"","myth":{"un":"If I didn't start the harm, I have no part in it.","re":"A witness who acts can end harm they never started.","why":"You don't have to start it to be the one who stops it."},"relearn":"You can end harm you didn't start.","persona":"any","source":"why speak up / allyship"},
  {"id":"su-1360","cat":"why-speak-up","type":"strike-rewrite","hook":"\"Asking a teacher for help is babyish.\"","myth":{"un":"Needing an adult's help means you're a baby.","re":"Asking for help is a smart, strong move, not a babyish one.","why":"Knowing when to fetch help is real courage."},"relearn":"Asking for help is strong, not babyish.","persona":"Asha","source":"why speak up / help-seeking"},
  {"id":"su-1361","cat":"why-speak-up","type":"strike-rewrite","hook":"\"It's only words, words can't really hurt.\"","myth":{"un":"Mean words are harmless because they're just words.","re":"Cruel words can wound and isolate as much as a shove.","why":"Naming words as harm is why we bother to stop them."},"relearn":"Cruel words are real harm, not 'just words'.","persona":"any","source":"why speak up / naming"},
  {"id":"su-1362","cat":"why-speak-up","type":"strike-rewrite","hook":"\"If everyone's laughing, it must be fine.\"","myth":{"un":"If the whole class laughs, it can't be hurtful.","re":"A crowd laughing doesn't make harm okay for the one hurt.","why":"The person being laughed at still feels alone."},"relearn":"A laughing crowd doesn't make harm okay.","persona":"any","source":"why speak up / bystander"},
  {"id":"su-1363","cat":"why-speak-up","type":"strike-rewrite","hook":"\"My one voice won't change anything anyway.\"","myth":{"un":"One person speaking up is too small to matter.","re":"One voice often gives others the courage to join in.","why":"The first 'stop' breaks the silence for everyone."},"relearn":"One voice can give others courage to join.","persona":"any","source":"why speak up / kid agency"},
  {"id":"su-1364","cat":"why-speak-up","type":"strike-rewrite","hook":"\"Standing with the teased kid will make them a target too.\"","myth":{"un":"Sitting with a teased classmate just makes you a target.","re":"Standing beside someone shows they're not alone, and teasing often fades.","why":"Harm thrives on the target seeming friendless."},"relearn":"Standing with someone shows they aren't alone.","persona":"Diya","source":"why speak up / allyship"},
  {"id":"su-1365","cat":"why-speak-up","type":"strike-rewrite","hook":"\"Telling means I'm scared to handle it myself.\"","myth":{"un":"Getting an adult means you couldn't handle it.","re":"Choosing the safe move is wise, not weak.","why":"For serious harm, fetching help is the strong choice."},"relearn":"Choosing to get help is wise, not weak.","persona":"any","source":"why speak up / help-seeking"},
  {"id":"su-1366","cat":"why-speak-up","type":"strike-rewrite","hook":"\"It happened online, so it isn't real harm.\"","myth":{"un":"Mean things online don't count as real harm.","re":"Online cruelty hurts a real person and is worth reporting.","why":"A screen doesn't make the hurt any less real."},"relearn":"Online cruelty is real harm worth reporting.","persona":"any","source":"why speak up / online"},
  {"id":"su-1367","cat":"why-speak-up","type":"strike-rewrite","hook":"\"If I'd been hurt, I'd want it dealt with quietly.\"","myth":{"un":"The kind thing is to keep someone's harm a quiet secret.","re":"Quietly checking in helps; quietly hiding harm leaves them alone.","why":"Help-seeking, with their trust, beats silence."},"relearn":"Quiet secrecy can leave the hurt person alone.","persona":"any","source":"why speak up / silence"},
  {"id":"su-1368","cat":"why-speak-up","type":"strike-rewrite","hook":"\"They're new here, it's not my job to look out for them.\"","myth":{"un":"Looking out for the new kid isn't your responsibility.","re":"A witness who welcomes a new kid can stop them being a target.","why":"Care isn't only for friends you already have."},"relearn":"Looking out for a new kid is everyone's business.","persona":"any","source":"why speak up / allyship"},
  {"id":"su-1369","cat":"why-speak-up","type":"strike-rewrite","hook":"\"Speaking up will get ME into trouble.\"","myth":{"un":"You'll be the one punished for speaking up.","re":"Calmly naming harm or fetching an adult rarely lands you in trouble.","why":"Helping safely is the opposite of getting into trouble."},"relearn":"Helping safely rarely gets you into trouble.","persona":"any","source":"why speak up / safety"},
  {"id":"su-1370","cat":"why-speak-up","type":"strike-rewrite","hook":"\"They have friends, so they don't need me.\"","myth":{"un":"Someone with friends doesn't need a bystander to step in.","re":"Even kids with friends feel alone when nobody names the harm.","why":"One extra voice saying 'not okay' still matters."},"relearn":"Even kids with friends need someone to speak up.","persona":"any","source":"why speak up / allyship"},
  {"id":"su-1371","cat":"why-speak-up","type":"strike-rewrite","hook":"\"It's a teacher's job, not mine, to stop teasing.\"","myth":{"un":"Stopping teasing is only the teacher's job.","re":"You can act safely now, and fetch a teacher for the serious stuff.","why":"Waiting for an adult leaves the moment to the harm."},"relearn":"You can act now and fetch a teacher too.","persona":"any","source":"why speak up / kid agency"},
  {"id":"su-1372","cat":"why-speak-up","type":"strike-rewrite","hook":"\"If I tell, they'll call me a tattletale forever.\"","myth":{"un":"Tell once and you're a tattletale for life.","re":"Telling to keep someone safe is brave; the name fades, safety stays.","why":"Tattling gets someone in trouble; telling keeps someone safe."},"relearn":"Telling to keep someone safe is brave, not tattling.","persona":"Asha","source":"why speak up / tattle-vs-tell"},
  {"id":"su-1373","cat":"why-speak-up","type":"reflect","hook":"Lensy: think of a time you saw something unfair and stayed quiet.","prompt":"What held you back?","options":["I was scared","I didn't know what to say","I thought someone else would"],"affirm":"Naming what held you back is the first step to acting next time.","relearn":"Knowing what holds you back helps you speak up next time.","persona":"any","source":"why speak up / reflection"},
  {"id":"su-1374","cat":"why-speak-up","type":"reflect","hook":"Lensy: imagine you're the one being teased and the room goes quiet.","prompt":"What would one kind voice mean?","options":["I'd feel less alone","Everything","Like someone saw me"],"affirm":"One voice can change how alone the hurt person feels.","relearn":"One kind voice can make the hurt person feel less alone.","persona":"Diya","source":"why speak up / empathy"},
  {"id":"su-1375","cat":"why-speak-up","type":"reflect","hook":"Lensy: which kind of friend would you want in your corner?","prompt":"Pick what feels true.","options":["One who speaks up","One who sits with me","One who tells an adult"],"affirm":"The friend you'd want is the upstander you can choose to be.","relearn":"You can be the upstander friend you'd want for yourself.","persona":"any","source":"why speak up / identity"},
  {"id":"su-1376","cat":"why-speak-up","type":"reflect","hook":"Lensy: doing nothing can feel safer in the moment.","prompt":"And later?","options":["I'd feel bad","I'd wish I'd acted","I'd remember it"],"affirm":"That uneasy feeling is your fairness compass; it's worth listening to.","relearn":"That uneasy 'I should've acted' feeling is worth listening to.","persona":"any","source":"why speak up / reflection"},
  {"id":"su-1377","cat":"why-speak-up","type":"reflect","hook":"Lensy: courage isn't never feeling scared.","prompt":"What is it then?","options":["Acting even when scared","Doing it anyway","Trying despite fear"],"affirm":"Courage is acting through the fear, not waiting for it to vanish.","relearn":"Courage is acting through fear, not the absence of it.","persona":"Aarav","source":"why speak up / courage"},
  {"id":"su-1378","cat":"why-speak-up","type":"reflect","hook":"Lensy: you don't need a big dramatic rescue to help.","prompt":"What small thing could you do?","options":["Sit beside them","Say 'come with me'","Tell an adult"],"affirm":"Small steady acts are real upstanding; you don't need a grand rescue.","relearn":"Small steady acts count; you don't need a grand rescue.","persona":"any","source":"why speak up / kid agency"},
  {"id":"su-1379","cat":"why-speak-up","type":"reflect","hook":"Lensy: if your little cousin was being left out, what would rise in you?","prompt":"Sit with that feeling.","options":["I'd want to protect them","Anger that it's unfair","I'd step in"],"affirm":"That same care can move you for any kid, not only family.","relearn":"The care you feel for family can extend to any kid.","persona":"any","source":"why speak up / empathy"},
  {"id":"su-1380","cat":"why-speak-up","type":"reflect","hook":"Lensy: silence and saying 'stop' both send a message.","prompt":"Which message do you want to send?","options":["That it's not okay","That I see them","That they're not alone"],"affirm":"Speaking up tells both the target and the room where you stand.","relearn":"Speaking up tells everyone watching that harm isn't okay.","persona":"any","source":"why speak up / identity"},
  {"id":"su-1381","cat":"why-speak-up","type":"reflect","hook":"Lensy: who's a person you'd feel safe telling about harm?","prompt":"Picture them.","options":["A teacher I trust","A parent","Didi or an older cousin"],"affirm":"Knowing your go-to person now means you won't be stuck later.","relearn":"Knowing your trusted person now means you won't be stuck later.","persona":"Asha","source":"why speak up / help-seeking"},
  {"id":"su-1382","cat":"why-speak-up","type":"reflect","hook":"Lensy: an upstander isn't a one-time hero.","prompt":"What is it more like?","options":["A choice you keep making","Who you decide to be","A habit"],"affirm":"Upstanding is a choice you get to make again and again.","relearn":"Being an upstander is a choice you keep making.","persona":"any","source":"why speak up / identity"},
  {"id":"su-1383","cat":"why-speak-up","type":"reflect","hook":"Lensy: you froze last time and the moment passed.","prompt":"What's true about that?","options":["It's okay, I can try again","Freezing happens","Next time I'm readier"],"affirm":"Freezing once doesn't decide who you are; the next moment is a fresh chance.","relearn":"Freezing once is okay; the next moment is a fresh chance.","persona":"Aarav","source":"why speak up / second chance"},
  {"id":"su-1384","cat":"why-speak-up","type":"reflect","hook":"Lensy: think about why you'd bother to speak up at all.","prompt":"What's your reason?","options":["It's the right thing","I'd want it for me","To make it stop"],"affirm":"Holding your own reason makes it easier to act when it's hard.","relearn":"Knowing your own reason makes it easier to act.","persona":"any","source":"why speak up / reflection"},
  {"id":"su-1385","cat":"why-speak-up","type":"reflect","hook":"Lensy: a crowd can make us each feel off the hook.","prompt":"What's one truth there?","options":["I can still choose to act","Crowds freeze people","Being first helps"],"affirm":"In any crowd, your choice to act is still fully yours.","relearn":"In a crowd, your choice to act is still yours.","persona":"any","source":"why speak up / bystander"},
  {"id":"su-1386","cat":"why-speak-up","type":"reflect","hook":"Lensy: what does standing with someone harmed cost, and give?","prompt":"What feels true to you?","options":["Worth it","A bit of nerve, lots of meaning","Friendship"],"affirm":"A little nerve spent can mean everything to the person beside you.","relearn":"A little nerve can mean everything to the person you stand with.","persona":"Diya","source":"why speak up / empathy"},
  {"id":"su-1387","cat":"why-speak-up","type":"sort","hook":"Sort: a real reason to speak up, or a silencing myth?","items":[{"id":"a","text":"It keeps someone from feeling alone"},{"id":"b","text":"\"It's none of my business\""},{"id":"c","text":"Silence can look like permission"},{"id":"d","text":"\"Someone else will do it\""},{"id":"e","text":"Kids stop harm every day"},{"id":"f","text":"\"I'm too young to matter\""}],"bins":[{"id":"reason","label":"Real reason","valence":"pos"},{"id":"myth","label":"Silencing myth","valence":"neg"}],"key":{"a":"reason","b":"myth","c":"reason","d":"myth","e":"reason","f":"myth"},"relearn":"Real reasons to act outweigh the myths that keep us quiet.","persona":"any","source":"why speak up"},
  {"id":"su-1388","cat":"why-speak-up","type":"sort","hook":"Sort: telling to keep safe, or tattling for trouble?","items":[{"id":"a","text":"Reporting a cruel group chat"},{"id":"b","text":"\"Miss, he took my pencil\""},{"id":"c","text":"Telling about a kid being shoved"},{"id":"d","text":"Complaining over a lost game"},{"id":"e","text":"Saying a friend is threatened"},{"id":"f","text":"Tattling to get someone scolded"}],"bins":[{"id":"tell","label":"Telling (safe)","valence":"tell"},{"id":"tattle","label":"Tattling (trouble)","valence":"uhoh"}],"key":{"a":"tell","b":"tattle","c":"tell","d":"tattle","e":"tell","f":"tattle"},"relearn":"Telling keeps someone safe; tattling just gets someone in trouble.","persona":"Asha","source":"why speak up / tattle-vs-tell"},
  {"id":"su-1389","cat":"why-speak-up","type":"sort","hook":"Sort: speaks up, or stays silent?","items":[{"id":"a","text":"\"Hey, that's not okay\""},{"id":"b","text":"Pretending not to notice"},{"id":"c","text":"Walking the kid to a teacher"},{"id":"d","text":"Looking down at your shoes"},{"id":"e","text":"Asking 'are you okay?' after"},{"id":"f","text":"Scrolling your phone instead"}],"bins":[{"id":"speak","label":"Speaks up","valence":"tell"},{"id":"silent","label":"Stays silent","valence":"neg"}],"key":{"a":"speak","b":"silent","c":"speak","d":"silent","e":"speak","f":"silent"},"relearn":"Speaking up takes many forms; silence has just as many.","persona":"any","source":"why speak up"},
  {"id":"su-1390","cat":"why-speak-up","type":"sort","hook":"Sort: makes the harm grow, or helps it stop?","items":[{"id":"a","text":"A bystander says 'stop'"},{"id":"b","text":"Others cheer the teaser on"},{"id":"c","text":"Someone fetches an adult"},{"id":"d","text":"The crowd films it"},{"id":"e","text":"Friends close ranks around the target"},{"id":"f","text":"Nobody says a word"}],"bins":[{"id":"stop","label":"Helps it stop","valence":"pos"},{"id":"grow","label":"Makes it grow","valence":"neg"}],"key":{"a":"stop","b":"grow","c":"stop","d":"grow","e":"stop","f":"grow"},"relearn":"What the watchers do decides if harm grows or stops.","persona":"any","source":"why speak up / bystander"},
  {"id":"su-1391","cat":"why-speak-up","type":"sort","hook":"Sort: true about speaking up, or false?","items":[{"id":"a","text":"Asking for help is strong"},{"id":"b","text":"\"It's just a joke, so it's fine\""},{"id":"c","text":"You can be the first to act"},{"id":"d","text":"\"The target must have asked for it\""},{"id":"e","text":"One voice can spark others"},{"id":"f","text":"\"Online harm doesn't count\""}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"false","label":"False","valence":"neg"}],"key":{"a":"true","b":"false","c":"true","d":"false","e":"true","f":"false"},"relearn":"Speaking up is strong and counts; the excuses for silence are false.","persona":"any","source":"why speak up"},
  {"id":"su-1392","cat":"why-speak-up","type":"sort","hook":"Sort: keeps the target company, or leaves them alone?","items":[{"id":"a","text":"Saving them a seat"},{"id":"b","text":"Moving away from them"},{"id":"c","text":"Walking home together"},{"id":"d","text":"Joining the kids who tease"},{"id":"e","text":"Messaging 'I'm with you'"},{"id":"f","text":"Pretending you didn't see"}],"bins":[{"id":"with","label":"Keeps them company","valence":"pos"},{"id":"alone","label":"Leaves them alone","valence":"neg"}],"key":{"a":"with","b":"alone","c":"with","d":"alone","e":"with","f":"alone"},"relearn":"Standing close, on or offline, tells the target they're not alone.","persona":"Diya","source":"why speak up / allyship"},
  {"id":"su-1393","cat":"why-speak-up","type":"sort","hook":"Sort: a brave act, or just going along?","items":[{"id":"a","text":"Naming the harm calmly"},{"id":"b","text":"Laughing because everyone is"},{"id":"c","text":"Fetching a teacher for a shove"},{"id":"d","text":"Forwarding the mean meme"},{"id":"e","text":"Checking in after"},{"id":"f","text":"Staying quiet to fit in"}],"bins":[{"id":"brave","label":"Brave act","valence":"tell"},{"id":"along","label":"Going along","valence":"neg"}],"key":{"a":"brave","b":"along","c":"brave","d":"along","e":"brave","f":"along"},"relearn":"Brave is naming harm and helping; going along is the easy quiet.","persona":"any","source":"why speak up"},
  {"id":"su-1394","cat":"why-speak-up","type":"sort","hook":"Sort: a reason kids CAN act, or an excuse not to?","items":[{"id":"a","text":"A short 'stop' can break the moment"},{"id":"b","text":"\"I'm only a kid\""},{"id":"c","text":"You can fetch an adult"},{"id":"d","text":"\"It's not my fight\""},{"id":"e","text":"Distracting is a safe option"},{"id":"f","text":"\"I'll just make it worse\""}],"bins":[{"id":"can","label":"Reason you CAN","valence":"pos"},{"id":"excuse","label":"Excuse not to","valence":"neg"}],"key":{"a":"can","b":"excuse","c":"can","d":"excuse","e":"can","f":"excuse"},"relearn":"There are always safe ways to act; the excuses don't hold up.","persona":"any","source":"why speak up / kid agency"},
  {"id":"su-1428","cat":"why-speak-up","type":"sort","hook":"Sort: a courage move, or a fear move?","items":[{"id":"a","text":"Saying 'stop' even though you're nervous"},{"id":"b","text":"Staying quiet so nobody notices you"},{"id":"c","text":"Fetching help for something scary"},{"id":"d","text":"Pretending you didn't see it"},{"id":"e","text":"Trying again after you froze"},{"id":"f","text":"Hoping it sorts itself out"}],"bins":[{"id":"courage","label":"Courage move","valence":"tell"},{"id":"fear","label":"Fear move","valence":"uhoh"}],"key":{"a":"courage","b":"fear","c":"courage","d":"fear","e":"courage","f":"fear"},"relearn":"Courage is acting through fear, not waiting for it to pass.","persona":"Aarav","source":"why speak up / courage"},
  {"id":"su-1395","cat":"why-speak-up","type":"branch","hook":"Kids chant a gendered nickname at a classmate. Others laugh.","options":[{"text":"Say 'not cool, stop' and wave the kid over to you","consequence":"The chant fizzles and they aren't left alone.","outcome":"upstander","best":true},{"text":"Laugh quietly so you blend in","consequence":"Going along feeds the crowd; a calm 'stop' helps more."}],"debrief":"In a crowd, the first calm 'stop' often breaks the moment.","relearn":"Being the first to say 'stop' can break the moment.","persona":"any","source":"why speak up / bystander"},
  {"id":"su-1396","cat":"why-speak-up","type":"branch","hook":"A classmate forwards you a mean photo of a girl with a cruel caption.","options":[{"text":"Don't forward; screenshot as proof and tell an adult","consequence":"The chain stops with you and an adult can help her.","outcome":"report","best":true},{"text":"Forward it to one friend 'just so they know'","consequence":"Every forward spreads the harm; save proof and tell instead."}],"debrief":"The safe move online: don't forward, save proof, tell an adult.","relearn":"For online harm: don't forward, save proof, tell an adult.","persona":"any","source":"why speak up / online"},
  {"id":"su-1397","cat":"why-speak-up","type":"branch","hook":"You're new here and see a boy mocked for crying. Nobody acts.","options":[{"text":"Go sit beside him and quietly say 'you okay?'","consequence":"He feels less alone and the mockers lose their audience.","outcome":"upstander","best":true},{"text":"Wait for a popular kid to step in first","consequence":"If everyone waits, no one acts; you can be the first."}],"debrief":"You don't have to be popular or old to be the first to help.","relearn":"You can be the first to act, even as the new kid.","persona":"Aarav","source":"why speak up / kid agency"},
  {"id":"su-1398","cat":"why-speak-up","type":"branch","hook":"A group keeps shutting Diya out of the game 'because she's a girl'.","options":[{"text":"Pass her the ball and say 'she's playing, come on'","consequence":"Including her ends the exclusion, no confrontation needed.","outcome":"upstander","best":true},{"text":"Feel bad for her but keep playing","consequence":"Feeling bad doesn't help her; one welcoming line can."}],"debrief":"Including someone who's shut out is itself a strong upstander move.","relearn":"Including an excluded kid is an upstander move.","persona":"Diya","source":"why speak up / allyship"},
  {"id":"su-1399","cat":"why-speak-up","type":"branch","hook":"You half-saw something at the back of the bus. Not sure it was harm.","options":[{"text":"Check in quietly: 'hey, you alright back there?'","consequence":"If something's wrong you'll know; if not, no harm done.","outcome":"upstander","best":true},{"text":"Decide it's nothing and turn around","consequence":"A quiet check costs nothing; ignoring a 'maybe' lets harm grow."}],"debrief":"A calm check-in on a 'maybe' is safe and often exactly right.","relearn":"It's better to check a 'maybe' than to ignore real harm.","persona":"any","source":"why speak up"},
  {"id":"su-1400","cat":"why-speak-up","type":"branch","hook":"You want to help but worry the bullies will turn on you next.","options":[{"text":"Pick a safe move: distract them or fetch a teacher","consequence":"You help and stay safe; upstanding isn't fighting.","outcome":"smart","best":true},{"text":"Confront them loudly on your own","consequence":"Going head-on alone isn't safe; distract or get help instead."}],"debrief":"You always have a safe option; helping never means fighting alone.","relearn":"You can help safely without confronting anyone alone.","persona":"any","source":"why speak up / safety"},
  {"id":"su-1401","cat":"why-speak-up","type":"branch","hook":"Your friend says 'don't tell anyone' about being threatened online.","options":[{"text":"Stay by them and say a trusted adult can help keep them safe","consequence":"They're not alone and a grown-up can stop the threats.","outcome":"upstander","best":true},{"text":"Promise to keep the threats a total secret","consequence":"Secret threats can grow; telling an adult keeps them safe."}],"debrief":"For real threats, telling a trusted adult keeps a friend safe.","relearn":"Telling about threats keeps a friend safe.","persona":"Asha","source":"why speak up / help-seeking"},
  {"id":"su-1402","cat":"why-speak-up","type":"branch","hook":"A teacher walks in as kids mock a classmate, but doesn't notice.","options":[{"text":"Quietly tell the teacher what you saw after class","consequence":"The teacher can step in; telling keeps your classmate safe.","outcome":"upstander","best":true},{"text":"Say nothing so you're not called a tattletale","consequence":"Telling to keep someone safe isn't tattling; it's right."}],"debrief":"Telling an adult what they missed is help-seeking, not tattling.","relearn":"Telling what an adult missed is help-seeking, not tattling.","persona":"any","source":"why speak up / tattle-vs-tell"},
  {"id":"su-1403","cat":"why-speak-up","type":"branch","hook":"The whole field watches one kid get teased, waiting for someone to act.","options":[{"text":"Call out 'hey, that's enough' and wave the kid over","consequence":"Your first move gives others the nerve to back you up.","outcome":"upstander","best":true},{"text":"Keep waiting for an older kid to handle it","consequence":"When everyone waits, no one acts; one voice can start it."}],"debrief":"The first voice in a frozen crowd often unfreezes everyone else.","relearn":"One voice can give a frozen crowd the nerve to act.","persona":"any","source":"why speak up / bystander effect"},
  {"id":"su-1404","cat":"why-speak-up","type":"spot","hook":"At the school gate. Spot the silencing myths (the false bits).","scene":[{"id":"a","text":"\"It's not my problem if it's not me\"","trick":true},{"id":"b","text":"Seeing harm makes it your business too","trick":false},{"id":"c","text":"\"I'm too young to change anything\"","trick":true},{"id":"d","text":"One voice can give others courage","trick":false},{"id":"e","text":"Asking for help is a strong move","trick":false}],"why":"The myths say silence is fine; the truths say your voice matters.","relearn":"Spotting the silencing myths is how you stop believing them.","persona":"any","source":"why speak up"},
  {"id":"su-1405","cat":"why-speak-up","type":"spot","hook":"In the WhatsApp class group. Spot the false ideas.","scene":[{"id":"a","text":"\"It's online, so it isn't real harm\"","trick":true},{"id":"b","text":"Online cruelty hurts a real person","trick":false},{"id":"c","text":"Don't forward it; save proof and tell an adult","trick":false},{"id":"d","text":"\"Forwarding it is just sharing news\"","trick":true},{"id":"e","text":"Reporting harm isn't snitching","trick":false}],"why":"A screen doesn't make harm fake; forwarding spreads it, reporting stops it.","relearn":"Online harm is real; report it, don't forward it.","persona":"any","source":"why speak up / online"},
  {"id":"su-1406","cat":"why-speak-up","type":"spot","hook":"On the playground. Spot the victim-blaming (the false bits).","scene":[{"id":"a","text":"\"She must have done something to deserve it\"","trick":true},{"id":"b","text":"Harm is never the target's fault","trick":false},{"id":"c","text":"\"He asked for it by being soft\"","trick":true},{"id":"d","text":"The person doing harm chose to do it","trick":false},{"id":"e","text":"Standing with the target helps them","trick":false}],"why":"Blaming the target just excuses the one doing the harm.","relearn":"Harm is never the target's fault; blame belongs to the harm-doer.","persona":"any","source":"why speak up / no victim-blaming"},
  {"id":"su-1407","cat":"why-speak-up","type":"spot","hook":"In the canteen. Spot what tells the harm to keep going.","scene":[{"id":"a","text":"The crowd laughs along","trick":true},{"id":"b","text":"A kid says 'okay, that's enough'","trick":false},{"id":"c","text":"Someone films it for a laugh","trick":true},{"id":"d","text":"A friend sits down beside the target","trick":false},{"id":"e","text":"Another kid fetches a teacher","trick":false}],"why":"Laughing and filming feed the harm; naming it or getting help stops it.","relearn":"Laughing and filming feed harm; naming or fetching help stops it.","persona":"any","source":"why speak up / bystander"},
  {"id":"su-1408","cat":"why-speak-up","type":"spot","hook":"Tattle or tell? Spot the two that are really just tattling.","scene":[{"id":"a","text":"\"Miss, he took the last chalk\"","trick":true},{"id":"b","text":"Telling about a kid being threatened","trick":false},{"id":"c","text":"\"She's complaining I lost the game\"","trick":true},{"id":"d","text":"Reporting a cruel group chat","trick":false},{"id":"e","text":"Saying a classmate is being shoved","trick":false}],"why":"Tattling gets someone in trouble; telling keeps someone safe.","relearn":"Telling keeps someone safe; tattling just gets someone in trouble.","persona":"Asha","source":"why speak up / tattle-vs-tell"},
  {"id":"su-1409","cat":"why-speak-up","type":"spot","hook":"Spot the safe upstander moves (the false bits are the unsafe ideas).","scene":[{"id":"a","text":"\"Just fight whoever's being mean\"","trick":true},{"id":"b","text":"Fetch a teacher for anything scary","trick":false},{"id":"c","text":"\"Chase them down on your own\"","trick":true},{"id":"d","text":"Distract to break the moment","trick":false},{"id":"e","text":"Check in with the person afterwards","trick":false}],"why":"Helping is never fighting or chasing alone; the safe moves do the work.","relearn":"Upstanding is never fighting alone; pick a safe move.","persona":"any","source":"why speak up / safety"},
  {"id":"su-1410","cat":"why-speak-up","type":"spot","hook":"Spot the excuses that keep kids quiet (the false bits).","scene":[{"id":"a","text":"\"Someone else will surely step in\"","trick":true},{"id":"b","text":"In a crowd, you can be the first","trick":false},{"id":"c","text":"\"My one voice won't matter\"","trick":true},{"id":"d","text":"One voice can spark others to join","trick":false},{"id":"e","text":"A short 'stop' can end the moment","trick":false}],"why":"The excuses keep us frozen; the truths show your voice counts.","relearn":"The excuses keep us frozen; your voice counts.","persona":"any","source":"why speak up / bystander effect"},
  {"id":"su-1411","cat":"why-speak-up","type":"spot","hook":"Spot the bits that get 'why speak up' WRONG.","scene":[{"id":"a","text":"\"Silence is the safe, neutral choice\"","trick":true},{"id":"b","text":"Silence can leave the target alone","trick":false},{"id":"c","text":"\"If it's a joke, it can't be harm\"","trick":true},{"id":"d","text":"A hurtful joke is still harm","trick":false},{"id":"e","text":"Speaking up is everyone's business","trick":false}],"why":"Silence isn't neutral, and 'just a joke' never makes harm okay.","relearn":"Silence isn't neutral; 'just a joke' doesn't excuse harm.","persona":"any","source":"why speak up"},
  {"id":"su-1412","cat":"why-speak-up","type":"role-play","hook":"A friend whispers 'don't get involved, it's not our problem'.","setup":"You answer your friend. Say:","yourLine":[{"text":"\"If we see it, it kind of is our problem. Let's help.\"","best":true},{"text":"\"Yeah, you're right, let's just go.\""}],"relearn":"Seeing harm makes it your business; you can say so out loud.","persona":"any","source":"why speak up / allyship"},
  {"id":"su-1413","cat":"why-speak-up","type":"role-play","hook":"Someone calls you a snitch for wanting to tell a teacher about a threat.","setup":"You hold your ground. Say:","yourLine":[{"text":"\"Telling to keep someone safe isn't snitching.\"","best":true},{"text":"\"Fine, I won't say anything then.\""}],"relearn":"Telling to keep someone safe is brave, not snitching.","persona":"Asha","source":"why speak up / tattle-vs-tell"},
  {"id":"su-1414","cat":"why-speak-up","type":"role-play","hook":"Your friend says 'we're just kids, leave it to the adults'.","setup":"You push back gently. Say:","yourLine":[{"text":"\"We can do a safe bit now and tell an adult too.\"","best":true},{"text":"\"True, there's nothing we can do.\""}],"relearn":"Kids can act safely now and still bring in adults.","persona":"any","source":"why speak up / kid agency"},
  {"id":"su-1415","cat":"why-speak-up","type":"role-play","hook":"The teased kid mutters 'it's fine, I'm used to it'.","setup":"You let them know they matter. Say:","yourLine":[{"text":"\"You shouldn't have to get used to it. I've got your back.\"","best":true},{"text":"\"Okay, if you say it's fine.\""}],"relearn":"Nobody should 'get used to' harm; saying so helps them feel seen.","persona":"Diya","source":"why speak up / empathy"},
  {"id":"su-1416","cat":"why-speak-up","type":"role-play","hook":"You froze last time and the moment passed. It's happening again.","setup":"You give yourself the line to start. Say:","yourLine":[{"text":"\"Hey, that's enough.\"","best":true},{"text":"\"...\" (stay frozen again)"}],"relearn":"Freezing once is okay; a short line gives you a second chance.","persona":"Aarav","source":"why speak up / second chance"},
  {"id":"su-1417","cat":"why-speak-up","type":"role-play","hook":"A classmate says 'everyone's laughing, so it's clearly fine'.","setup":"You name the truth. Say:","yourLine":[{"text":"\"A crowd laughing doesn't make it okay for them.\"","best":true},{"text":"\"Guess so, if everyone thinks it's funny.\""}],"relearn":"A laughing crowd doesn't make harm okay for the one hurt.","persona":"any","source":"why speak up / bystander"},
  {"id":"su-1418","cat":"why-speak-up","type":"role-play","hook":"Someone says 'why bother, your one voice won't change anything'.","setup":"You answer. Say:","yourLine":[{"text":"\"One voice can get others to join in. I'll start.\"","best":true},{"text":"\"You're probably right, what's the point.\""}],"relearn":"One voice can give others the courage to join in.","persona":"any","source":"why speak up / kid agency"},
  {"id":"su-1419","cat":"why-speak-up","type":"role-play","hook":"A friend says 'just delete the mean post and forget it'.","setup":"You suggest the safer move. Say:","yourLine":[{"text":"\"Let's not forward it. Screenshot it and tell an adult.\"","best":true},{"text":"\"Yeah, just delete it, whatever.\""}],"relearn":"For online harm: don't forward, save proof, tell an adult.","persona":"any","source":"why speak up / online"},
  {"id":"su-1420","cat":"why-speak-up","type":"match","hook":"Match the silencing myth to its truth.","pairs":[{"left":"\"Not my business\"","right":"Seeing harm makes it yours too"},{"left":"\"Someone else will act\"","right":"You can be the one who acts first"},{"left":"\"Telling is tattling\"","right":"Telling keeps someone safe"},{"left":"\"I'm too young to matter\"","right":"Kids stop harm every day"},{"left":"\"Silence is neutral\"","right":"Silence can leave the target alone"}],"relearn":"Every silencing myth has a truth that frees you to act.","persona":"any","source":"why speak up"},
  {"id":"su-1421","cat":"why-speak-up","type":"match","hook":"Match each excuse to why it doesn't hold.","pairs":[{"left":"\"I'll make it worse\"","right":"A safe move usually helps, not harms"},{"left":"\"It's just a joke\"","right":"A hurtful joke is still harm"},{"left":"\"Online doesn't count\"","right":"Online cruelty hurts a real person"},{"left":"\"They deserved it\"","right":"Harm is never the target's fault"},{"left":"\"One voice won't matter\"","right":"One voice can spark others"}],"relearn":"Each excuse for silence has a clear answer.","persona":"any","source":"why speak up"},
  {"id":"su-1422","cat":"why-speak-up","type":"match","hook":"Match the small act to the message it sends the target.","pairs":[{"left":"Sitting beside them","right":"You're not alone"},{"left":"Saying 'that's not okay'","right":"This isn't your fault"},{"left":"Walking them to a teacher","right":"Help is on the way"},{"left":"Checking in after","right":"Someone noticed you"},{"left":"Sharing your snack","right":"You belong here"}],"relearn":"Even small acts send a clear message: you're not alone.","persona":"Diya","source":"why speak up / empathy"},
  {"id":"su-1423","cat":"why-speak-up","type":"match","hook":"Match what a silent bystander does to what an upstander does instead.","pairs":[{"left":"Looks away","right":"Looks and names the harm"},{"left":"Laughs along","right":"Says 'that's enough'"},{"left":"Films it","right":"Reports it to an adult"},{"left":"Waits for someone else","right":"Acts first"},{"left":"Walks off","right":"Walks the target to safety"}],"relearn":"For every bystander move, there's an upstander move you can choose.","persona":"any","source":"why speak up"},
  {"id":"su-1424","cat":"why-speak-up","type":"match","hook":"Match the worry that stops you to a way through it.","pairs":[{"left":"\"It might get worse\"","right":"Pick a safe move, like fetching help"},{"left":"\"They'll turn on me\"","right":"Distract instead of confronting"},{"left":"\"I froze last time\"","right":"You get a second chance"},{"left":"\"I don't know the words\"","right":"A short 'stop' is enough"},{"left":"\"I'm scared to tell alone\"","right":"Bring a friend with you"}],"relearn":"Every worry that holds you back has a safe way through.","persona":"any","source":"why speak up / safety"},
  {"id":"su-1425","cat":"why-speak-up","type":"match","hook":"Match what's true about speaking up to why it matters.","pairs":[{"left":"Silence isn't neutral","right":"It can leave the target alone"},{"left":"You can be the first","right":"Others often follow your lead"},{"left":"Asking for help is strong","right":"Knowing your limits is wise"},{"left":"Your action counts","right":"Kids stop harm every day"},{"left":"Telling keeps people safe","right":"It's not the same as tattling"}],"relearn":"The reasons to speak up are stronger than the reasons to stay quiet.","persona":"any","source":"why speak up"},
  {"id":"su-1426","cat":"why-speak-up","type":"match","hook":"Match the moment to a safe first move.","pairs":[{"left":"A scary, physical fight","right":"Get a teacher or trusted adult"},{"left":"A cruel online post","right":"Save proof, don't forward"},{"left":"Loud teasing, no danger","right":"Calmly say 'that's not okay'"},{"left":"After it's over","right":"Check in: 'are you okay?'"},{"left":"Too scared to tell alone","right":"Bring a friend to tell with you"}],"relearn":"Different moments call for different safe first moves.","persona":"any","source":"why speak up / five moves"},
  {"id":"su-1427","cat":"why-speak-up","type":"match","hook":"Match the situation to the right helper.","pairs":[{"left":"Harm during a lesson","right":"A trusted teacher"},{"left":"Something scary at home","right":"A trusted adult or relative"},{"left":"A serious emergency","right":"Childline 1098 / 112"},{"left":"You won't tell parents","right":"A near-peer educator like Asha"},{"left":"Need a private listen","right":"The school counsellor"}],"relearn":"There's a right helper for every situation; know who to turn to.","persona":"Asha","source":"why speak up / help-seeking"},
];

